        imgId: 'brand-logo-img',
        badgeId: 'brand-logo-badge',
        className: 'brand-logo-img hidden',
        inlineStyle:
          'max-height:50px;max-width:210px;width:auto;height:auto;object-fit:contain;background:transparent;padding:0;border-radius:0;flex-shrink:0;'
