    function populateAdminPublicWebsiteCmsFormPhase6(cmsData) {
      if (!cmsData || typeof cmsData !== 'object') return;
      currentAdminPublicCmsState = cmsData;

      var dekCfg = cmsData.dekConfig || {
        mode: 'AUTO_YEAR',
        baseDekNumber: 70,
        cohorts: ['DEK70', 'DEK71', 'DEK72'],
        staticGreetingText: 'Welcome, DEK70, DEK71 & DEK72'
      };
      setInputValue('select-admin-cms-dek-mode', dekCfg.mode || 'AUTO_YEAR');
      setInputValue('input-admin-cms-dek-base', String(dekCfg.baseDekNumber || 70));

      var dekBadge = document.getElementById('admin-cms-dek-preview-badge');
      if (dekBadge) {
        dekBadge.textContent =
          'Active Cohorts (' +
          (dekCfg.mode === 'MANUAL_OVERRIDE' ? 'Manual' : 'Auto Year') +
          '): ' +
          (Array.isArray(dekCfg.cohorts) ? dekCfg.cohorts.join(', ') : 'DEK70, DEK71, DEK72');
      }

      var statusBadge = document.getElementById('admin-cms-status-badge');
      if (statusBadge) {
        if (cmsData.hasUnpublishedDraft) {
          statusBadge.className = 'badge badge-incomplete';
          statusBadge.textContent = 'Unpublished Draft Saved';
        } else if (cmsData.rawPublishedJson) {
          statusBadge.className = 'badge badge-ok';
          statusBadge.textContent = 'Custom Published Copy Live';
        } else {
          statusBadge.className = 'badge badge-ok';
          statusBadge.textContent = 'Default Owner Copy Live';
        }
      }

      /* Academic Year 180-Day Verification Reminder Bar */
      var acad = cmsData.academicYearVerification || {};
      var reminderBar = document.getElementById('admin-instructor-academic-reminder-bar');
      if (reminderBar) {
        reminderBar.classList.toggle('is-verified', !acad.needsAnnualReview);
      }
      if (acad.reminderMessage) {
        setText('admin-instructor-academic-reminder-text', acad.reminderMessage);
      }

      /* Instructor Portrait Thumbnail Preview */
      var portFileId = cmsData.instructorPortraitFileId || '';
      setText(
        'admin-instructor-portrait-file-id-code',
        portFileId ? portFileId : 'None (Default Academic Crest)'
      );
      var portObj = cmsData.instructorPortrait || {};
      var thumbImg = document.getElementById('admin-instructor-portrait-thumb-img');
      var thumbFb = document.getElementById('admin-instructor-portrait-thumb-fallback');
      var portStatusBadge = document.getElementById('admin-instructor-portrait-status-badge');
      if (portObj.available && portObj.dataUri && thumbImg && thumbFb) {
        thumbImg.setAttribute('src', portObj.dataUri);
        thumbImg.classList.remove('hidden');
        thumbFb.classList.add('hidden');
        if (portStatusBadge) {
          portStatusBadge.className = 'badge badge-ok';
          portStatusBadge.textContent = 'Custom Portrait Active (' + (portObj.mimeType || 'Image') + ')';
        }
      } else {
        if (thumbImg) {
          thumbImg.removeAttribute('src');
          thumbImg.classList.add('hidden');
        }
        if (thumbFb) {
          thumbFb.classList.remove('hidden');
          thumbFb.textContent = portFileId
            ? 'Fallback Crest (' + (portObj.fallbackReason || 'UNAVAILABLE') + ')'
            : 'No Portrait Uploaded (Crest Active)';
        }
        if (portStatusBadge) {
          portStatusBadge.className = portFileId ? 'badge badge-incomplete' : 'badge badge-ok';
          portStatusBadge.textContent = portFileId
            ? 'Fallback Crest (' + (portObj.fallbackReason || 'ERROR') + ')'
            : 'Academic Crest Default';
        }
      }

      /* Hero Shuffle Cards (1, 2, 3) Admin Preview Thumbnails */
      var heroCardsArr = Array.isArray(cmsData.heroShuffleCards) ? cmsData.heroShuffleCards : [];
      var defaultFallbacks = [
        'Default Vesicle Illustration',
        'Default DNA Helix Illustration',
        'Default Mitochondrion Illustration'
      ];
      var customHeroCount = 0;
      for (var hcSlot = 1; hcSlot <= 3; hcSlot++) {
        var cardItem = null;
        for (var hci = 0; hci < heroCardsArr.length; hci++) {
          if (heroCardsArr[hci] && Number(heroCardsArr[hci].slotIndex) === hcSlot) {
            cardItem = heroCardsArr[hci];
            break;
          }
        }
        if (!cardItem && heroCardsArr[hcSlot - 1]) {
          cardItem = heroCardsArr[hcSlot - 1];
        }
        var hcFileId = (cardItem && cardItem.fileId) || '';
        setText(
          'admin-hero-card-file-id-' + String(hcSlot),
          hcFileId ? hcFileId : 'Default SVG'
        );
        var hcImg = document.getElementById('admin-hero-card-thumb-img-' + String(hcSlot));
        var hcFb = document.getElementById('admin-hero-card-thumb-fallback-' + String(hcSlot));
        if (cardItem && cardItem.available && cardItem.dataUri && hcImg && hcFb) {
          customHeroCount++;
          hcImg.setAttribute('src', cardItem.dataUri);
          hcImg.classList.remove('hidden');
          hcFb.classList.add('hidden');
        } else {
          var defaultHeroSvgs = [
            'data:image/svg+xml;utf8,' + encodeURIComponent('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 200"><defs><linearGradient id="g1" x1="0" y1="0" x2="1" y2="1"><stop offset="0%" stop-color="#CCFBF1"/><stop offset="100%" stop-color="#E0F2FE"/></linearGradient></defs><rect width="320" height="200" rx="14" fill="url(#g1)"/><circle cx="160" cy="92" r="46" fill="#99F6E4" stroke="#0D9488" stroke-width="3.5"/><circle cx="160" cy="92" r="28" fill="#F0FDFA" stroke="#14B8A6" stroke-width="2" stroke-dasharray="5 4"/><circle cx="148" cy="84" r="6" fill="#0F766E"/><circle cx="172" cy="98" r="5" fill="#0284C7"/><circle cx="156" cy="104" r="4" fill="#10B981"/><text x="160" y="168" text-anchor="middle" font-family="sans-serif" font-size="13" font-weight="700" fill="#0F766E">Default Vesicle Illustration</text></svg>'),
            'data:image/svg+xml;utf8,' + encodeURIComponent('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 200"><defs><linearGradient id="g2" x1="0" y1="0" x2="1" y2="1"><stop offset="0%" stop-color="#E0F2FE"/><stop offset="100%" stop-color="#DCFCE7"/></linearGradient></defs><rect width="320" height="200" rx="14" fill="url(#g2)"/><path d="M90 60 C135 60, 135 124, 180 124 C210 124, 210 60, 235 60" fill="none" stroke="#0D9488" stroke-width="4" stroke-linecap="round"/><path d="M90 124 C135 124, 135 60, 180 60 C210 60, 210 124, 235 124" fill="none" stroke="#0284C7" stroke-width="4" stroke-linecap="round"/><line x1="112" y1="68" x2="112" y2="116" stroke="#14B8A6" stroke-width="2.5"/><line x1="160" y1="68" x2="160" y2="116" stroke="#14B8A6" stroke-width="2.5"/><line x1="206" y1="68" x2="206" y2="116" stroke="#14B8A6" stroke-width="2.5"/><text x="160" y="168" text-anchor="middle" font-family="sans-serif" font-size="13" font-weight="700" fill="#0F766E">Default DNA Helix Illustration</text></svg>'),
            'data:image/svg+xml;utf8,' + encodeURIComponent('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 200"><defs><linearGradient id="g3" x1="0" y1="0" x2="1" y2="1"><stop offset="0%" stop-color="#DCFCE7"/><stop offset="100%" stop-color="#CCFBF1"/></linearGradient></defs><rect width="320" height="200" rx="14" fill="url(#g3)"/><ellipse cx="160" cy="92" rx="68" ry="38" fill="#99F6E4" stroke="#0D9488" stroke-width="3.5"/><path d="M106 92 Q122 68 134 92 T160 92 T186 92 T214 92" fill="none" stroke="#0F766E" stroke-width="3" stroke-linecap="round"/><text x="160" y="168" text-anchor="middle" font-family="sans-serif" font-size="13" font-weight="700" fill="#0F766E">Default Mitochondrion Illustration</text></svg>')
          ];
          if (hcImg) {
            hcImg.setAttribute('src', defaultHeroSvgs[hcSlot - 1] || defaultHeroSvgs[0]);
            hcImg.classList.remove('hidden');
          }
          if (hcFb) {
            hcFb.classList.add('hidden');
            hcFb.textContent = defaultFallbacks[hcSlot - 1] || 'Default Illustration';
          }
        }
      }
      var heroBadgeEl = document.getElementById('admin-hero-cards-status-badge');
      if (heroBadgeEl) {
        heroBadgeEl.className = 'badge badge-ok';
        heroBadgeEl.textContent =
          customHeroCount > 0
            ? String(customHeroCount) + '/3 Custom Card Images Active'
            : 'Default 3-Card Illustrations Active';
      }
      if (heroCardsArr.length > 0) {
        applyHeroShuffleCardsPhase8(heroCardsArr);
      }

      /* Populate Copy Inputs from Draft (or Published / Default) */
      var activeCopy = cmsData.draftContent || cmsData.publishedContent || cmsData.defaultContent || {};
      var hero = activeCopy.hero || {};
      var about = activeCopy.aboutUs || {};
      var paras = Array.isArray(about.paragraphs) ? about.paragraphs : [];
      var inst = activeCopy.instructorProfile || {};
      var awards = Array.isArray(inst.awards) ? inst.awards : [];

      setInputValue('input-admin-cms-hero-eyebrow', hero.eyebrow || '');
      setInputValue('input-admin-cms-hero-lead', hero.lead || '');
      setInputValue('input-admin-cms-about-subtitle', about.subtitle || '');
      setInputValue('input-admin-cms-about-p1', paras[0] || '');
      setInputValue('input-admin-cms-about-p2', paras[1] || '');
      setInputValue('input-admin-cms-about-p3', paras[2] || '');
      setInputValue('input-admin-cms-instructor-headline', inst.headlineBadge || '');
      setInputValue('input-admin-cms-instructor-education', inst.education || '');
      setInputValue('input-admin-cms-instructor-awards', awards.join('\n'));
      setInputValue('input-admin-cms-instructor-experience', inst.teachingExperience || '');
    }

    function collectAdminPublicWebsiteCmsFormPayloadPhase6(mode) {
      var dekModeEl = document.getElementById('select-admin-cms-dek-mode');
      var dekBaseEl = document.getElementById('input-admin-cms-dek-base');
      var awardsRaw = document.getElementById('input-admin-cms-instructor-awards')
        ? document.getElementById('input-admin-cms-instructor-awards').value
        : '';
      var awardsLines = String(awardsRaw || '')
        .split(/\r?\n/)
        .map(function (s) {
          return String(s || '').trim();
        })
        .filter(function (s) {
          return s.length > 0;
        });

      return {
        mode: mode || 'PUBLISH',
        dekDisplayMode: dekModeEl ? dekModeEl.value : 'AUTO_YEAR',
        dekManualBaseNumber: dekBaseEl ? Number(dekBaseEl.value || 70) : 70,
        contentOverrides: {
          heroEyebrow: document.getElementById('input-admin-cms-hero-eyebrow')
            ? document.getElementById('input-admin-cms-hero-eyebrow').value.trim()
            : '',
          heroLead: document.getElementById('input-admin-cms-hero-lead')
            ? document.getElementById('input-admin-cms-hero-lead').value.trim()
            : '',
          aboutSubtitle: document.getElementById('input-admin-cms-about-subtitle')
            ? document.getElementById('input-admin-cms-about-subtitle').value.trim()
            : '',
          aboutParagraph1: document.getElementById('input-admin-cms-about-p1')
            ? document.getElementById('input-admin-cms-about-p1').value.trim()
            : '',
          aboutParagraph2: document.getElementById('input-admin-cms-about-p2')
            ? document.getElementById('input-admin-cms-about-p2').value.trim()
            : '',
          aboutParagraph3: document.getElementById('input-admin-cms-about-p3')
            ? document.getElementById('input-admin-cms-about-p3').value.trim()
            : '',
          instructorHeadlineBadge: document.getElementById('input-admin-cms-instructor-headline')
            ? document.getElementById('input-admin-cms-instructor-headline').value.trim()
            : '',
          instructorEducation: document.getElementById('input-admin-cms-instructor-education')
            ? document.getElementById('input-admin-cms-instructor-education').value.trim()
            : '',
          instructorAwards: awardsLines,
          instructorTeachingExperience: document.getElementById('input-admin-cms-instructor-experience')
            ? document.getElementById('input-admin-cms-instructor-experience').value.trim()
            : ''
        }
      };
    }

    function handleAdminSavePublicWebsiteCmsPhase6(mode) {
      hideUiErrorBanner();
      setAdminCmsAlertPhase6('hidden');
      var payload = collectAdminPublicWebsiteCmsFormPayloadPhase6(mode);
      setText('admin-cms-save-status', 'Saving Public Website CMS (' + mode + ')...');

      return rpcCallEnvelope('admin.savePublicWebsiteContent', payload)
        .then(function (envelope) {
          var d = envelope.data || {};
          currentAdminSettingsVersions = d.versions || currentAdminSettingsVersions;
          if (d.publicWebsiteCms) {
            populateAdminPublicWebsiteCmsFormPhase6(d.publicWebsiteCms);
            if (mode === 'PUBLISH' || mode === 'RESET_DEFAULT') {
              applyPublicWebsiteContentPhase3({
                bangkokYear: d.publicWebsiteCms.dekConfig
                  ? d.publicWebsiteCms.dekConfig.bangkokYear
                  : 2026,
                dekConfig: d.publicWebsiteCms.dekConfig,
                publicContent: d.publicWebsiteCms.publishedContent,
                instructorPortrait: d.publicWebsiteCms.instructorPortrait
              });
            }
          }
          setText('admin-cms-save-status', d.savedMessage || 'Public Website CMS updated.');
          setAdminCmsAlertPhase6(
            'success',
            mode === 'PUBLISH'
              ? 'Published to Live Website'
              : mode === 'SAVE_DRAFT'
              ? 'Draft Saved'
              : mode === 'RESET_DEFAULT'
              ? 'Restored Default Owner Copy'
              : 'Academic Year Verified',
            d.savedMessage || ''
          );
          PBNotify.toast(
            'success',
            mode === 'PUBLISH' ? 'Public Website Published' : 'CMS Updated',
            d.savedMessage || ''
          );
          return d;
        })
        .catch(function (err) {
          setText(
            'admin-cms-save-status',
            'Error (' + (err.code || 'ERR') + '): ' + (err.message || '')
          );
          setAdminCmsAlertPhase6(
            'danger',
            'Public Website CMS Save Failed (' + (err.code || 'ERR') + ')',
            err.message || ''
          );
          throw err;
        });
    }

    function handleAdminPreviewDraftOnHomePagePhase6() {
      var formPayload = collectAdminPublicWebsiteCmsFormPayloadPhase6('SAVE_DRAFT');
      var ov = formPayload.contentOverrides || {};
      var bkkYear =
        currentBootstrapData && currentBootstrapData.bangkokYear
          ? currentBootstrapData.bangkokYear
          : 2026;
      var firstDek =
        formPayload.dekDisplayMode === 'MANUAL_OVERRIDE'
          ? Math.max(60, Math.min(150, Math.floor(Number(formPayload.dekManualBaseNumber) || 70)))
          : 70 + (bkkYear - 2026);
      var cohorts = [
        'DEK' + String(firstDek),
        'DEK' + String(firstDek + 1),
        'DEK' + String(firstDek + 2)
      ];
      var previewDekCfg = {
        bangkokYear: bkkYear,
        mode: formPayload.dekDisplayMode,
        baseDekNumber: firstDek,
        cohorts: cohorts,
        staticGreetingText: 'Welcome, ' + cohorts[0] + ', ' + cohorts[1] + ' & ' + cohorts[2],
        ariaLabelText: 'Welcome, ' + cohorts[0] + ', ' + cohorts[1] + ', and ' + cohorts[2]
      };
      var previewContent = {
        dek: previewDekCfg,
        hero: {
          eyebrow: ov.heroEyebrow || 'Online Learning Platform',
          lead: ov.heroLead || ''
        },
        aboutUs: {
          subtitle: ov.aboutSubtitle || '',
          paragraphs: [ov.aboutParagraph1 || '', ov.aboutParagraph2 || '', ov.aboutParagraph3 || '']
        },
        instructorProfile: {
          headlineBadge: ov.instructorHeadlineBadge || '',
          education: ov.instructorEducation || '',
          awards: Array.isArray(ov.instructorAwards) ? ov.instructorAwards : [],
          teachingExperience: ov.instructorTeachingExperience || ''
        }
      };
      applyPublicWebsiteContentPhase3({
        bangkokYear: bkkYear,
        dekConfig: previewDekCfg,
        publicContent: previewContent,
        instructorPortrait:
          currentAdminPublicCmsState && currentAdminPublicCmsState.instructorPortrait
            ? currentAdminPublicCmsState.instructorPortrait
            : null
      });
      handleNavigateToView('landing');
      PBNotify.toast(
        'info',
        'Previewing Draft on Public Home Page',
        'Return to Admin > School Settings and click "Publish to Live Website" when ready to make this copy permanent.'
      );
    }

    /* ========================================================================
     * PHASE 6: STUDENT ASSESSMENT SCORE PUBLISHING WORKSPACE CONTROLLERS
     * ======================================================================== */
    function setAdminScoresAlertPhase6(variant, title, message) {
      var box = document.getElementById('admin-scores-alert-box');
      if (!box) return;
      if (variant === 'hidden') {
        box.classList.add('hidden');
        return;
      }
      box.className = 'banner banner-' + (variant || 'danger');
      setText('admin-scores-alert-title', title || 'Score Publishing Notice');
      setText('admin-scores-alert-message', message || '');
      box.classList.remove('hidden');
      if (typeof PBNotify === 'object' && PBNotify && typeof PBNotify.toast === 'function') {
        PBNotify.toast(variant || 'danger', title || 'Score Publishing Notice', message || '');
      }
    }

    function populateAdminScorePublisherDropdownsPhase6() {
      var courseSel = document.getElementById('select-admin-score-course');
      var filterCourseSel = document.getElementById('select-admin-scores-filter-course');
      var asmSel = document.getElementById('select-admin-score-assessment');
      var studentSel = document.getElementById('select-admin-score-student');

      if (courseSel) {
        var prevCourse = courseSel.value;
        clearChildren(courseSel);
        var defC = document.createElement('option');
        defC.value = '';
        defC.textContent = '— Select Course —';
        courseSel.appendChild(defC);
        var courses = Array.isArray(currentAdminCoursesList) && currentAdminCoursesList.length > 0
          ? currentAdminCoursesList
          : currentAdminAvailableCourses || [];
        for (var c = 0; c < courses.length; c++) {
          var cr = courses[c];
          var optC = document.createElement('option');
          optC.value = cr.courseId;
          optC.textContent =
            '[' + (cr.courseCode || cr.courseId) + '] ' + (cr.title || 'Course') + ' (' + (cr.status || 'PUBLISHED') + ')';
          courseSel.appendChild(optC);
        }
        if (prevCourse) {
          courseSel.value = prevCourse;
        } else if (courses.length > 0) {
          courseSel.value = courses[0].courseId;
        }
      }

      if (filterCourseSel) {
        var prevFilterCourse = filterCourseSel.value;
        clearChildren(filterCourseSel);
        var allC = document.createElement('option');
        allC.value = '';
        allC.textContent = 'All Courses';
        filterCourseSel.appendChild(allC);
        var fCourses = Array.isArray(currentAdminCoursesList) && currentAdminCoursesList.length > 0
          ? currentAdminCoursesList
          : currentAdminAvailableCourses || [];
        for (var fc = 0; fc < fCourses.length; fc++) {
          var fcr = fCourses[fc];
          var fOpt = document.createElement('option');
          fOpt.value = fcr.courseId;
          fOpt.textContent = '[' + (fcr.courseCode || fcr.courseId) + '] ' + (fcr.title || 'Course');
          filterCourseSel.appendChild(fOpt);
        }
        if (prevFilterCourse) {
          filterCourseSel.value = prevFilterCourse;
        }
      }

      if (asmSel) {
        var prevAsm = asmSel.value;
        clearChildren(asmSel);
        var defA = document.createElement('option');
        defA.value = '';
        defA.textContent = '— Select Assessment —';
        asmSel.appendChild(defA);
        var asms = currentAdminAssessmentsList || [];
        for (var a = 0; a < asms.length; a++) {
          var am = asms[a];
          var optA = document.createElement('option');
          optA.value = am.assessmentId;
          optA.textContent = (am.title || am.assessmentId) + ' (' + (am.status || 'ACTIVE') + ')';
          asmSel.appendChild(optA);
        }
        if (prevAsm) {
          asmSel.value = prevAsm;
        } else if (asms.length > 0) {
          asmSel.value = asms[0].assessmentId;
        }
      }

      if (studentSel) {
        var prevStu = studentSel.value;
        clearChildren(studentSel);
        var defS = document.createElement('option');
        defS.value = '';
        defS.textContent = '— Select Student —';
        studentSel.appendChild(defS);
        var users = currentAdminUsersCache || [];
        var studentCount = 0;
        for (var u = 0; u < users.length; u++) {
          var usr = users[u];
          if (usr.role !== 'STUDENT') continue;
          studentCount++;
          var optS = document.createElement('option');
          optS.value = usr.userId;
          optS.textContent =
            (usr.fullName || usr.username) + ' (@' + usr.username + ' — ' + (usr.status || 'ACTIVE') + ')';
          studentSel.appendChild(optS);
        }
        if (prevStu) {
          studentSel.value = prevStu;
        } else if (studentCount > 0 && studentSel.options.length > 1) {
          studentSel.selectedIndex = 1;
        }
      }
    }

    function resetAdminScoreEditorFormPhase6() {
      setInputValue('input-admin-score-id', '');
      setInputValue('input-admin-score-version', '');
      setInputValue('input-admin-score-points', '');
      setInputValue('input-admin-score-max-points', '50');
      setInputValue('input-admin-score-feedback', '');
      setInputValue('select-admin-score-status', 'PUBLISHED');
      setText('admin-score-editor-status', '');
      setAdminScoresAlertPhase6('hidden');
      PBNotify.clearAllFieldErrors(document.getElementById('form-admin-score-editor'));

      var modeBadge = document.getElementById('admin-score-editor-mode-badge');
      if (modeBadge) {
        modeBadge.className = 'badge badge-ok';
        modeBadge.textContent = 'Record New / Upsert Assessment Score';
      }
      var verBadge = document.getElementById('admin-score-editor-version-badge');
      if (verBadge) {
        verBadge.textContent = 'Version: New / Upsert (v1)';
      }
    }

    function selectScoreForAdminEditingPhase6(scoreDto) {
      if (!scoreDto || !scoreDto.scoreId) {
        resetAdminScoreEditorFormPhase6();
        return;
      }
      populateAdminScorePublisherDropdownsPhase6();

      var studentSel = document.getElementById('select-admin-score-student');
      if (studentSel && scoreDto.studentUserId) {
        var hasOpt = false;
        for (var i = 0; i < studentSel.options.length; i++) {
          if (studentSel.options[i].value === scoreDto.studentUserId) {
            hasOpt = true;
            break;
          }
        }
        if (!hasOpt) {
          var dynOpt = document.createElement('option');
          dynOpt.value = scoreDto.studentUserId;
          dynOpt.textContent =
            (scoreDto.studentFullName || scoreDto.studentUsername || scoreDto.studentUserId) +
            (scoreDto.studentUsername ? ' (@' + scoreDto.studentUsername + ')' : '');
          studentSel.appendChild(dynOpt);
        }
      }

      setInputValue('input-admin-score-id', scoreDto.scoreId);
      setInputValue('input-admin-score-version', String(scoreDto.version || 1));
      setInputValue('select-admin-score-course', scoreDto.courseId || '');
      setInputValue('select-admin-score-assessment', scoreDto.assessmentId || '');
      setInputValue('select-admin-score-student', scoreDto.studentUserId || '');
      setInputValue('select-admin-score-status', scoreDto.status || 'PUBLISHED');
      setInputValue('input-admin-score-points', String(scoreDto.scorePoints || '0'));
      setInputValue('input-admin-score-max-points', String(scoreDto.maxPoints || '50'));
      setInputValue('input-admin-score-feedback', scoreDto.feedbackText || '');

      var modeBadge = document.getElementById('admin-score-editor-mode-badge');
      if (modeBadge) {
        modeBadge.className = 'badge badge-incomplete';
        modeBadge.textContent =
          'Editing Score ' +
          scoreDto.scoreId +
          ' (' +
          (scoreDto.studentFullName || scoreDto.studentUsername || scoreDto.studentUserId) +
          ')';
      }
      var verBadge = document.getElementById('admin-score-editor-version-badge');
      if (verBadge) {
        verBadge.textContent = 'Version: v' + String(scoreDto.version || 1);
      }
    }

    function renderAdminAssessmentScoresTablePhase6(scoresList) {
      var tbody = document.getElementById('admin-scores-table-tbody');
      if (!tbody) return;
      clearChildren(tbody);

      var list = Array.isArray(scoresList) ? scoresList : [];
      var pubCount = 0;
      var draftCount = 0;
      for (var k = 0; k < list.length; k++) {
        if (list[k].status === 'PUBLISHED') pubCount++;
        else if (list[k].status === 'DRAFT') draftCount++;
      }
      setText('admin-scores-kpi-total', String(list.length));
      setText('admin-scores-kpi-published', String(pubCount));
      setText('admin-scores-kpi-draft', String(draftCount));

      if (list.length === 0) {
        var emptyTr = document.createElement('tr');
        var emptyTd = document.createElement('td');
        emptyTd.colSpan = 6;
        emptyTd.textContent =
          'No student assessment scores match the current filter. Use the form above to record and publish student scores.';
        emptyTr.appendChild(emptyTd);
        tbody.appendChild(emptyTr);
        return;
      }

      for (var i = 0; i < list.length; i++) {
        (function (sc) {
          var tr = document.createElement('tr');

          /* Col 1: Student */
          var tdStu = document.createElement('td');
          var stuStrong = document.createElement('strong');
          stuStrong.textContent = sc.studentFullName || sc.studentUsername || sc.studentUserId;
          tdStu.appendChild(stuStrong);
          if (sc.studentUsername) {
            var stuSub = document.createElement('div');
            stuSub.style.fontSize = '0.78rem';
            stuSub.style.color = 'var(--pb-text-muted)';
            stuSub.textContent = '@' + sc.studentUsername + ' (' + sc.studentUserId + ')';
            tdStu.appendChild(stuSub);
          }
          tr.appendChild(tdStu);

          /* Col 2: Course & Assessment */
          var tdCourse = document.createElement('td');
          var cBadge = document.createElement('span');
          cBadge.className = 'badge badge-ok';
          cBadge.textContent = sc.courseCode || sc.courseId;
          tdCourse.appendChild(cBadge);
          var asmDiv = document.createElement('div');
          asmDiv.style.fontWeight = '600';
          asmDiv.style.marginTop = '4px';
          asmDiv.textContent = sc.assessmentTitle || sc.assessmentId;
          tdCourse.appendChild(asmDiv);
          tr.appendChild(tdCourse);

          /* Col 3: Score & Percentage */
          var tdScore = document.createElement('td');
          var scoreMain = document.createElement('div');
          scoreMain.style.fontWeight = '800';
          scoreMain.style.fontVariantNumeric = 'tabular-nums';
          scoreMain.style.color = 'var(--pb-brand-deep)';
          scoreMain.textContent = sc.scoreDisplay || (sc.scorePoints + ' / ' + sc.maxPoints);
          tdScore.appendChild(scoreMain);
          var pctSub = document.createElement('div');
          pctSub.style.fontSize = '0.8rem';
          pctSub.style.fontWeight = '700';
          pctSub.style.color = 'var(--pb-brand-primary)';
          pctSub.textContent = sc.percentageFormatted || '';
          tdScore.appendChild(pctSub);
          tr.appendChild(tdScore);

          /* Col 4: Status */
          var tdStatus = document.createElement('td');
          var stBadge = document.createElement('span');
          stBadge.className =
            sc.status === 'PUBLISHED'
              ? 'badge badge-ok'
              : sc.status === 'DRAFT'
              ? 'badge badge-incomplete'
              : 'badge badge-danger';
          stBadge.textContent = sc.status || 'DRAFT';
          tdStatus.appendChild(stBadge);
          tr.appendChild(tdStatus);

          /* Col 5: Feedback & Updated */
          var tdMeta = document.createElement('td');
          if (sc.feedbackText) {
            var fbP = document.createElement('div');
            fbP.style.fontSize = '0.84rem';
            fbP.style.marginBottom = '4px';
            fbP.textContent = sc.feedbackText;
            tdMeta.appendChild(fbP);
          }
          var timeSub = document.createElement('div');
          timeSub.style.fontSize = '0.76rem';
          timeSub.style.color = 'var(--pb-text-muted)';
          timeSub.textContent =
            (sc.publishedAtBangkok
              ? 'Published: ' + sc.publishedAtBangkok
              : 'Updated: ' + (sc.updatedAtBangkok || sc.updatedAtUtc || '-')) +
            ' (v' +
            String(sc.version || 1) +
            ')';
          tdMeta.appendChild(timeSub);
          tr.appendChild(tdMeta);

          /* Col 6: Actions */
          var tdAct = document.createElement('td');
          var actWrap = document.createElement('div');
          actWrap.style.display = 'flex';
          actWrap.style.gap = '6px';
          actWrap.style.flexWrap = 'wrap';

          var editBtn = document.createElement('button');
          editBtn.type = 'button';
          editBtn.className = 'btn btn-secondary btn-sm';
          editBtn.textContent = 'Edit';
          editBtn.addEventListener('click', function () {
            selectScoreForAdminEditingPhase6(sc);
            PBAdminActionModal.open('form-admin-score-editor', 'Edit Score: ' + (sc.studentFullName || sc.studentUsername || sc.scoreId));
          });
          actWrap.appendChild(editBtn);

          var toggleBtn = document.createElement('button');
          toggleBtn.type = 'button';
          toggleBtn.className =
            sc.status === 'PUBLISHED' ? 'btn btn-outline btn-sm' : 'btn btn-primary btn-sm';
          toggleBtn.textContent =
            sc.status === 'PUBLISHED' ? 'Revert to Draft' : 'Publish Score';
          toggleBtn.addEventListener('click', function () {
            var nextStatus = sc.status === 'PUBLISHED' ? 'DRAFT' : 'PUBLISHED';
            withButtonAndAreaLoading(toggleBtn, tr, function () {
              return handleAdminQuickToggleScoreStatusPhase6(sc, nextStatus);
            });
          });
          actWrap.appendChild(toggleBtn);

          tdAct.appendChild(actWrap);
          tr.appendChild(tdAct);
          tbody.appendChild(tr);
        })(list[i]);
      }
    }

    function loadAdminAssessmentScoresPhase6() {
      if (
        !currentSessionMeta ||
        !currentSessionMeta.user ||
        currentSessionMeta.user.role !== 'ADMIN' ||
        currentSessionMeta.user.requiresPrivacyAck
      ) {
        return Promise.resolve();
      }
      var filterCourseEl = document.getElementById('select-admin-scores-filter-course');
      var filterStatusEl = document.getElementById('select-admin-scores-filter-status');

      return rpcCallEnvelope(
        'admin.listAssessmentScores',
        {
          courseId: filterCourseEl ? filterCourseEl.value : '',
          status: filterStatusEl ? filterStatusEl.value : 'ALL'
        },
        { suppressErrorBanner: true }
      )
        .then(function (envelope) {
          var d = envelope.data || {};
          currentAdminScoresList = d.scores || [];
          renderAdminAssessmentScoresTablePhase6(currentAdminScoresList);
          return currentAdminScoresList;
        })
        .catch(function (err) {
          if (
            isLogoutInProgress ||
            !currentSessionMeta ||
            !currentSessionMeta.user ||
            (err && (err.code === 'ERR_AUTH_REQUIRED' || err.suppressedDuringLogout))
          ) {
            setAdminScoresAlertPhase6('hidden');
            return [];
          }
          setAdminScoresAlertPhase6(
            'danger',
            'Could Not Load Assessment Scores (' + (err.code || 'ERR') + ')',
            err.message || ''
          );
        });
    }

    function handleAdminSaveAssessmentScoreSubmitPhase6(evt) {
      if (evt && typeof evt.preventDefault === 'function') {
        evt.preventDefault();
      }
      hideUiErrorBanner();
      setAdminScoresAlertPhase6('hidden');
      var formEl = document.getElementById('form-admin-score-editor');
      PBNotify.clearAllFieldErrors(formEl);

      var scoreId = document.getElementById('input-admin-score-id')
        ? document.getElementById('input-admin-score-id').value.trim()
        : '';
      var expectedVersion = document.getElementById('input-admin-score-version')
        ? Number(document.getElementById('input-admin-score-version').value || 0)
        : 0;
      var courseEl = document.getElementById('select-admin-score-course');
      var asmEl = document.getElementById('select-admin-score-assessment');
      var stuEl = document.getElementById('select-admin-score-student');
      var statusEl = document.getElementById('select-admin-score-status');
      var ptsEl = document.getElementById('input-admin-score-points');
      var maxEl = document.getElementById('input-admin-score-max-points');
      var fbEl = document.getElementById('input-admin-score-feedback');

      var courseId = courseEl ? courseEl.value.trim() : '';
      var assessmentId = asmEl ? asmEl.value.trim() : '';
      var studentUserId = stuEl ? stuEl.value.trim() : '';
      var status = statusEl ? statusEl.value.trim() : 'PUBLISHED';
      var scorePoints = ptsEl ? ptsEl.value.trim() : '';
      var maxPoints = maxEl ? maxEl.value.trim() : '';
      var feedbackText = fbEl ? fbEl.value.trim() : '';

      var hasClientError = false;
      if (!courseId && courseEl) {
        PBNotify.setFieldError(courseEl, 'Please select a course.');
        hasClientError = true;
      }
      if (!assessmentId && asmEl) {
        PBNotify.setFieldError(asmEl, 'Please select an assessment item.');
        hasClientError = true;
      }
      if (!studentUserId && stuEl) {
        PBNotify.setFieldError(stuEl, 'Please select a student account.');
        hasClientError = true;
      }
      if (!scorePoints && ptsEl) {
        PBNotify.setFieldError(ptsEl, 'Please enter the earned score points.');
        hasClientError = true;
      }
      if (!maxPoints && maxEl) {
        PBNotify.setFieldError(maxEl, 'Please enter the maximum possible points.');
        hasClientError = true;
      }
      if (hasClientError) {
        return Promise.resolve();
      }

      setText('admin-score-editor-status', 'Saving student assessment score...');
      return rpcCallEnvelope('admin.saveAssessmentScore', {
        scoreId: scoreId,
        expectedVersion: expectedVersion || undefined,
        courseId: courseId,
        assessmentId: assessmentId,
        studentUserId: studentUserId,
        status: status,
        scorePoints: scorePoints,
        maxPoints: maxPoints,
        feedbackText: feedbackText
      })
        .then(function (envelope) {
          var d = envelope.data || {};
          setText('admin-score-editor-status', d.savedMessage || 'Score saved.');
          PBNotify.toast(
            'success',
            'Assessment Score Saved',
            d.savedMessage || 'Updated student assessment score.'
          );
          resetAdminScoreEditorFormPhase6();
          PBAdminActionModal.close();
          return loadAdminAssessmentScoresPhase6();
        })
        .catch(function (err) {
          setText(
            'admin-score-editor-status',
            'Error (' + (err.code || 'ERR') + '): ' + (err.message || '')
          );
          setAdminScoresAlertPhase6(
            'danger',
            'Score Save Rejected (' + (err.code || 'ERR') + ')',
            err.message || ''
          );
        });
    }

    function handleAdminQuickToggleScoreStatusPhase6(scoreDto, nextStatus) {
      if (!scoreDto || !scoreDto.scoreId) return Promise.resolve();
      setAdminScoresAlertPhase6('hidden');
      return rpcCallEnvelope('admin.saveAssessmentScore', {
        scoreId: scoreDto.scoreId,
        expectedVersion: Number(scoreDto.version || 1),
        courseId: scoreDto.courseId,
        assessmentId: scoreDto.assessmentId,
        studentUserId: scoreDto.studentUserId,
        scorePoints: String(scoreDto.scorePoints || '0'),
        maxPoints: String(scoreDto.maxPoints || '50'),
        feedbackText: scoreDto.feedbackText || '',
        status: nextStatus
      })
        .then(function (envelope) {
          var d = envelope.data || {};
          PBNotify.toast(
            'success',
            nextStatus === 'PUBLISHED' ? 'Score Published to Student' : 'Score Reverted to Draft',
            d.savedMessage || ''
          );
          return loadAdminAssessmentScoresPhase6();
        })
        .catch(function (err) {
          setAdminScoresAlertPhase6(
            'danger',
            'Could Not Update Score Status (' + (err.code || 'ERR') + ')',
            err.message || ''
          );
        });
    }

    function loadAdminSettingsStep6() {
      if (
        !currentSessionMeta ||
        !currentSessionMeta.user ||
        currentSessionMeta.user.role !== 'ADMIN' ||
        currentSessionMeta.user.requiresPrivacyAck
      ) {
        return Promise.resolve();
      }

      return rpcCallEnvelope('admin.getSettings', {}, {
        suppressErrorBanner: true
      })
        .then(function (envelope) {
          var d = envelope.data || {};
          var pub = d.publicSettings || {};
          var priv = d.privateSettings || {};
          currentAdminSettingsVersions = d.versions || {};

          setInputValue('input-admin-school-name', pub.schoolName || 'Pattanabhumi Biology');
          setInputValue('input-admin-contact-email', pub.contactEmail || '');
          setInputValue('input-admin-line-url', pub.contactLineUrl || '');
          setInputValue('input-admin-facebook-url', pub.contactFacebookUrl || '');
          setInputValue('input-admin-privacy-version', pub.privacyNoticeVersion || '2026-10-v1');
          setInputValue('input-admin-privacy-document', pub.privacyNoticeDocumentText || '');

          setInputValue('input-admin-notification-email', priv.notificationRecipientEmail || '');
          setInputValue('input-admin-promptpay-target', priv.promptPayTarget || '');
          setInputValue('input-admin-bank-account-name', priv.bankAccountName || '');
          setInputValue('input-admin-bank-name', priv.bankName || '');
          setInputValue('input-admin-bank-account-number', priv.bankAccountNumber || '');
          setInputValue('input-admin-logo-override', priv.logoFileIdOverride || '');

          setText(
            'admin-settings-public-versions-badge',
            'Public Settings (SCHOOL_NAME v' +
              String(currentAdminSettingsVersions.SCHOOL_NAME || 1) +
              ', PRIVACY v' +
              String(currentAdminSettingsVersions.CURRENT_PRIVACY_NOTICE_VERSION || 1) +
              ')'
          );
          setText(
            'admin-settings-private-versions-badge',
            'Private Settings (PROMPTPAY v' +
              String(currentAdminSettingsVersions.PROMPTPAY_ID_DISPLAY || 1) +
              ', BANK v' +
              String(currentAdminSettingsVersions.BANK_ACCOUNT_NUMBER || 1) +
              ')'
          );

          if (d.logoUploadFeature && d.logoUploadFeature.honestExplanation) {
            setText('admin-logo-upload-honest-note', d.logoUploadFeature.honestExplanation);
          }
          if (d.publicWebsiteCms) {
            populateAdminPublicWebsiteCmsFormPhase6(d.publicWebsiteCms);
          }
        })
        .catch(function (err) {
          setAdminSettingsAlert(
            'danger',
            'Could Not Load School Settings (' + (err.code || 'ERR') + ')',
            err.message || ''
          );
        });
    }

    /**
     * Renders the checkbox list of available biology courses inside the User Editor card.
     */
    function renderUserEditorCourseCheckboxes(selectedCourseIds) {
      var host = document.getElementById('user-editor-courses-checkbox-list');
      if (!host) {
        return;
      }
      while (host.firstChild) {
        host.removeChild(host.firstChild);
      }

      var selectedMap = {};
      if (Array.isArray(selectedCourseIds)) {
        for (var s = 0; s < selectedCourseIds.length; s++) {
          selectedMap[String(selectedCourseIds[s])] = true;
        }
      }

      if (!Array.isArray(currentAdminAvailableCourses) || currentAdminAvailableCourses.length === 0) {
        var p = document.createElement('p');
        p.style.margin = '0';
        p.style.fontSize = '0.85rem';
        p.textContent = 'No courses available yet.';
        host.appendChild(p);
        return;
      }

      for (var i = 0; i < currentAdminAvailableCourses.length; i++) {
        var c = currentAdminAvailableCourses[i];
        var wrap = document.createElement('div');
        wrap.style.marginBottom = '6px';

        var lbl = document.createElement('label');
        lbl.className = 'checkbox-label';
        lbl.style.fontSize = '0.88rem';

        var cb = document.createElement('input');
        cb.type = 'checkbox';
        cb.name = 'userAssignedCourse';
        cb.value = c.courseId;
        cb.checked = Boolean(selectedMap[c.courseId]);

        var span = document.createElement('span');
        span.textContent =
          '[' + c.courseCode + '] ' + c.title + (c.subtitle ? ' - ' + c.subtitle : '');

        lbl.appendChild(cb);
        lbl.appendChild(span);
        wrap.appendChild(lbl);
        host.appendChild(wrap);
      }
    }

    function getCheckedCourseIdsInUserEditor() {
      var host = document.getElementById('user-editor-courses-checkbox-list');
      if (!host) {
        return [];
      }
      var boxes = host.querySelectorAll('input[name="userAssignedCourse"]');
      var ids = [];
      for (var i = 0; i < boxes.length; i++) {
        if (boxes[i].checked) {
          ids.push(boxes[i].value);
        }
      }
      return ids;
    }

    /**
     * Switches the User Editor Card between "CREATE NEW USER" mode (`userObj === null`)
     * and "EDIT EXISTING USER" mode (`userObj` populated), and also populates the
     * Password Reset card on the right.
     */
    function selectUserForAdminEditing(userObj) {
      var modeBadge = document.getElementById('admin-user-editor-mode-badge');
      var heading = document.getElementById('admin-user-editor-heading');
      var pwGroup = document.getElementById('group-user-editor-initial-password');
      var submitBtn = document.getElementById('btn-user-editor-submit');
      var staleBtn = document.getElementById('btn-user-editor-test-stale');
      var delBtn = document.getElementById('btn-user-editor-delete-test');
      var prvBox = document.getElementById('user-editor-privacy-readonly-box');
      var pwResetBtn = document.getElementById('btn-pw-reset-submit');

      setText('admin-user-editor-status', '');
      setText('admin-pw-reset-status', '');

      if (!userObj || !userObj.userId) {
        setInputValue('input-user-editor-id', '');
        setInputValue('input-user-editor-version', '');
        setInputValue('input-user-editor-username', '');
        setInputValue('input-user-editor-fullname', '');
        setInputValue('input-user-editor-email', '');
        setInputValue('select-user-editor-role', 'STUDENT');
        setInputValue('select-user-editor-status', 'ACTIVE');
        setInputValue('input-user-editor-password', '');
        var minorCbNew = document.getElementById('input-user-editor-minor-flag');
        if (minorCbNew) {
          minorCbNew.checked = false;
        }
        if (modeBadge) {
          modeBadge.className = 'badge badge-ok';
          modeBadge.textContent = 'CREATE NEW USER MODE';
        }
        if (heading) {
          heading.textContent = 'Create User Account (Student or Administrator)';
        }
        if (pwGroup) {
          pwGroup.classList.remove('hidden');
        }
        if (submitBtn) {
          submitBtn.textContent = 'Create User Account';
        }
        if (staleBtn) {
          staleBtn.classList.add('hidden');
        }
        if (delBtn) {
          delBtn.classList.add('hidden');
        }
        if (prvBox) {
          prvBox.classList.add('hidden');
        }
        renderUserEditorCourseCheckboxes([]);

        setInputValue('input-pw-reset-user-id', '');
        setInputValue('input-pw-reset-user-version', '');
        setInputValue(
          'input-pw-reset-username-display',
          'Click "Select / Edit" on any user row above first'
        );
        setInputValue('input-pw-reset-new-password', '');
        if (pwResetBtn) {
          pwResetBtn.disabled = true;
        }
        return;
      }

      /* Populate Edit Mode */
      setInputValue('input-user-editor-id', userObj.userId);
      setInputValue('input-user-editor-version', String(userObj.version || 1));
      setInputValue('input-user-editor-username', userObj.username || '');
      setInputValue('input-user-editor-fullname', userObj.fullName || '');
      setInputValue('input-user-editor-email', userObj.email || '');
      setInputValue('select-user-editor-role', userObj.role || 'STUDENT');
      setInputValue('select-user-editor-status', userObj.status || 'ACTIVE');
      setInputValue('input-user-editor-password', '');

      var minorCb = document.getElementById('input-user-editor-minor-flag');
      if (minorCb) {
        minorCb.checked = Boolean(userObj.isMinorFlag);
      }

      if (modeBadge) {
        modeBadge.className = 'badge badge-incomplete';
        modeBadge.textContent =
          'EDITING ' +
          userObj.username +
          ' (v' +
          String(userObj.version || 1) +
          ')';
      }
      if (heading) {
        heading.textContent =
          'Edit User Profile & Courses: ' + userObj.username;
      }
      if (pwGroup) {
        pwGroup.classList.add('hidden');
      }
      if (submitBtn) {
        submitBtn.textContent =
          'Save Profile & Enrollments (v' + String(userObj.version || 1) + ')';
      }
      if (staleBtn) {
        staleBtn.classList.remove('hidden');
      }
      if (delBtn) {
        delBtn.classList.remove('hidden');
      }
      if (prvBox) {
        prvBox.classList.remove('hidden');
        setText(
          'user-editor-privacy-readonly-text',
          'Notice Acknowledged: ' +
            (userObj.privacyAckVersion || 'Not yet acknowledged') +
            ' (' +
            String(userObj.privacyHistoryCount || 0) +
            ' history rows in PrivacyChoices) | Marketing Email Opt-In: ' +
            (userObj.marketingOptIn ? 'TRUE (Opted In)' : 'FALSE (Unchecked)') +
            ' - Preserved automatically during admin edits.'
        );
      }

      renderUserEditorCourseCheckboxes(userObj.assignedCourseIds || []);

      /* Populate Password Reset card */
      setInputValue('input-pw-reset-user-id', userObj.userId);
      setInputValue('input-pw-reset-user-version', String(userObj.version || 1));
      setInputValue(
        'input-pw-reset-username-display',
        userObj.username +
          ' (' +
          userObj.role +
          ' / ' +
          userObj.status +
          ' / v' +
          String(userObj.version || 1) +
          ')'
      );
      setInputValue('input-pw-reset-new-password', '');
      if (pwResetBtn) {
        pwResetBtn.disabled = false;
      }
    }

    /**
     * Renders the Admin Users table rows (`#admin-users-table-tbody`) using safe DOM node
     * construction (`document.createElement` / `textContent`, zero `innerHTML`).
     */
    function renderAdminUsersTable(items) {
      var tbody = document.getElementById('admin-users-table-tbody');
      if (!tbody) {
        return;
      }
      while (tbody.firstChild) {
        tbody.removeChild(tbody.firstChild);
      }

      if (!Array.isArray(items) || items.length === 0) {
        var emptyTr = document.createElement('tr');
        var emptyTd = document.createElement('td');
        emptyTd.colSpan = 6;
        emptyTd.style.textAlign = 'center';
        emptyTd.style.padding = '20px';
        emptyTd.style.color = 'var(--color-text-secondary)';
        emptyTd.textContent =
          'No user accounts matched the current search/filter criteria.';
        emptyTr.appendChild(emptyTd);
        tbody.appendChild(emptyTr);
        return;
      }

      for (var i = 0; i < items.length; i++) {
        (function (u) {
          var tr = document.createElement('tr');

          /* Col 1: User / Normalized Username / Email */
          var tdUser = document.createElement('td');
          var strongName = document.createElement('strong');
          strongName.style.color = 'var(--color-brand-deep)';
          strongName.textContent = u.username + ' ';
          tdUser.appendChild(strongName);

          if (u.isMinorFlag) {
            var minorBadge = document.createElement('span');
            minorBadge.className = 'badge badge-incomplete';
            minorBadge.style.fontSize = '0.7rem';
            minorBadge.textContent = 'Minor Flag';
            tdUser.appendChild(minorBadge);
          }

          var nameSpan = document.createElement('span');
          nameSpan.style.marginLeft = '6px';
          nameSpan.style.color = 'var(--color-text-primary)';
          nameSpan.textContent = '— ' + (u.fullName || '-');
          tdUser.appendChild(nameSpan);

          var emailSpan = document.createElement('span');
          emailSpan.style.marginLeft = '8px';
          emailSpan.style.fontSize = '0.78rem';
          emailSpan.style.color = 'var(--color-text-muted)';
          emailSpan.textContent = '(' + u.email + ')';
          tdUser.appendChild(emailSpan);
          tdUser.style.whiteSpace = 'nowrap';

          /* Col 2: Role & Status (Kept on same horizontal row) */
          var tdRole = document.createElement('td');
          var roleStatusRow = document.createElement('div');
          roleStatusRow.className = 'pb-users-inline-row';

          var roleBadge = document.createElement('span');
          roleBadge.className =
            u.role === 'ADMIN' ? 'badge badge-ok' : 'badge badge-incomplete';
          roleBadge.textContent = u.role;
          roleStatusRow.appendChild(roleBadge);

          var statusBadge = document.createElement('span');
          statusBadge.className =
            u.status === 'ACTIVE'
              ? 'badge badge-ok'
              : 'badge badge-danger';
          statusBadge.textContent = u.status;
          roleStatusRow.appendChild(statusBadge);

          if (u.isLastUsableAdmin) {
            var lastAdminNote = document.createElement('span');
            lastAdminNote.className = 'badge badge-incomplete';
            lastAdminNote.style.fontSize = '0.68rem';
            lastAdminNote.textContent = 'Last Active Admin';
            roleStatusRow.appendChild(lastAdminNote);
          }
          tdRole.appendChild(roleStatusRow);

          /* Col 3: Last Login (Asia/Bangkok) */
          var tdLogin = document.createElement('td');
          tdLogin.style.whiteSpace = 'nowrap';
          tdLogin.textContent = u.lastLoginAtBangkok || 'Never logged in';

          /* Col 4: Privacy & Marketing Choice (Kept on same horizontal row) */
          var tdPriv = document.createElement('td');
          var privRow = document.createElement('div');
          privRow.className = 'pb-users-inline-row';

          var ackSpan = document.createElement('span');
          ackSpan.className = 'pb-users-meta-chip';
          ackSpan.textContent = u.privacyAckVersion
            ? 'Ack: ' + u.privacyAckVersion
            : 'Ack: Pending';
          var mktSpan = document.createElement('span');
          mktSpan.className = 'pb-users-meta-chip';
          mktSpan.textContent =
            'Mkt: ' + (u.marketingOptIn ? 'In' : 'Out');
          var finSpan = document.createElement('span');
          finSpan.className = 'pb-users-meta-chip';
          var invCnt =
            u.financialReferences && u.financialReferences.invoiceCount
              ? u.financialReferences.invoiceCount
              : 0;
          var payCnt =
            u.financialReferences && u.financialReferences.paymentCount
              ? u.financialReferences.paymentCount
              : 0;
          finSpan.textContent = invCnt + ' inv / ' + payCnt + ' pay';
          privRow.appendChild(ackSpan);
          privRow.appendChild(mktSpan);
          privRow.appendChild(finSpan);
          tdPriv.appendChild(privRow);

          /* Col 5: Assigned Courses (Enrollments) */
          var tdCourses = document.createElement('td');
          var enrList = u.activeEnrollments || [];
          if (enrList.length === 0) {
            var noneSpan = document.createElement('span');
            noneSpan.style.fontSize = '0.82rem';
            noneSpan.style.color = 'var(--color-text-muted)';
            noneSpan.style.whiteSpace = 'nowrap';
            noneSpan.textContent = 'None assigned';
            tdCourses.appendChild(noneSpan);
          } else {
            var pillWrap = document.createElement('div');
            pillWrap.className = 'course-pill-list pb-users-inline-row';
            for (var cIdx = 0; cIdx < enrList.length; cIdx++) {
              var pill = document.createElement('span');
              pill.className = 'course-pill';
              pill.textContent = enrList[cIdx].courseCode;
              pill.title = enrList[cIdx].courseTitle || enrList[cIdx].courseCode;
              pillWrap.appendChild(pill);
            }
            tdCourses.appendChild(pillWrap);
          }

          /* Col 6: Version & Actions (Kept on same horizontal row) */
          var tdActions = document.createElement('td');
          var btnGroup = document.createElement('div');
          btnGroup.className = 'pb-users-actions-inline-row';

          var verDiv = document.createElement('span');
          verDiv.className = 'pb-users-ver-chip';
          verDiv.textContent = 'v' + String(u.version || 1);
          btnGroup.appendChild(verDiv);

          var editBtn = document.createElement('button');
          editBtn.type = 'button';
          editBtn.className = 'btn btn-primary btn-sm';
          setBtnVectorIcon(editBtn, 'edit', 'Edit', 'Edit user & course enrollments');
          editBtn.addEventListener('click', function () {
            selectUserForAdminEditing(u);
            PBAdminActionModal.open('admin-user-editor-card', 'Edit User & Courses: ' + u.username);
          });
          btnGroup.appendChild(editBtn);

          var pwModalBtn = document.createElement('button');
          pwModalBtn.type = 'button';
          pwModalBtn.className = 'btn btn-secondary btn-sm';
          setBtnVectorIcon(pwModalBtn, 'key', 'Password', 'Reset user password');
          pwModalBtn.addEventListener('click', function () {
            selectUserForAdminEditing(u);
            PBAdminActionModal.open('admin-password-reset-card', 'Reset Password: ' + u.username);
          });
          btnGroup.appendChild(pwModalBtn);

          var toggleBtn = document.createElement('button');
          toggleBtn.type = 'button';
          toggleBtn.className = 'btn btn-outline btn-sm';
          var nextQuickStatus =
            u.status === 'ACTIVE' ? 'SUSPENDED' : 'ACTIVE';
          setBtnVectorIcon(
            toggleBtn,
            u.status === 'ACTIVE' ? 'x' : 'check',
            u.status === 'ACTIVE' ? 'Suspend' : 'Activate',
            u.status === 'ACTIVE' ? 'Suspend account' : 'Activate account'
          );
          toggleBtn.addEventListener('click', function () {
            withButtonAndAreaLoading(toggleBtn, tr, function () {
              return handleQuickToggleUserStatus(u, nextQuickStatus);
            });
          });
          btnGroup.appendChild(toggleBtn);

          tdActions.appendChild(btnGroup);

          tr.appendChild(tdUser);
          tr.appendChild(tdRole);
          tr.appendChild(tdLogin);
          tr.appendChild(tdPriv);
          tr.appendChild(tdCourses);
          tr.appendChild(tdActions);
          tbody.appendChild(tr);
        })(items[i]);
      }
    }

    /**
     * Loads the paginated Admin Users table (`admin.listUsers`).
     */
    function loadAdminUsersStep6(opt_cursor, opt_resetPagination) {
      if (
        !currentSessionMeta ||
        !currentSessionMeta.user ||
        currentSessionMeta.user.role !== 'ADMIN' ||
        currentSessionMeta.user.requiresPrivacyAck
      ) {
        return Promise.resolve();
      }

      if (opt_resetPagination === true) {
        currentUsersCursorStack = [];
        currentUsersActiveCursor = null;
      } else if (opt_cursor !== undefined) {
        currentUsersActiveCursor = opt_cursor;
      }

      var searchInp = document.getElementById('input-users-search');
      var roleSel = document.getElementById('select-users-role-filter');
      var statusSel = document.getElementById('select-users-status-filter');
      var limitSel = document.getElementById('select-users-page-limit');

      var payload = {
        searchQuery: searchInp ? searchInp.value.trim() : '',
        roleFilter: roleSel ? roleSel.value : 'ALL',
        statusFilter: statusSel ? statusSel.value : 'ALL',
        limit: limitSel ? Number(limitSel.value || 10) : 10,
        cursor: currentUsersActiveCursor || null
      };

      return rpcCallEnvelope('admin.listUsers', payload, {
        suppressErrorBanner: true
      })
        .then(function (envelope) {
          var d = envelope.data || {};
          currentAdminUsersCache = d.items || [];
          currentAdminAvailableCourses = d.availableCourses || [];
          currentUsersNextCursor = d.nextCursor || null;

          var counts = d.summaryCounts || {};
          setText('users-count-usable-admins', String(counts.usableAdmins || 0));
          setText('users-count-active-students', String(counts.activeStudents || 0));
          setText('users-count-inactive-students', String(counts.inactiveStudents || 0));
          setText(
            'users-count-active-enrollments',
            String(counts.totalActiveEnrollments || 0)
          );

          renderAdminUsersTable(currentAdminUsersCache);
          populateAdminScorePublisherDropdownsPhase6();

          /* Update currently edited user if still open */
          var editingIdEl = document.getElementById('input-user-editor-id');
          var editingId = editingIdEl ? editingIdEl.value : '';
          if (!editingId) {
            renderUserEditorCourseCheckboxes(getCheckedCourseIdsInUserEditor());
          } else {
            for (var i = 0; i < currentAdminUsersCache.length; i++) {
              if (currentAdminUsersCache[i].userId === editingId) {
                selectUserForAdminEditing(currentAdminUsersCache[i]);
                break;
              }
            }
          }

          /* Update pagination controls */
          setText(
            'admin-users-pagination-summary',
            'Showing ' +
              String(currentAdminUsersCache.length) +
              ' of ' +
              String(d.totalMatched || 0) +
              ' matching users (Page ' +
              String(currentUsersCursorStack.length + 1) +
              ')'
          );

          var prevBtn = document.getElementById('btn-users-prev-page');
          var nextBtn = document.getElementById('btn-users-next-page');
          if (prevBtn) {
            prevBtn.disabled = currentUsersCursorStack.length === 0;
          }
          if (nextBtn) {
            nextBtn.disabled = !currentUsersNextCursor;
          }
        })
        .catch(function (err) {
          setAdminUsersAlert(
            'danger',
            'Failed to Load Users (' + (err.code || 'ERR') + ')',
            err.message || ''
          );
        });
    }

    /**
     * Quick row action to toggle a user between `ACTIVE` and `SUSPENDED`.
     */
    function handleQuickToggleUserStatus(userObj, targetStatus) {
      hideUiErrorBanner();
      setAdminUsersAlert('hidden');

      return rpcCallEnvelope('admin.updateUser', {
        userId: userObj.userId,
        expectedVersion: Number(userObj.version || 1),
        status: targetStatus
      })
        .then(function (envelope) {
          var res = envelope.data || {};
          setAdminUsersAlert(
            'success',
            'User Status Updated (' + res.user.username + ' -> ' + res.user.status + ')',
            'Updated to version ' +
              String(res.user.version) +
              (res.revokedSessionCount > 0
                ? ' and revoked ' + String(res.revokedSessionCount) + ' active session(s).'
                : '.')
          );
          renderDiagnosticResult(
            'PASS: User status updated (' + res.user.username + ' -> ' + res.user.status + ')',
            res
          );
          return refreshAdminDashboardSummary();
        })
        .catch(function (err) {
          setAdminUsersAlert(
            'danger',
            'Status Change Blocked (' + (err.code || 'ERR') + ')',
            err.message || ''
          );
          renderDiagnosticResult('User status change blocked (' + err.code + ')', err);
        });
    }

    /**
     * Fetches and renders the live Administrator Dashboard summary (`admin.getDashboardSummary`),
     * plus loads Step 6 Settings (`admin.getSettings`) and Step 6 Users (`admin.listUsers`).
     */
    function refreshAdminDashboardSummary() {
      if (
        !currentSessionMeta ||
        !currentSessionMeta.user ||
        currentSessionMeta.user.role !== 'ADMIN' ||
        currentSessionMeta.user.requiresPrivacyAck
      ) {
        return Promise.resolve();
      }

      return rpcCallEnvelope('admin.getDashboardSummary', {}, {
        suppressErrorBanner: true
      })
        .then(function (envelope) {
          var d = envelope.data || {};
          setText(
            'admin-summary-username',
            d.adminUser
              ? d.adminUser.username + ' (' + d.adminUser.fullName + ')'
              : currentSessionMeta.user.username
          );
          setText(
            'admin-summary-users-count',
            String(d.totalUsersCount || 1) +
              ' total (' +
              String(d.studentUsersCount || 0) +
              ' students)'
          );
          setText(
            'admin-summary-sessions-count',
            String(d.activeSessionsCount || 1)
          );
          setText(
            'admin-summary-privacy-count',
            String(d.privacyChoicesCount || 0) + ' records in PrivacyChoices'
          );
          setText(
            'admin-summary-privacy-version',
            d.currentPrivacyNoticeVersion || '2026-10-v1'
          );

          if (d.logoDiagnostics && typeof d.logoDiagnostics === 'object') {
            var diag = d.logoDiagnostics;
            var statusBadge = document.getElementById('admin-logo-status-badge');
            if (statusBadge) {
              statusBadge.className = diag.available
                ? 'badge badge-ok'
                : 'badge badge-incomplete';
              statusBadge.textContent = diag.available
                ? 'ACTIVE (' + (diag.formatLabel || diag.detectedMimeType) + ')'
                : 'FALLBACK PB (' + (diag.statusCode || 'ERROR') + ')';
            }
            setText('admin-logo-diagnostic-message', diag.adminMessage || '-');
            setText(
              'admin-logo-source-type',
              (diag.sourceType || '-') +
                (diag.scriptPropertyConfigured
                  ? ' (DEFAULT_LOGO_DRIVE_FILE_ID Set)'
                  : ' (Using Built-in Default ID)')
            );
            setText('admin-logo-drive-id', diag.effectiveDriveFileId || '-');
            setText(
              'admin-logo-format-size',
              diag.available
                ? (diag.detectedMimeType || '-') +
                    ' (' +
                    String(diag.sizeBytes || 0) +
                    ' bytes)'
                : (diag.statusCode || 'FALLBACK') +
                    (diag.detectedMimeType
                      ? ' [' + diag.detectedMimeType + ']'
                      : '')
            );
            setText(
              'admin-logo-cache-status',
              diag.available
                ? (diag.cachedInScriptCache
                    ? 'CacheService + Browser Session Cache'
                    : 'Browser Session Cache (Payload > 90 KB)') +
                    (diag.servedFromScriptCache ? ' [Cache Hit]' : ' [Fresh Read]')
                : 'Not Cached (Fallback Active)'
            );
          }

          var activeTabPromise;
          if (currentAdminTab === 'users') {
            activeTabPromise = loadAdminUsersStep6(currentUsersActiveCursor, false);
          } else if (currentAdminTab === 'courses' || currentAdminTab === 'assessments') {
            activeTabPromise = loadAdminCoursesAndAssessmentsStep7();
          } else if (currentAdminTab === 'invoices') {
            activeTabPromise = loadAdminInvoicesStep10();
          } else if (currentAdminTab === 'unavailability') {
            activeTabPromise = loadAdminUnavailabilityRequestsStep14();
          } else {
            activeTabPromise = loadAdminSettingsStep6();
          }
          return activeTabPromise;
        })
        .catch(function (err) {
          renderDiagnosticResult(
            'Admin summary check returned ' + err.code,
            err
          );
        });
    }

    /**
     * Handles Step 6 Admin Settings form submission (`#form-admin-settings`), including
     * optimistic concurrency (`expectedVersions`).
     */
    function handleAdminSettingsSubmit(evt, opt_forceStaleVersionTest) {
      if (evt && typeof evt.preventDefault === 'function') {
        evt.preventDefault();
      }
      hideUiErrorBanner();
      setAdminSettingsAlert('hidden');

      var schoolNameInp = document.getElementById('input-admin-school-name');
      var emailInp = document.getElementById('input-admin-contact-email');
      var lineInp = document.getElementById('input-admin-line-url');
      var fbInp = document.getElementById('input-admin-facebook-url');
      var notifEmailInp = document.getElementById('input-admin-notification-email');
      var promptPayInp = document.getElementById('input-admin-promptpay-target');
      var bankAccNameInp = document.getElementById('input-admin-bank-account-name');
      var bankNameInp = document.getElementById('input-admin-bank-name');
      var bankAccNumInp = document.getElementById('input-admin-bank-account-number');
      var verInp = document.getElementById('input-admin-privacy-version');
      var docInp = document.getElementById('input-admin-privacy-document');
      var logoOverrideInp = document.getElementById('input-admin-logo-override');
      var submitBtn = document.getElementById('btn-save-admin-settings');

      var expectedVersionsToSend = {};
      var vKeys = Object.keys(currentAdminSettingsVersions || {});
      for (var i = 0; i < vKeys.length; i++) {
        var k = vKeys[i];
        expectedVersionsToSend[k] = currentAdminSettingsVersions[k];
      }
      if (opt_forceStaleVersionTest === true) {
        expectedVersionsToSend.SCHOOL_NAME = 999999;
      }

      var payload = {
        schoolName: schoolNameInp ? schoolNameInp.value.trim() : 'Pattanabhumi Biology',
        contactEmail: emailInp ? emailInp.value.trim() : '',
        contactLineUrl: lineInp ? lineInp.value.trim() : '',
        contactFacebookUrl: fbInp ? fbInp.value.trim() : '',
        notificationRecipientEmail: notifEmailInp ? notifEmailInp.value.trim() : '',
        promptPayTarget: promptPayInp ? promptPayInp.value.trim() : '',
        bankAccountName: bankAccNameInp ? bankAccNameInp.value.trim() : '',
        bankName: bankNameInp ? bankNameInp.value.trim() : '',
        bankAccountNumber: bankAccNumInp ? bankAccNumInp.value.trim() : '',
        privacyNoticeVersion: verInp ? verInp.value.trim() : '2026-10-v1',
        privacyNoticeDocumentText: docInp ? docInp.value.trim() : '',
        expectedVersions: expectedVersionsToSend
      };
      if (logoOverrideInp) {
        payload.logoFileIdOverride = logoOverrideInp.value.trim();
      }

      if (submitBtn) {
        submitBtn.disabled = true;
        submitBtn.textContent = 'Saving...';
      }
      setText('admin-settings-status', 'Validating and saving settings to Google Sheets...');

      return rpcCallEnvelope('admin.updateSettings', payload)
        .then(function (envelope) {
          var resData = envelope.data || {};
          currentAdminSettingsVersions = resData.versions || currentAdminSettingsVersions;
          setAdminSettingsAlert(
            'success',
            'School Settings Saved (' + String(resData.updatedCount || 0) + ' setting keys updated)',
            'Saved at ' +
              (resData.updatedAtBangkok || '') +
              '. Public settings updated in bootstrap; private settings stored securely on the backend.'
          );
          setText(
            'admin-settings-status',
            'Saved at ' + (resData.updatedAtBangkok || '')
          );
          renderDiagnosticResult(
            'PASS: Step 6 Public & Private School Settings saved by ADMIN',
            resData
          );
          writeCachedLogoState(null);
          return initializeShell();
        })
        .catch(function (err) {
          setAdminSettingsAlert(
            'danger',
            'Settings Save Failed (' + (err.code || 'ERR') + ')',
            err.message || ''
          );
          setText(
            'admin-settings-status',
            'Error (' + err.code + '): ' + String(err.message || '')
          );
          renderDiagnosticResult('Settings update rejected (' + err.code + ')', err);
        })
        .then(function () {
          if (submitBtn) {
            submitBtn.disabled = false;
            submitBtn.textContent = 'Save All School Settings';
          }
        });
    }

    /**
     * Handles Step 6 Create / Edit User & Course Assignments form (`#form-admin-user-editor`).
     */
    function handleAdminUserEditorSubmit(evt, opt_forceStaleVersionTest) {
      if (evt && typeof evt.preventDefault === 'function') {
        evt.preventDefault();
      }
      hideUiErrorBanner();
      setAdminUsersAlert('hidden');

      var idInp = document.getElementById('input-user-editor-id');
      var verInp = document.getElementById('input-user-editor-version');
      var userInp = document.getElementById('input-user-editor-username');
      var nameInp = document.getElementById('input-user-editor-fullname');
      var emailInp = document.getElementById('input-user-editor-email');
      var roleSel = document.getElementById('select-user-editor-role');
      var statusSel = document.getElementById('select-user-editor-status');
      var passInp = document.getElementById('input-user-editor-password');
      var minorInp = document.getElementById('input-user-editor-minor-flag');
      var submitBtn = document.getElementById('btn-user-editor-submit');

      var editingUserId = idInp ? idInp.value.trim() : '';
      var isEditMode = editingUserId.length > 0;
      var assignedCourseIds = getCheckedCourseIdsInUserEditor();

      var actionName = isEditMode ? 'admin.updateUser' : 'admin.createUser';
      var payload = {
        username: userInp ? userInp.value.trim() : '',
        fullName: nameInp ? nameInp.value.trim() : '',
        email: emailInp ? emailInp.value.trim() : '',
        role: roleSel ? roleSel.value : 'STUDENT',
        status: statusSel ? statusSel.value : 'ACTIVE',
        isMinorFlag: Boolean(minorInp && minorInp.checked),
        assignedCourseIds: assignedCourseIds
      };

      if (isEditMode) {
        payload.userId = editingUserId;
        payload.expectedVersion =
          opt_forceStaleVersionTest === true
            ? 999999
            : Number(verInp ? verInp.value : 1);
      } else {
        payload.initialPassword = passInp ? passInp.value : '';
      }

      if (submitBtn) {
        submitBtn.disabled = true;
      }
      setText(
        'admin-user-editor-status',
        isEditMode
          ? 'Updating user profile & course enrollments (checking record version)...'
          : 'Hashing initial password (PBKDF2-HMAC-SHA256) and creating user + course enrollments...'
      );

      return rpcCallEnvelope(actionName, payload)
        .then(function (envelope) {
          var res = envelope.data || {};
          var usr = res.user || {};
          setText(
            'admin-user-editor-status',
            (isEditMode ? 'Updated ' : 'Created ') +
              usr.username +
              ' (' +
              usr.role +
              ' / ' +
              usr.status +
              ', v' +
              String(usr.version) +
              ', ' +
              String((usr.assignedCourseIds || []).length) +
              ' enrolled course(s)).'
          );
          setAdminUsersAlert(
            'success',
            (isEditMode ? 'User Updated: ' : 'User Created: ') + usr.username,
            'Role: ' +
              usr.role +
              ' | Status: ' +
              usr.status +
              ' | Version: v' +
              String(usr.version) +
              ' | Active Course Enrollments: ' +
              String((usr.assignedCourseIds || []).length) +
              (res.revokedSessionCount
                ? ' | Revoked ' + String(res.revokedSessionCount) + ' active session(s).'
                : '')
          );
          renderDiagnosticResult(
            'PASS: ' + actionName + ' succeeded for ' + usr.username,
            res
          );
          selectUserForAdminEditing(usr);
          PBAdminActionModal.close();
          return refreshAdminDashboardSummary();
        })
        .catch(function (err) {
          setText(
            'admin-user-editor-status',
            'Error (' + (err.code || 'ERR') + '): ' + String(err.message || '')
          );
          setAdminUsersAlert(
            'danger',
            'User Save Failed (' + (err.code || 'ERR') + ')',
            err.message || ''
          );
          renderDiagnosticResult(actionName + ' rejected (' + err.code + ')', err);
        })
        .then(function () {
          if (submitBtn) {
            submitBtn.disabled = false;
          }
        });
    }

    /**
     * Handles Step 6 Dedicated Password Reset form (`#form-admin-reset-password`).
     */
    function handleAdminPasswordResetSubmit(evt) {
      if (evt && typeof evt.preventDefault === 'function') {
        evt.preventDefault();
      }
      hideUiErrorBanner();
      setAdminUsersAlert('hidden');

      var idInp = document.getElementById('input-pw-reset-user-id');
      var verInp = document.getElementById('input-pw-reset-user-version');
      var pwInp = document.getElementById('input-pw-reset-new-password');
      var submitBtn = document.getElementById('btn-pw-reset-submit');

      var userId = idInp ? idInp.value.trim() : '';
      var expectedVersion = Number(verInp ? verInp.value : 0);
      var newPassword = pwInp ? pwInp.value : '';

      if (!userId) {
        setText(
          'admin-pw-reset-status',
          'Select a user from the table above first.'
        );
        return Promise.resolve();
      }

      if (submitBtn) {
        submitBtn.disabled = true;
      }
      setText(
        'admin-pw-reset-status',
        'Hashing new password (PBKDF2-HMAC-SHA256) and revoking active sessions...'
      );

      return rpcCallEnvelope('admin.resetUserPassword', {
        userId: userId,
        expectedVersion: expectedVersion,
        newPassword: newPassword
      })
        .then(function (envelope) {
          var res = envelope.data || {};
          if (pwInp) {
            pwInp.value = '';
          }
          setText(
            'admin-pw-reset-status',
            'Password reset for ' +
              res.user.username +
              ' (v' +
              String(res.user.version) +
              '). Revoked ' +
              String(res.revokedSessionCount || 0) +
              ' session(s).'
          );
          setAdminUsersAlert(
            'success',
            'Password Reset Complete for ' + res.user.username,
            'New PBKDF2-HMAC-SHA256 hash stored (v' +
              String(res.user.version) +
              ') and ' +
              String(res.revokedSessionCount || 0) +
              ' active session(s) revoked.'
          );
          renderDiagnosticResult(
            'PASS: Password reset & sessions revoked for ' + res.user.username,
            res
          );
          selectUserForAdminEditing(res.user);
          return refreshAdminDashboardSummary();
        })
        .catch(function (err) {
          setText(
            'admin-pw-reset-status',
            'Error (' + (err.code || 'ERR') + '): ' + String(err.message || '')
          );
          setAdminUsersAlert(
            'danger',
            'Password Reset Failed (' + (err.code || 'ERR') + ')',
            err.message || ''
          );
        })
        .then(function () {
          if (submitBtn) {
            submitBtn.disabled = false;
          }
        });
    }

