    function handleAdminDeleteCourseStep7(courseObj) {
      var target =
        courseObj && courseObj.courseId
          ? courseObj
          : currentSelectedCourseDetail && currentSelectedCourseDetail.course
          ? currentSelectedCourseDetail.course
          : null;
      if (!target || !target.courseId) {
        setAdminCoursesAlert('warning', 'No Course Selected', 'Please select a course to delete.');
        return Promise.resolve();
      }
      var label = '[' + (target.courseCode || target.courseId) + '] "' + (target.title || '') + '"';
      if (typeof window !== 'undefined' && typeof window.confirm === 'function') {
        var confirmed = window.confirm(
          'Delete course ' +
            label +
            '?\n\nThis will permanently remove the course along with its sections, cards, and student enrollments.'
        );
        if (!confirmed) {
          return Promise.resolve();
        }
      }
      hideUiErrorBanner();
      return rpcCallEnvelope('admin.deleteCourse', { courseId: target.courseId })
        .then(function (envelope) {
          var d = envelope.data || {};
          PBAdminActionModal.close();
          if (adminCourseDetailCacheById && adminCourseDetailCacheById[target.courseId]) {
            delete adminCourseDetailCacheById[target.courseId];
          }
          if (studentCourseDetailCacheById && studentCourseDetailCacheById[target.courseId]) {
            delete studentCourseDetailCacheById[target.courseId];
          }
          if (
            currentSelectedCourseDetail &&
            currentSelectedCourseDetail.course &&
            currentSelectedCourseDetail.course.courseId === target.courseId
          ) {
            currentSelectedCourseDetail = null;
            populateCourseEditorForm(null);
            var ws = document.getElementById('admin-selected-course-workspace');
            if (ws) {
              ws.classList.add('hidden');
            }
          }
          setAdminCoursesAlert(
            'success',
            'Course Deleted',
            d.savedMessage || 'Deleted course ' + label + '.'
          );
          if (typeof PBNotify === 'object' && PBNotify && typeof PBNotify.toast === 'function') {
            PBNotify.toast('success', 'Course Deleted', d.savedMessage || 'Deleted course ' + label + '.');
          }
          return loadAdminCoursesAndAssessmentsStep7().then(function () {
            return refreshAdminDashboardSummary();
          });
        })
        .catch(function (err) {
          setAdminCoursesAlert(
            'danger',
            'Course Deletion Failed (' + (err.code || 'ERR') + ')',
            err.message || ''
          );
        });
    }

    function handleAdminSaveCourseSubmit(evt, opt_forceStaleVersion) {
      if (evt && typeof evt.preventDefault === 'function') {
        evt.preventDefault();
      }
      hideUiErrorBanner();
      ensureStep7RichTextEditorsInitialized();

      var courseId = document.getElementById('input-course-editor-id').value.trim();
      var expectedVersion = Number(
        document.getElementById('input-course-editor-version').value || 1
      );
      if (opt_forceStaleVersion === true) {
        expectedVersion = 999999;
      } else if (
        courseId &&
        currentSelectedCourseDetail &&
        currentSelectedCourseDetail.course &&
        currentSelectedCourseDetail.course.courseId === courseId
      ) {
        expectedVersion = Math.max(
          expectedVersion,
          Number(currentSelectedCourseDetail.course.version || 1)
        );
      }

      var objEditor = richTextEditorsRegistry['richtext-editor-course-objectives'];
      var outEditor = richTextEditorsRegistry['richtext-editor-course-outcomes'];

      var payload = {
        courseId: courseId,
        expectedVersion: expectedVersion,
        courseCode: document.getElementById('input-course-editor-code').value.trim(),
        title: document.getElementById('input-course-editor-title').value.trim(),
        subtitle: document.getElementById('input-course-editor-subtitle').value.trim(),
        status: document.getElementById('select-course-editor-status').value,
        sortOrder: Number(
          document.getElementById('input-course-editor-sort-order').value || 10
        ),
        calendarTag: document.getElementById('input-course-editor-calendar-tag').value.trim(),
        coverFileId: document.getElementById('input-course-editor-cover-file-id').value.trim(),
        objectivesRichText: objEditor ? objEditor.getValue() : createDefaultEmptyRichTextDoc(),
        outcomesRichText: outEditor ? outEditor.getValue() : createDefaultEmptyRichTextDoc()
      };

      if (!payload.courseCode || !payload.title) {
        setText('admin-course-editor-status', 'Course Code and Course Title are required.');
        setAdminCoursesAlert(
          'warning',
          'Missing Required Fields',
          'Please enter both Course Code and Course Title before saving.'
        );
        return Promise.resolve();
      }

      if (courseId && opt_forceStaleVersion !== true) {
        if (
          currentSelectedCourseDetail &&
          currentSelectedCourseDetail.course &&
          currentSelectedCourseDetail.course.courseId === courseId
        ) {
          var crs = currentSelectedCourseDetail.course;
          crs.courseCode = payload.courseCode;
          crs.title = payload.title;
          crs.subtitle = payload.subtitle;
          crs.status = payload.status;
          crs.sortOrder = payload.sortOrder;
          crs.calendarTag = payload.calendarTag;
          crs.coverFileId = payload.coverFileId;
          crs.objectivesRichText = payload.objectivesRichText;
          crs.outcomesRichText = payload.outcomesRichText;
          syncCourseCachesAfterMutation(currentSelectedCourseDetail);
          renderSelectedCourseSectionsAndCards(currentSelectedCourseDetail);
        } else {
          syncCourseCachesAfterMutation({
            course: {
              courseId: courseId,
              courseCode: payload.courseCode,
              title: payload.title,
              subtitle: payload.subtitle,
              status: payload.status,
              sortOrder: payload.sortOrder,
              calendarTag: payload.calendarTag,
              coverFileId: payload.coverFileId,
              version: expectedVersion
            },
            sections: []
          });
        }
        setCourseEditorDirtyState(false);
        setText('admin-course-editor-status', 'Saved locally — syncing to database...');
        PBAdminActionModal.close();

        return enqueueCourseMutation(courseId, 'Course Details', function () {
          var liveExpectedVer = payload.expectedVersion;
          if (
            currentSelectedCourseDetail &&
            currentSelectedCourseDetail.course &&
            currentSelectedCourseDetail.course.courseId === courseId &&
            currentSelectedCourseDetail.course.version
          ) {
            liveExpectedVer = Math.max(
              liveExpectedVer,
              Number(currentSelectedCourseDetail.course.version || 1)
            );
          }
          payload.expectedVersion = liveExpectedVer;
          return rpcCallEnvelope('admin.saveCourse', payload, { suppressErrorBanner: true })
            .then(function (envelope) {
              var d = envelope.data || {};
              if (pendingCourseMutationCountById[courseId] <= 1 && d.course) {
                currentSelectedCourseDetail = d;
                renderSelectedCourseSectionsAndCards(d);
                populateCourseEditorForm(d.course);
              } else if (d.course && currentSelectedCourseDetail && currentSelectedCourseDetail.course) {
                currentSelectedCourseDetail.course.version = d.course.version;
              }
              syncCourseCachesAfterMutation(d.course ? d : currentSelectedCourseDetail);
              setCourseEditorDirtyState(false);
              setText('admin-course-editor-status', d.savedMessage || 'Course saved.');
              setAdminCoursesAlert('success', 'Course Saved', d.savedMessage || '');
              renderDiagnosticResult('PASS: Course saved via admin.saveCourse', d);
              return d;
            })
            .catch(function (err) {
              setText(
                'admin-course-editor-status',
                'Save failed (' + (err.code || 'ERR') + '): ' + (err.message || '')
              );
              setAdminCoursesAlert(
                'danger',
                'Course Save Blocked (' + (err.code || 'ERR') + ')',
                err.message || ''
              );
              renderDiagnosticResult('Course save rejected (' + err.code + ')', err);
              return loadAdminCoursesAndAssessmentsStep7(courseId);
            });
        });
      }

      return rpcCallEnvelope('admin.saveCourse', payload)
        .then(function (envelope) {
          var d = envelope.data || {};
          currentSelectedCourseDetail = d;
          setCourseEditorDirtyState(false);
          setText('admin-course-editor-status', d.savedMessage || 'Course saved.');
          setAdminCoursesAlert('success', 'Course Saved', d.savedMessage || '');
          PBAdminActionModal.close();
          syncCourseCachesAfterMutation(d);
          if (d.course) {
            populateCourseEditorForm(d.course);
            var wsNew = document.getElementById('admin-selected-course-workspace');
            if (wsNew) wsNew.classList.remove('hidden');
            renderSelectedCourseSectionsAndCards(d);
          }
          renderDiagnosticResult('PASS: Course saved via admin.saveCourse', d);
          return d;
        })
        .catch(function (err) {
          setText(
            'admin-course-editor-status',
            'Save failed (' + (err.code || 'ERR') + '): ' + (err.message || '')
          );
          setAdminCoursesAlert(
            'danger',
            'Course Save Blocked (' + (err.code || 'ERR') + ')',
            err.message || ''
          );
          renderDiagnosticResult('Course save rejected (' + err.code + ')', err);
        });
    }

    function handleAdminSaveSectionSubmit(evt) {
      if (evt && typeof evt.preventDefault === 'function') {
        evt.preventDefault();
      }
      if (!currentSelectedCourseDetail || !currentSelectedCourseDetail.course) {
        setAdminCoursesAlert('warning', 'Select a Course First', 'Please select or create a course before adding sections.');
        return Promise.resolve();
      }

      var courseId = currentSelectedCourseDetail.course.courseId;
      var sectionId = document.getElementById('input-section-editor-id').value.trim();
      var expectedVersion = Number(
        document.getElementById('input-section-editor-version').value || 1
      );
      var title = document.getElementById('input-section-editor-title').value.trim();
      var status = document.getElementById('select-section-editor-status').value;

      if (!title) {
        setText('admin-section-editor-status', 'Section Title is required.');
        var secTitleInp = document.getElementById('input-section-editor-title');
        if (secTitleInp) secTitleInp.focus();
        return Promise.resolve();
      }

      var secsList = Array.isArray(currentSelectedCourseDetail.sections)
        ? currentSelectedCourseDetail.sections
        : (currentSelectedCourseDetail.sections = []);
      var tempSecId = sectionId || '__opt_sec_' + String(Date.now());
      if (sectionId) {
        for (var i = 0; i < secsList.length; i++) {
          if (secsList[i] && secsList[i].sectionId === sectionId) {
            expectedVersion = Math.max(expectedVersion, Number(secsList[i].version || 1));
            secsList[i].title = title;
            secsList[i].status = status;
            break;
          }
        }
      } else {
        secsList.push({
          sectionId: tempSecId,
          courseId: courseId,
          title: title,
          status: status,
          sectionType: 'CUSTOM',
          isDefaultSection: false,
          canHardDelete: true,
          sortOrder: (secsList.length + 1) * 10,
          version: 1,
          updatedAtBangkok: 'Saving...',
          cards: []
        });
      }

      populateSectionEditorForm(null);
      populateCardEditorDropdowns(
        secsList,
        currentSelectedCourseDetail.assessmentsLibrary || currentAdminAssessmentsList
      );
      syncCourseCachesAfterMutation(currentSelectedCourseDetail);
      renderSelectedCourseSectionsAndCards(currentSelectedCourseDetail);
      setCourseEditorDirtyState(false);
      PBAdminActionModal.close();

      return enqueueCourseMutation(courseId, 'Section Save', function () {
        return rpcCallEnvelope('admin.saveSection', {
          courseId: courseId,
          sectionId: sectionId,
          expectedVersion: expectedVersion,
          title: title,
          status: status,
          sectionType: 'CUSTOM'
        }, { suppressErrorBanner: true })
          .then(function (envelope) {
            var d = envelope.data || {};
            if (pendingCourseMutationCountById[courseId] <= 1) {
              currentSelectedCourseDetail = d;
              populateCardEditorDropdowns(
                d.sections || [],
                d.assessmentsLibrary || currentAdminAssessmentsList
              );
              renderSelectedCourseSectionsAndCards(d);
            } else if (d.course && currentSelectedCourseDetail && currentSelectedCourseDetail.course) {
              currentSelectedCourseDetail.course.version = d.course.version;
            }
            syncCourseCachesAfterMutation(d);
            setText('admin-section-editor-status', d.savedMessage || 'Section saved.');
            setAdminCoursesAlert('success', 'Section Saved', d.savedMessage || '');
            setCourseEditorDirtyState(false);
            renderDiagnosticResult('PASS: Section saved via admin.saveSection', d);
            return d;
          })
          .catch(function (err) {
            setText(
              'admin-section-editor-status',
              'Error (' + (err.code || 'ERR') + '): ' + (err.message || '')
            );
            setAdminCoursesAlert(
              'danger',
              'Section Save Failed (' + (err.code || 'ERR') + ')',
              err.message || ''
            );
            return loadAdminCourseEditorDetailStep7(courseId);
          });
      });
    }

    function handleAdminReorderSections(secIndex, directionDelta) {
      if (!currentSelectedCourseDetail || !currentSelectedCourseDetail.course) {
        return Promise.resolve();
      }
      var courseId = currentSelectedCourseDetail.course.courseId;
      var secs = Array.isArray(currentSelectedCourseDetail.sections)
        ? currentSelectedCourseDetail.sections
        : [];
      var targetIdx = secIndex + directionDelta;
      if (targetIdx < 0 || targetIdx >= secs.length) {
        return Promise.resolve();
      }
      var temp = secs[secIndex];
      secs[secIndex] = secs[targetIdx];
      secs[targetIdx] = temp;
      for (var i = 0; i < secs.length; i++) {
        if (secs[i]) secs[i].sortOrder = (i + 1) * 10;
      }

      var orderedIds = secs.map(function (s) {
        return s.sectionId;
      });

      syncCourseCachesAfterMutation(currentSelectedCourseDetail);
      populateCardEditorDropdowns(
        secs,
        currentSelectedCourseDetail.assessmentsLibrary || currentAdminAssessmentsList
      );
      renderSelectedCourseSectionsAndCards(currentSelectedCourseDetail);

      return enqueueCourseMutation(courseId, 'Reorder Sections', function () {
        return rpcCallEnvelope('admin.reorderSections', {
          courseId: courseId,
          orderedSectionIds: orderedIds
        }, { suppressErrorBanner: true })
          .then(function (env) {
            var d = env.data || {};
            if (pendingCourseMutationCountById[courseId] <= 1) {
              currentSelectedCourseDetail = d;
              renderSelectedCourseSectionsAndCards(d);
            } else if (d.course && currentSelectedCourseDetail && currentSelectedCourseDetail.course) {
              currentSelectedCourseDetail.course.version = d.course.version;
            }
            syncCourseCachesAfterMutation(d.course ? d : currentSelectedCourseDetail);
            setAdminCoursesAlert('success', 'Sections Reordered', d.savedMessage || '');
            return d;
          })
          .catch(function (err) {
            setAdminCoursesAlert(
              'danger',
              'Section Reorder Failed (' + (err.code || 'ERR') + ')',
              err.message || ''
            );
            return loadAdminCourseEditorDetailStep7(courseId);
          });
      });
    }

    function handleAdminSaveCardSubmit(evt) {
      if (evt && typeof evt.preventDefault === 'function') {
        evt.preventDefault();
      }
      if (!currentSelectedCourseDetail || !currentSelectedCourseDetail.course) {
        setAdminCoursesAlert('warning', 'Select a Course First', 'Please select a course first.');
        return Promise.resolve();
      }
      ensureStep7RichTextEditorsInitialized();
      var cardContentEditor = richTextEditorsRegistry['richtext-editor-card-content'];

      var courseId = currentSelectedCourseDetail.course.courseId;
      var cardId = document.getElementById('input-card-editor-id').value.trim();
      var expectedVersion = Number(
        document.getElementById('input-card-editor-version').value || 1
      );

      var payload = {
        courseId: courseId,
        sectionId: document.getElementById('select-card-editor-section-id').value,
        cardId: cardId,
        expectedVersion: expectedVersion,
        cardType: document.getElementById('select-card-editor-type').value,
        title: document.getElementById('input-card-editor-title').value.trim(),
        subtitle: document.getElementById('input-card-editor-subtitle').value.trim(),
        status: document.getElementById('select-card-editor-status').value,
        sortOrder: Number(
          document.getElementById('input-card-editor-sort-order').value || 10
        ),
        assessmentId: document.getElementById('select-card-editor-assessment-id').value,
        recordingUrl: document.getElementById('input-card-editor-recording-url').value.trim(),
        recordingUploadedAtUtc: document
          .getElementById('input-card-editor-upload-date')
          .value.trim(),
        imageFileId: document.getElementById('input-card-editor-image-file-id').value.trim(),
        imageCaption: document.getElementById('input-card-editor-image-caption').value.trim(),
        contentRichText: cardContentEditor
          ? cardContentEditor.getValue()
          : createDefaultEmptyRichTextDoc()
      };

      if (!payload.sectionId || !payload.title) {
        setText('admin-card-editor-status', 'Section and Card Title are required.');
        var cardTitleInp = document.getElementById('input-card-editor-title');
        if (cardTitleInp) cardTitleInp.focus();
        return Promise.resolve();
      }

      var secsList = Array.isArray(currentSelectedCourseDetail.sections)
        ? currentSelectedCourseDetail.sections
        : [];
      var existingCardCopy = null;
      for (var si = 0; si < secsList.length; si++) {
        var scCards = Array.isArray(secsList[si].cards) ? secsList[si].cards : [];
        for (var ci = 0; ci < scCards.length; ci++) {
          if (cardId && scCards[ci] && scCards[ci].cardId === cardId) {
            payload.expectedVersion = Math.max(
              payload.expectedVersion,
              Number(scCards[ci].version || 1)
            );
            if (secsList[si].sectionId !== payload.sectionId) {
              existingCardCopy = scCards.splice(ci, 1)[0];
            } else {
              existingCardCopy = scCards[ci];
            }
            break;
          }
        }
      }
      var tempCardObj = existingCardCopy || {
        cardId: cardId || '__opt_card_' + String(Date.now()),
        version: 1,
        updatedAtBangkok: 'Saving...'
      };
      tempCardObj.sectionId = payload.sectionId;
      tempCardObj.courseId = courseId;
      tempCardObj.cardType = payload.cardType;
      tempCardObj.title = payload.title;
      tempCardObj.subtitle = payload.subtitle;
      tempCardObj.status = payload.status;
      tempCardObj.sortOrder = payload.sortOrder;
      tempCardObj.assessmentId = payload.assessmentId;
      tempCardObj.recordingUrl = payload.recordingUrl;
      tempCardObj.recordingUploadedAtUtc = payload.recordingUploadedAtUtc;
      tempCardObj.imageFileId = payload.imageFileId;
      tempCardObj.imageCaption = payload.imageCaption;
      tempCardObj.contentRichText = payload.contentRichText;

      for (var ts = 0; ts < secsList.length; ts++) {
        if (secsList[ts] && secsList[ts].sectionId === payload.sectionId) {
          if (!Array.isArray(secsList[ts].cards)) secsList[ts].cards = [];
          if (secsList[ts].cards.indexOf(tempCardObj) === -1) {
            secsList[ts].cards.push(tempCardObj);
          }
          secsList[ts].cards.sort(function (a, b) {
            return (Number(a.sortOrder) || 0) - (Number(b.sortOrder) || 0);
          });
          break;
        }
      }

      populateCardEditorForm(null, payload.sectionId, payload.cardType);
      syncCourseCachesAfterMutation(currentSelectedCourseDetail);
      renderSelectedCourseSectionsAndCards(currentSelectedCourseDetail);
      setCourseEditorDirtyState(false);
      PBAdminActionModal.close();

      return enqueueCourseMutation(courseId, 'Card Save', function () {
        return rpcCallEnvelope('admin.saveCard', payload, { suppressErrorBanner: true })
          .then(function (env) {
            var d = env.data || {};
            if (pendingCourseMutationCountById[courseId] <= 1) {
              currentSelectedCourseDetail = d;
              renderSelectedCourseSectionsAndCards(d);
            } else if (d.course && currentSelectedCourseDetail && currentSelectedCourseDetail.course) {
              currentSelectedCourseDetail.course.version = d.course.version;
            }
            syncCourseCachesAfterMutation(d);
            setText('admin-card-editor-status', d.savedMessage || 'Card saved.');
            setAdminCoursesAlert('success', 'Card Saved', d.savedMessage || '');
            setCourseEditorDirtyState(false);
            renderDiagnosticResult('PASS: Card saved via admin.saveCard', d);
            return d;
          })
          .catch(function (err) {
            setText(
              'admin-card-editor-status',
              'Error (' + (err.code || 'ERR') + '): ' + (err.message || '')
            );
            setAdminCoursesAlert(
              'danger',
              'Card Save Failed (' + (err.code || 'ERR') + ')',
              err.message || ''
            );
            return loadAdminCourseEditorDetailStep7(courseId);
          });
      });
    }

    function handleAdminTestCrossCourseGuard() {
      if (!currentSelectedCourseDetail || !currentSelectedCourseDetail.sections) {
        return Promise.resolve();
      }
      var sampleCard = null;
      var secs = currentSelectedCourseDetail.sections;
      for (var i = 0; i < secs.length; i++) {
        if (secs[i].cards && secs[i].cards.length > 0) {
          sampleCard = secs[i].cards[0];
          break;
        }
      }
      if (!sampleCard) {
        setAdminCoursesAlert(
          'warning',
          'Add or Seed a Card First',
          'Seed the sample course or add a card first to test cross-course reassignment protection.'
        );
        return Promise.resolve();
      }

      return rpcCallEnvelope('admin.saveCard', {
        courseId: 'crs_tampered_other_course_id_999',
        sectionId: sampleCard.sectionId,
        cardId: sampleCard.cardId,
        expectedVersion: sampleCard.version,
        cardType: sampleCard.cardType,
        title: sampleCard.title,
        contentRichText: sampleCard.contentRichText
      })
        .then(function () {
          setAdminCoursesAlert('danger', 'Unexpected Success', 'Cross-course reassignment should be blocked.');
        })
        .catch(function (err) {
          setAdminCoursesAlert(
            'success',
            'Cross-Course Reassignment Blocked (' + (err.code || 'ERR') + ')',
            err.message || ''
          );
          renderDiagnosticResult(
            'PASS: Cross-course card reassignment blocked with ' + err.code,
            err
          );
        });
    }

    function handleAdminReorderCards(secObj, cardIndex, directionDelta) {
      if (!currentSelectedCourseDetail || !currentSelectedCourseDetail.course) {
        return Promise.resolve();
      }
      var courseId = currentSelectedCourseDetail.course.courseId;
      var liveSecs = Array.isArray(currentSelectedCourseDetail.sections)
        ? currentSelectedCourseDetail.sections
        : [];
      var targetSec = secObj;
      for (var s = 0; s < liveSecs.length; s++) {
        if (liveSecs[s] && secObj && liveSecs[s].sectionId === secObj.sectionId) {
          targetSec = liveSecs[s];
          break;
        }
      }
      var cards = Array.isArray(targetSec && targetSec.cards) ? targetSec.cards : [];
      var targetIdx = cardIndex + directionDelta;
      if (targetIdx < 0 || targetIdx >= cards.length) {
        return Promise.resolve();
      }
      var tmp = cards[cardIndex];
      cards[cardIndex] = cards[targetIdx];
      cards[targetIdx] = tmp;
      for (var c = 0; c < cards.length; c++) {
        if (cards[c]) cards[c].sortOrder = (c + 1) * 10;
      }

      var orderedCardIds = cards.map(function (cItem) {
        return cItem.cardId;
      });

      syncCourseCachesAfterMutation(currentSelectedCourseDetail);
      renderSelectedCourseSectionsAndCards(currentSelectedCourseDetail);

      return enqueueCourseMutation(courseId, 'Reorder Cards', function () {
        return rpcCallEnvelope('admin.reorderCards', {
          courseId: courseId,
          sectionId: targetSec.sectionId,
          orderedCardIds: orderedCardIds
        }, { suppressErrorBanner: true })
          .then(function (env) {
            var d = env.data || {};
            if (pendingCourseMutationCountById[courseId] <= 1) {
              currentSelectedCourseDetail = d;
              renderSelectedCourseSectionsAndCards(d);
            } else if (d.course && currentSelectedCourseDetail && currentSelectedCourseDetail.course) {
              currentSelectedCourseDetail.course.version = d.course.version;
            }
            syncCourseCachesAfterMutation(d.course ? d : currentSelectedCourseDetail);
            setAdminCoursesAlert('success', 'Cards Reordered', d.savedMessage || '');
            return d;
          })
          .catch(function (err) {
            setAdminCoursesAlert(
              'danger',
              'Card Reorder Failed (' + (err.code || 'ERR') + ')',
              err.message || ''
            );
            return loadAdminCourseEditorDetailStep7(courseId);
          });
      });
    }

    function handleAdminSaveAssessmentSubmit(evt) {
      if (evt && typeof evt.preventDefault === 'function') {
        evt.preventDefault();
      }
      ensureStep7RichTextEditorsInitialized();
      var descEditor = richTextEditorsRegistry['richtext-editor-assessment-desc'];

      var assessmentId = document.getElementById('input-assessment-editor-id').value.trim();
      var expectedVersion = Number(
        document.getElementById('input-assessment-editor-version').value || 1
      );

      var payload = {
        assessmentId: assessmentId,
        expectedVersion: expectedVersion,
        title: document.getElementById('input-assessment-editor-title').value.trim(),
        status: document.getElementById('select-assessment-editor-status').value,
        externalUrl: document
          .getElementById('input-assessment-editor-external-url')
          .value.trim(),
        pdfFileId: document.getElementById('input-assessment-editor-pdf-file-id').value.trim(),
        descriptionRichText: descEditor
          ? descEditor.getValue()
          : createDefaultEmptyRichTextDoc()
      };

      return rpcCallEnvelope('admin.saveAssessment', payload)
        .then(function (env) {
          var d = env.data || {};
          setText('admin-assessment-editor-status', d.savedMessage || 'Saved assessment.');
          populateAssessmentEditorForm(null);
          PBAdminActionModal.close();
          renderDiagnosticResult('PASS: Assessment saved via admin.saveAssessment', d);
          return loadAdminCoursesAndAssessmentsStep7(
            currentSelectedCourseDetail && currentSelectedCourseDetail.course
              ? currentSelectedCourseDetail.course.courseId
              : null
          );
        })
        .catch(function (err) {
          setText(
            'admin-assessment-editor-status',
            'Error (' + (err.code || 'ERR') + '): ' + (err.message || '')
          );
        });
    }

    /**
     * Opens the Student Course Detail View (`#view-course-detail`) and renders Course Assessment
     * objectives & outcomes, Reading Material cards, and Class Recordings cards.
     */
    var currentStudentCourseDetailBundle = null;
    var activeStudentSectionFilter = 'ALL';

    function handleCourseAccessRevokedWhileOpen(err) {
      PBObjectUrlManager.revokeAll('COURSE_ACCESS_REVOKED');
      closeModalDialog('modal-recording-detail');
      currentStudentCourseId = '';
      currentStudentCourseDetailBundle = null;
      showSectionView('profile');
      refreshStudentProfileCourses();
      showUiErrorBanner({
        code: (err && err.code) || 'ERR_FORBIDDEN_RESOURCE',
        action: (err && err.action) || 'student.getCourseDetail',
        requestId: (err && err.requestId) || 'access_revoked',
        message:
          (err && err.message) ||
          'Access denied: Your enrollment in this course was removed or the course is no longer published. You have been returned to My Profile.'
      });
    }

    function renderStudentCourseSectionsFiltered(detailBundle, sectionFilterId) {
      var d = detailBundle || {};
      var course = d.course || {};
      var sections = Array.isArray(d.sections) ? d.sections : [];
      activeStudentSectionFilter = sectionFilterId || 'ALL';

      /* 1. Render Administrator-Defined Section Selector Cards */
      var navHost = document.getElementById('student-course-section-cards-nav');
      var activeBadge = document.getElementById('student-course-active-section-indicator');
      if (navHost) {
        while (navHost.firstChild) {
          navHost.removeChild(navHost.firstChild);
        }

        function getSectionToneBadgeClass(toneKey, isSel) {
          if (isSel) {
            return 'badge badge-incomplete';
          }
          if (toneKey === 'RECORDING') return 'badge pb-cat-badge-recording';
          if (toneKey === 'READING') return 'badge pb-cat-badge-reading';
          if (toneKey === 'ASSESSMENT') return 'badge pb-cat-badge-assessment';
          if (toneKey === 'SCORES') return 'badge pb-cat-badge-scores';
          if (toneKey === 'CUSTOM') return 'badge pb-cat-badge-custom';
          return 'badge badge-ok';
        }

        function createSectionSelectorCard(filterVal, badgeText, titleText, metaText, opt_toneKey) {
          var toneKey = String(opt_toneKey || filterVal || 'CUSTOM').toUpperCase();
          var btn = document.createElement('button');
          btn.type = 'button';
          var isSelected = activeStudentSectionFilter === filterVal;
          btn.className =
            'section-selector-card' + (isSelected ? ' is-active' : '');
          btn.setAttribute('aria-pressed', isSelected ? 'true' : 'false');
          btn.setAttribute('data-section-card-filter', filterVal);
          btn.setAttribute('data-category-tone', toneKey);

          var topBadge = document.createElement('span');
          topBadge.className = getSectionToneBadgeClass(toneKey, isSelected);
          topBadge.textContent = badgeText;
          btn.appendChild(topBadge);

          var ttl = document.createElement('div');
          ttl.className = 'section-selector-title';
          ttl.textContent = titleText;
          btn.appendChild(ttl);

          var meta = document.createElement('div');
          meta.className = 'section-selector-meta';
          meta.textContent = metaText;
          btn.appendChild(meta);

          btn.addEventListener('click', function () {
            renderStudentCourseSectionsFiltered(detailBundle, filterVal);
          });
          return btn;
        }

        var courseScoresList = Array.isArray(d.publishedScores) ? d.publishedScores : [];
        navHost.appendChild(
          createSectionSelectorCard(
            'ALL',
            'ALL SECTIONS (' + String(sections.length) + ')',
            'All Course Sections',
            'Objectives, Scores, Assessment, Reading & Recordings',
            'ALL'
          )
        );

        navHost.appendChild(
          createSectionSelectorCard(
            'SCORES',
            'PUBLISHED SCORES (' + String(courseScoresList.length) + ')',
            'My Published Assessment Scores',
            String(courseScoresList.length) +
              ' published score(s) verified for your account',
            'SCORES'
          )
        );

        for (var nIdx = 0; nIdx < sections.length; nIdx++) {
          var sItem = sections[nIdx];
          var cardCnt = Array.isArray(sItem.cards) ? sItem.cards.length : 0;
          navHost.appendChild(
            createSectionSelectorCard(
              sItem.sectionId,
              sItem.sectionType,
              (nIdx + 1) + '. ' + sItem.title,
              String(cardCnt) +
                ' item(s) | Updated: ' +
                (sItem.updatedAtBangkok || sItem.updatedAtUtc || '-'),
              sItem.sectionType || 'CUSTOM'
            )
          );
          if (activeStudentSectionFilter === sItem.sectionId && activeBadge) {
            activeBadge.textContent = 'Showing Section: ' + sItem.title;
          }
        }
        if (activeStudentSectionFilter === 'ALL' && activeBadge) {
          activeBadge.textContent = 'Showing: All Course Sections (' + sections.length + ')';
        } else if (activeStudentSectionFilter === 'SCORES' && activeBadge) {
          activeBadge.textContent =
            'Showing: My Published Assessment Scores (' + courseScoresList.length + ')';
        }
      }

      /* Render and toggle Phase 3 Native Examination Catalog Card */
      var nativeExamsCard = document.getElementById('student-course-native-exams-card');
      if (d.nativeExamCatalog) {
        renderStudentCourseExamCatalogCardsPhase3(d.nativeExamCatalog);
      } else if (d.course && d.course.courseId) {
        loadStudentCourseExamsCatalogPhase3(d.course.courseId);
      }
      if (nativeExamsCard) {
        var showNativeExams =
          activeStudentSectionFilter === 'ALL' ||
          activeStudentSectionFilter === 'SCORES';
        if (!showNativeExams) {
          for (var neIdx = 0; neIdx < sections.length; neIdx++) {
            if (
              sections[neIdx].sectionId === activeStudentSectionFilter &&
              sections[neIdx].sectionType === 'ASSESSMENT'
            ) {
              showNativeExams = true;
              break;
            }
          }
        }
        nativeExamsCard.classList.toggle('hidden', !showNativeExams);
      }

      /* Render and toggle Course Published Scores Card */
      var courseScoresCard = document.getElementById('student-course-published-scores-card');
      renderStudentPublishedScoresTable(
        'student-course-scores-tbody',
        'student-course-scores-empty',
        'student-course-scores-table-wrap',
        'student-course-scores-count-badge',
        d.publishedScores || [],
        false
      );
      if (courseScoresCard) {
        var showScoresCard =
          activeStudentSectionFilter === 'ALL' ||
          activeStudentSectionFilter === 'SCORES';
        if (!showScoresCard) {
          for (var scIdx = 0; scIdx < sections.length; scIdx++) {
            if (
              sections[scIdx].sectionId === activeStudentSectionFilter &&
              sections[scIdx].sectionType === 'ASSESSMENT'
            ) {
              showScoresCard = true;
              break;
            }
          }
        }
        courseScoresCard.classList.toggle('hidden', !showScoresCard);
      }

      /* Toggle Course Assessment Overview Card visibility based on active section filter */
      var asmOverviewCard = document.getElementById('student-course-assessment-overview');
      if (asmOverviewCard) {
        var showOverview = activeStudentSectionFilter === 'ALL';
        if (!showOverview) {
          for (var k = 0; k < sections.length; k++) {
            if (
              sections[k].sectionId === activeStudentSectionFilter &&
              sections[k].sectionType === 'ASSESSMENT'
            ) {
              showOverview = true;
              break;
            }
          }
        }
        asmOverviewCard.classList.toggle('hidden', !showOverview);
      }

      /* 2. Render Section Views (Assessment View, Reading View, Recording View, Custom Sections) */
      var secContainer = document.getElementById('student-course-sections-container');
      if (!secContainer) {
        return;
      }
      while (secContainer.firstChild) {
        secContainer.removeChild(secContainer.firstChild);
      }

      for (var sIdx = 0; sIdx < sections.length; sIdx++) {
        var sec = sections[sIdx];
        if (
          activeStudentSectionFilter !== 'ALL' &&
          sec.sectionId !== activeStudentSectionFilter
        ) {
          continue;
        }

        var secTone = String(sec.sectionType || 'CUSTOM').toUpperCase();
        var secCard = document.createElement('section');
        secCard.className =
          'card course-section-box course-section-' + String(sec.sectionType || 'custom').toLowerCase();
        secCard.setAttribute('data-section-id', sec.sectionId);
        secCard.setAttribute('data-section-type', sec.sectionType || 'CUSTOM');
        secCard.setAttribute('data-category-tone', secTone);

        var secTop = document.createElement('div');
        secTop.style.display = 'flex';
        secTop.style.alignItems = 'center';
        secTop.style.justifyContent = 'space-between';
        secTop.style.flexWrap = 'wrap';
        secTop.style.gap = '8px';
        secTop.style.marginBottom = '12px';

        var secTitleWrap = document.createElement('div');
        var secBadge = document.createElement('span');
        secBadge.className =
          sec.sectionType === 'ASSESSMENT'
            ? 'badge pb-cat-badge-assessment'
            : sec.sectionType === 'RECORDING'
            ? 'badge pb-cat-badge-recording'
            : sec.sectionType === 'READING'
            ? 'badge pb-cat-badge-reading'
            : 'badge pb-cat-badge-custom';
        secBadge.textContent =
          sec.sectionType === 'ASSESSMENT'
            ? 'Assigned Assessments'
            : sec.sectionType === 'READING'
            ? 'Reading Materials'
            : sec.sectionType === 'RECORDING'
            ? 'Class Recordings'
            : 'Course Module';

        var secH2 = document.createElement('h2');
        secH2.style.margin = '6px 0 0 0';
        secH2.style.fontSize = '1.28rem';
        secH2.style.color = 'var(--color-brand-deep)';
        secH2.textContent = (sIdx + 1) + '. ' + sec.title;

        secTitleWrap.appendChild(secBadge);
        secTitleWrap.appendChild(secH2);

        var secUpd = document.createElement('div');
        secUpd.style.fontSize = '0.82rem';
        secUpd.style.fontWeight = '600';
        secUpd.style.color = 'var(--color-text-secondary)';
        var effectiveLastUpdated =
          sec.sectionType === 'ASSESSMENT'
            ? course.assessmentUpdatedAtBangkok || sec.updatedAtBangkok || sec.updatedAtUtc || '-'
            : sec.sectionType === 'READING'
            ? course.readingUpdatedAtBangkok || sec.updatedAtBangkok || sec.updatedAtUtc || '-'
            : sec.updatedAtBangkok || sec.updatedAtUtc || '-';
        secUpd.textContent = 'Updated (BKK): ' + effectiveLastUpdated;

        secTop.appendChild(secTitleWrap);
        secTop.appendChild(secUpd);
        secCard.appendChild(secTop);

        /* In Assessment View, also show inline Course Objectives & Outcomes summary if filtered */
        if (sec.sectionType === 'ASSESSMENT') {
          var asmIntroP = document.createElement('p');
          asmIntroP.style.margin = '0 0 12px 0';
          asmIntroP.style.fontSize = '0.9rem';
          asmIntroP.style.color = 'var(--color-text-secondary)';
          asmIntroP.textContent =
            'Review and complete your assigned assessments, topic checkpoints, and downloadable worksheets below.';
          secCard.appendChild(asmIntroP);
        } else if (sec.sectionType === 'RECORDING') {
          var recIntroP = document.createElement('p');
          recIntroP.style.margin = '0 0 12px 0';
          recIntroP.style.fontSize = '0.9rem';
          recIntroP.style.color = 'var(--color-text-secondary)';
          recIntroP.textContent =
            'Select any class recording episode below to launch the Theater Video Player, view lesson notes, and download PDF handouts.';
          secCard.appendChild(recIntroP);
        }

        var cards = Array.isArray(sec.cards) ? sec.cards : [];
        if (cards.length === 0) {
          var emptyNote = document.createElement('p');
          emptyNote.style.margin = '0';
          emptyNote.style.color = 'var(--color-text-muted)';
          emptyNote.textContent = 'No published items in this section yet.';
          secCard.appendChild(emptyNote);
        } else {
          var sectionRecordingCards = cards.filter(function (cItem) {
            return cItem && (cItem.cardType === 'RECORDING_CARD' || sec.sectionType === 'RECORDING');
          });
          var activeVideoGrid = null;

          for (var cIdx = 0; cIdx < cards.length; cIdx++) {
            (function (crd, cardPositionIndex) {
              var isRecordingCard =
                crd.cardType === 'RECORDING_CARD' || sec.sectionType === 'RECORDING';

              if (isRecordingCard) {
                if (!activeVideoGrid) {
                  activeVideoGrid = document.createElement('div');
                  activeVideoGrid.className = 'pb-yt-video-grid';
                  secCard.appendChild(activeVideoGrid);
                }

                var ytCard = document.createElement('article');
                ytCard.className = 'pb-yt-card recording-card-clickable';
                ytCard.setAttribute('data-card-id', crd.cardId);
                ytCard.setAttribute('tabindex', '0');
                ytCard.setAttribute('role', 'button');
                ytCard.setAttribute(
                  'aria-label',
                  'Play class recording ' + (crd.title || '')
                );

                var thumbBox = document.createElement('div');
                thumbBox.className = 'pb-yt-thumb-box';

                var cardYtMeta = extractAndNormalizeYouTubeUrlClient(crd.recordingUrl || '');
                var hasLink = Boolean(crd.recordingUrl && isSafeRichTextHref(crd.recordingUrl));
                var docListCount = Array.isArray(crd.lessonDocuments)
                  ? crd.lessonDocuments.length
                  : Array.isArray(crd.pdfAttachments)
                  ? crd.pdfAttachments.length
                  : 0;

                var fallbackLayer = document.createElement('div');
                fallbackLayer.className = 'pb-yt-thumb-fallback';
                var fbTitle = document.createElement('div');
                fbTitle.style.fontWeight = '800';
                fbTitle.style.fontSize = '0.94rem';
                fbTitle.textContent = hasLink ? 'Recorded Class Stream' : 'Video Pending Upload';
                var fbSub = document.createElement('div');
                fbSub.style.fontSize = '0.78rem';
                fbSub.style.opacity = '0.82';
                fbSub.textContent = crd.subtitle || crd.title || 'Pattanabhumi Biology';
                fallbackLayer.appendChild(fbTitle);
                fallbackLayer.appendChild(fbSub);
                thumbBox.appendChild(fallbackLayer);

                if (cardYtMeta.isYouTubeVideo && cardYtMeta.youtubeThumbnailUrl) {
                  var ytThumbImg = document.createElement('img');
                  ytThumbImg.className = 'pb-yt-thumb-img';
                  ytThumbImg.src = cardYtMeta.youtubeThumbnailUrl;
                  ytThumbImg.alt = (crd.title || 'Class Recording') + ' thumbnail';
                  ytThumbImg.loading = 'lazy';
                  ytThumbImg.setAttribute('referrerpolicy', 'no-referrer');
                  fallbackLayer.classList.add('hidden');
                  ytThumbImg.addEventListener('error', function () {
                    ytThumbImg.classList.add('hidden');
                    fallbackLayer.classList.remove('hidden');
                  });
                  thumbBox.appendChild(ytThumbImg);
                } else if (crd.imageFileId && /^fil_[a-z0-9_-]{4,64}$/i.test(crd.imageFileId)) {
                  var customThumbImg = document.createElement('img');
                  customThumbImg.className = 'pb-yt-thumb-img hidden';
                  customThumbImg.alt = crd.imageCaption || crd.title || 'Recording cover';
                  thumbBox.appendChild(customThumbImg);
                  PBObjectUrlManager.fetchAndCreateObjectUrl(
                    crd.imageFileId,
                    course.courseId
                  )
                    .then(function (entry) {
                      customThumbImg.src = entry.objectUrl;
                      customThumbImg.classList.remove('hidden');
                      fallbackLayer.classList.add('hidden');
                    })
                    .catch(function () {});
                }

                var scrim = document.createElement('div');
                scrim.className = 'pb-yt-thumb-scrim';
                thumbBox.appendChild(scrim);

                var srcChip = document.createElement('span');
                srcChip.className = 'pb-yt-source-chip';
                srcChip.textContent = cardYtMeta.isYouTubeVideo
                  ? 'YouTube HD'
                  : hasLink
                  ? 'External Stream'
                  : 'Notes Only';
                thumbBox.appendChild(srcChip);

                var playCircle = document.createElement('div');
                playCircle.className = 'pb-yt-play-overlay';
                playCircle.innerHTML =
                  '<svg viewBox="0 0 24 24" width="24" height="24" fill="currentColor" aria-hidden="true" focusable="false"><polygon points="6 4 20 12 6 20 6 4"></polygon></svg>';
                thumbBox.appendChild(playCircle);

                var bottomChip = document.createElement('span');
                bottomChip.className = 'pb-yt-bottom-chip';
                bottomChip.textContent =
                  docListCount > 0
                    ? String(docListCount) + (docListCount === 1 ? ' PDF Handout' : ' PDF Handouts')
                    : 'Episode ' + String(cardPositionIndex + 1);
                thumbBox.appendChild(bottomChip);

                ytCard.appendChild(thumbBox);

                var cardFooter = document.createElement('div');
                cardFooter.className = 'pb-yt-card-footer';

                var avatar = document.createElement('div');
                avatar.className = 'pb-yt-avatar-badge';
                avatar.textContent = 'E' + String(cardPositionIndex + 1);
                cardFooter.appendChild(avatar);

                var cardTextWrap = document.createElement('div');
                cardTextWrap.className = 'pb-yt-card-text';

                var cardTitleEl = document.createElement('h3');
                cardTitleEl.className = 'pb-yt-card-title';
                cardTitleEl.textContent = crd.title || 'Class Recording';
                cardTextWrap.appendChild(cardTitleEl);

                if (crd.subtitle) {
                  var cardSubEl = document.createElement('p');
                  cardSubEl.className = 'pb-yt-card-subtitle';
                  cardSubEl.textContent = crd.subtitle;
                  cardTextWrap.appendChild(cardSubEl);
                }

                var cardMetaEl = document.createElement('div');
                cardMetaEl.className = 'pb-yt-card-meta';
                var rawUploadDt =
                  crd.recordingUploadedAtBangkok ||
                  crd.recordingUploadedAtUtc ||
                  crd.updatedAtBangkok ||
                  '-';
                cardMetaEl.textContent =
                  rawUploadDt +
                  (docListCount > 0
                    ? ' • ' + String(docListCount) + ' PDF(s)'
                    : ' • Click to Watch');
                cardTextWrap.appendChild(cardMetaEl);

                cardFooter.appendChild(cardTextWrap);
                ytCard.appendChild(cardFooter);

                ytCard.addEventListener('click', function () {
                  openRecordingDetailModal(crd, sectionRecordingCards);
                });
                ytCard.addEventListener('keydown', function (evt) {
                  if (evt.key === 'Enter' || evt.key === ' ') {
                    evt.preventDefault();
                    openRecordingDetailModal(crd, sectionRecordingCards);
                  }
                });

                activeVideoGrid.appendChild(ytCard);
                return;
              }

              activeVideoGrid = null;
              var itemBox = document.createElement('article');
              itemBox.className = 'course-card-item';
              itemBox.setAttribute('data-card-id', crd.cardId);

              /* Top Row: Card Title & Upload / Updated Date */
              var topHeaderRow = document.createElement('div');
              topHeaderRow.style.display = 'flex';
              topHeaderRow.style.alignItems = 'flex-start';
              topHeaderRow.style.justifyContent = 'space-between';
              topHeaderRow.style.flexWrap = 'wrap';
              topHeaderRow.style.gap = '8px';

              var titleCol = document.createElement('div');
              var h3 = document.createElement('h3');
              h3.style.margin = '0 0 4px 0';
              h3.style.fontSize = '1.1rem';
              h3.style.color = 'var(--color-brand-deep)';
              h3.textContent = crd.title;
              titleCol.appendChild(h3);

              if (crd.subtitle) {
                var subP = document.createElement('p');
                subP.style.margin = '0 0 8px 0';
                subP.style.fontSize = '0.9rem';
                subP.style.color = 'var(--color-text-secondary)';
                subP.textContent = crd.subtitle;
                titleCol.appendChild(subP);
              }
              topHeaderRow.appendChild(titleCol);

              var cardUpdSpan = document.createElement('span');
              cardUpdSpan.style.fontSize = '0.8rem';
              cardUpdSpan.style.color = 'var(--color-text-muted)';
              cardUpdSpan.textContent =
                'Updated: ' + (crd.updatedAtBangkok || crd.updatedAtUtc || '-');
              topHeaderRow.appendChild(cardUpdSpan);

              itemBox.appendChild(topHeaderRow);

              /* Reading / Content View: Optional Image + Caption */
              if (crd.imageFileId || crd.imageCaption) {
                var figBox = document.createElement('figure');
                figBox.className = 'pb-rt-attachment-figure';

                if (crd.imageFileId && /^fil_[a-z0-9_-]{4,64}$/i.test(crd.imageFileId)) {
                  var cardImgEl = document.createElement('img');
                  cardImgEl.className = 'pb-rt-attachment-img hidden';
                  cardImgEl.alt = crd.imageCaption || crd.title || 'Reading card diagram';
                  figBox.appendChild(cardImgEl);

                  PBObjectUrlManager.fetchAndCreateObjectUrl(
                    crd.imageFileId,
                    course.courseId
                  )
                    .then(function (entry) {
                      cardImgEl.src = entry.objectUrl;
                      cardImgEl.classList.remove('hidden');
                    })
                    .catch(function () {});
                }

                if (crd.imageCaption) {
                  var capEl = document.createElement('figcaption');
                  capEl.className = 'pb-rt-attachment-caption';
                  capEl.textContent = crd.imageCaption;
                  figBox.appendChild(capEl);
                }
                itemBox.appendChild(figBox);
              }

              /* Structured Rich-Text Content */
              var rtDiv = document.createElement('div');
              rtDiv.className = 'pb-rt-rendered';
              rtDiv.style.padding = '10px 12px';
              rtDiv.style.backgroundColor = '#FFFFFF';
              rtDiv.style.borderRadius = '6px';
              rtDiv.style.border = '1px solid var(--color-brand-border)';
              renderRichTextDocumentToDom(rtDiv, crd.contentRichText, course.courseId);
              itemBox.appendChild(rtDiv);

              /* Reading View: Resource Links Strip (Safe https:// links) */
              if (
                !isRecordingCard &&
                crd.cardType !== 'ASSESSMENT_LINK_CARD' &&
                crd.recordingUrl &&
                isSafeRichTextHref(crd.recordingUrl)
              ) {
                var resLinkBar = document.createElement('div');
                resLinkBar.style.marginTop = '10px';
                resLinkBar.style.display = 'flex';
                resLinkBar.style.alignItems = 'center';
                resLinkBar.style.justifyContent = 'space-between';
                resLinkBar.style.flexWrap = 'wrap';
                resLinkBar.style.gap = '8px';
                resLinkBar.style.padding = '8px 12px';
                resLinkBar.style.backgroundColor = '#F4FAF6';
                resLinkBar.style.borderRadius = '6px';
                resLinkBar.style.border = '1px solid var(--color-brand-border)';

                var resLabel = document.createElement('span');
                resLabel.style.fontSize = '0.86rem';
                resLabel.style.fontWeight = '700';
                resLabel.style.color = 'var(--color-brand-deep)';
                resLabel.textContent = 'External Reading Resource Link:';
                resLinkBar.appendChild(resLabel);

                var resAnchor = document.createElement('a');
                resAnchor.className = 'btn btn-secondary btn-sm';
                resAnchor.href = crd.recordingUrl.trim();
                resAnchor.target = '_blank';
                resAnchor.rel = 'noopener noreferrer';
                resAnchor.textContent = 'Open Resource Link (New Tab)';
                resLinkBar.appendChild(resAnchor);

                itemBox.appendChild(resLinkBar);
              }

              /* Assessment View: Redesigned Assigned Assessment Card */
              if (crd.cardType === 'ASSESSMENT_LINK_CARD' && crd.linkedAssessment) {
                var asmBox = document.createElement('div');
                asmBox.className = 'pb-assigned-assessment-card';

                var asmTop = document.createElement('div');
                asmTop.className = 'pb-assigned-assessment-header';

                var asmLeftGroup = document.createElement('div');
                asmLeftGroup.className = 'pb-assigned-assessment-title-group';

                var asmBadgeRow = document.createElement('div');
                asmBadgeRow.style.display = 'flex';
                asmBadgeRow.style.alignItems = 'center';
                asmBadgeRow.style.gap = '6px';
                asmBadgeRow.style.flexWrap = 'wrap';
                asmBadgeRow.style.marginBottom = '4px';

                var asmFormatPill = document.createElement('span');
                asmFormatPill.className = 'badge pb-exam-badge-assigned';
                asmFormatPill.textContent = 'Assigned Assessment';
                asmBadgeRow.appendChild(asmFormatPill);

                var asmResourcePill = document.createElement('span');
                asmResourcePill.className = 'badge pb-asm-type-pill';
                asmResourcePill.textContent = crd.linkedAssessment.externalUrl
                  ? 'External Quiz / Form'
                  : crd.linkedAssessment.pdfFileId
                  ? 'PDF Worksheet'
                  : 'Course Checkpoint';
                asmBadgeRow.appendChild(asmResourcePill);

                asmLeftGroup.appendChild(asmBadgeRow);

                var asmTitle = document.createElement('strong');
                asmTitle.className = 'pb-assigned-assessment-title';
                asmTitle.textContent = crd.linkedAssessment.title || crd.title || 'Assigned Assessment';
                asmLeftGroup.appendChild(asmTitle);
                asmTop.appendChild(asmLeftGroup);

                var asmStatusBadge = document.createElement('span');
                asmStatusBadge.className = crd.linkedAssessment.isArchived
                  ? 'badge badge-incomplete'
                  : 'badge badge-ok';
                asmStatusBadge.textContent = crd.linkedAssessment.isArchived
                  ? 'Archived'
                  : 'Ready to Complete';
                asmTop.appendChild(asmStatusBadge);

                asmBox.appendChild(asmTop);

                var asmDescDiv = document.createElement('div');
                asmDescDiv.className = 'pb-rt-rendered pb-assigned-assessment-desc';
                renderRichTextDocumentToDom(
                  asmDescDiv,
                  crd.linkedAssessment.descriptionRichText,
                  course.courseId
                );
                asmBox.appendChild(asmDescDiv);

                var asmActionsRow = document.createElement('div');
                asmActionsRow.className = 'pb-assigned-assessment-actions';

                if (
                  crd.linkedAssessment.externalUrl &&
                  isSafeRichTextHref(crd.linkedAssessment.externalUrl)
                ) {
                  var extLink = document.createElement('a');
                  extLink.className = 'btn btn-primary btn-sm';
                  extLink.href = crd.linkedAssessment.externalUrl.trim();
                  extLink.target = '_blank';
                  extLink.rel = 'noopener noreferrer';
                  setBtnVectorIcon(extLink, 'play', 'Open Assigned Assessment', 'Open external assessment in a new tab');
                  asmActionsRow.appendChild(extLink);
                }

                if (
                  crd.linkedAssessment.pdfFileId &&
                  /^fil_[a-z0-9_-]{4,64}$/i.test(crd.linkedAssessment.pdfFileId)
                ) {
                  var pdfDlBtn = document.createElement('button');
                  pdfDlBtn.type = 'button';
                  pdfDlBtn.className = 'btn btn-secondary btn-sm';
                  setBtnVectorIcon(pdfDlBtn, 'download', 'Download PDF Worksheet', 'Download assessment PDF handout');
                  pdfDlBtn.addEventListener('click', function () {
                    pdfDlBtn.disabled = true;
                    pdfDlBtn.textContent = 'Preparing PDF...';
                    PBObjectUrlManager.triggerAuthorizedDownload(
                      crd.linkedAssessment.pdfFileId,
                      course.courseId,
                      false
                    )
                      .then(function () {
                        pdfDlBtn.disabled = false;
                        setBtnVectorIcon(pdfDlBtn, 'download', 'Download PDF Worksheet', 'Download assessment PDF handout');
                      })
                      .catch(function (err) {
                        pdfDlBtn.disabled = false;
                        setBtnVectorIcon(pdfDlBtn, 'download', 'Download PDF Worksheet', 'Download assessment PDF handout');
                        showUiErrorBanner(err);
                      });
                  });
                  asmActionsRow.appendChild(pdfDlBtn);
                }

                var jumpNativeExamsBtn = document.createElement('button');
                jumpNativeExamsBtn.type = 'button';
                jumpNativeExamsBtn.className = 'btn btn-outline btn-sm';
                setBtnVectorIcon(jumpNativeExamsBtn, 'preview', 'View Online Quizzes & Exams', 'Jump to online quizzes and exams for this course');
                jumpNativeExamsBtn.addEventListener('click', function () {
                  var nativeCard = document.getElementById('student-course-native-exams-card');
                  if (nativeCard && typeof nativeCard.scrollIntoView === 'function') {
                    nativeCard.scrollIntoView({ behavior: 'smooth', block: 'start' });
                  }
                });
                asmActionsRow.appendChild(jumpNativeExamsBtn);

                asmBox.appendChild(asmActionsRow);

                var matchedPubScore = crd.studentPublishedScore || null;
                if (!matchedPubScore && Array.isArray(d.publishedScores) && crd.assessmentId) {
                  for (var psIdx = 0; psIdx < d.publishedScores.length; psIdx++) {
                    if (d.publishedScores[psIdx].assessmentId === crd.assessmentId) {
                      matchedPubScore = d.publishedScores[psIdx];
                      break;
                    }
                  }
                }
                if (matchedPubScore) {
                  var scoreBanner = document.createElement('div');
                  scoreBanner.className = 'pb-assessment-inline-score-banner';
                  scoreBanner.setAttribute('data-published-score-id', matchedPubScore.scoreId || '');

                  var sbHeader = document.createElement('div');
                  sbHeader.className = 'pb-assessment-inline-score-header';

                  var sbLabel = document.createElement('strong');
                  sbLabel.style.color = 'var(--color-brand-deep)';
                  sbLabel.textContent =
                    'Your Published Score: ' +
                    (matchedPubScore.scoreDisplay ||
                      matchedPubScore.scorePoints + ' / ' + matchedPubScore.maxPoints);
                  sbHeader.appendChild(sbLabel);

                  var sbPill = document.createElement('span');
                  sbPill.className = 'pb-score-pill pb-score-pill-high';
                  sbPill.textContent = matchedPubScore.percentageFormatted || '-';
                  sbHeader.appendChild(sbPill);
                  scoreBanner.appendChild(sbHeader);

                  if (matchedPubScore.feedbackText) {
                    var sbFb = document.createElement('p');
                    sbFb.style.margin = '0';
                    sbFb.style.fontSize = '0.86rem';
                    sbFb.style.color = 'var(--color-text-secondary)';
                    sbFb.textContent = 'Instructor Feedback: ' + matchedPubScore.feedbackText;
                    scoreBanner.appendChild(sbFb);
                  }
                  asmBox.appendChild(scoreBanner);
                }

                itemBox.appendChild(asmBox);
              }

              secCard.appendChild(itemBox);
            })(cards[cIdx], cIdx);
          }
        }

        secContainer.appendChild(secCard);
      }
    }

    
    function setAdminInvoicesAlert(variant, title, message) {
      var box = document.getElementById('admin-invoices-alert-box');
      if (!box) {
        return;
      }
      if (variant === 'hidden') {
        box.classList.add('hidden');
        return;
      }
      box.className = 'banner banner-' + (variant || 'success');
      setText('admin-invoices-alert-title', title || 'Invoice Notice');
      setText('admin-invoices-alert-message', message || '');
      box.classList.remove('hidden');
      if (typeof PBNotify === 'object' && PBNotify && typeof PBNotify.toast === 'function') {
        PBNotify.toast(variant || 'success', title || 'Invoice Notice', message || '');
      }
    }

    function populateAdminInvoiceDropdownsStep10(studentsList, coursesList) {
      var stuSel = document.getElementById('select-admin-invoice-student');
      var filterStuSel = document.getElementById('select-admin-invoices-filter-student');
      var currentStuVal = stuSel ? stuSel.value : '';
      var currentFilterStuVal = filterStuSel ? filterStuSel.value : 'ALL';

      if (stuSel) {
        while (stuSel.firstChild) {
          stuSel.removeChild(stuSel.firstChild);
        }
        var defOpt = document.createElement('option');
        defOpt.value = '';
        defOpt.textContent = '-- Select a Student --';
        stuSel.appendChild(defOpt);

        var stus = Array.isArray(studentsList) ? studentsList : [];
        for (var i = 0; i < stus.length; i++) {
          var s = stus[i];
          var opt = document.createElement('option');
          opt.value = s.userId;
          opt.textContent =
            s.username + ' — ' + (s.fullName || s.email || s.userId) + ' (' + s.status + ')';
          stuSel.appendChild(opt);
        }
        if (currentStuVal) {
          stuSel.value = currentStuVal;
        } else if (stus.length > 0) {
          stuSel.value = stus[0].userId;
        }
      }

      if (filterStuSel) {
        while (filterStuSel.firstChild) {
          filterStuSel.removeChild(filterStuSel.firstChild);
        }
        var allOpt = document.createElement('option');
        allOpt.value = 'ALL';
        allOpt.textContent = 'All Students';
        filterStuSel.appendChild(allOpt);

        var stusF = Array.isArray(studentsList) ? studentsList : [];
        for (var j = 0; j < stusF.length; j++) {
          var sf = stusF[j];
          var fOpt = document.createElement('option');
          fOpt.value = sf.userId;
          fOpt.textContent = sf.username + ' (' + (sf.fullName || sf.userId) + ')';
          filterStuSel.appendChild(fOpt);
        }
        if (currentFilterStuVal) {
          filterStuSel.value = currentFilterStuVal;
        }
      }

      var crsSel = document.getElementById('select-admin-invoice-course');
      if (crsSel) {
        var currentCrsVal = crsSel.value;
        while (crsSel.firstChild) {
          crsSel.removeChild(crsSel.firstChild);
        }
        var defCrs = document.createElement('option');
        defCrs.value = '';
        defCrs.textContent = '-- Optional: General Tuition / No Specific Course --';
        crsSel.appendChild(defCrs);

        var crss = Array.isArray(coursesList) ? coursesList : [];
        for (var c = 0; c < crss.length; c++) {
          var cr = crss[c];
          var cOpt = document.createElement('option');
          cOpt.value = cr.courseId;
          cOpt.textContent = '[' + cr.courseCode + '] ' + cr.title + ' (' + cr.status + ')';
          crsSel.appendChild(cOpt);
        }
        if (currentCrsVal) {
          crsSel.value = currentCrsVal;
        }
      }
    }

    function renderAdminInvoicesTableStep10(invoices) {
      var tbody = document.getElementById('admin-invoices-table-tbody');
      if (!tbody) {
        return;
      }
      while (tbody.firstChild) {
        tbody.removeChild(tbody.firstChild);
      }

      var list = Array.isArray(invoices) ? invoices : [];
      if (list.length === 0) {
        var emptyTr = document.createElement('tr');
        var emptyTd = document.createElement('td');
        emptyTd.colSpan = 6;
        emptyTd.style.textAlign = 'center';
        emptyTd.style.padding = '20px';
        emptyTd.style.color = 'var(--color-text-secondary)';
        emptyTd.textContent =
          'No invoices found matching the current filter. Use the form above to create an unpaid student invoice.';
        emptyTr.appendChild(emptyTd);
        tbody.appendChild(emptyTr);
        return;
      }

      for (var i = 0; i < list.length; i++) {
        var inv = list[i];
        var tr = document.createElement('tr');

        /* Col 1: Invoice ID & Student */
        var tdStu = document.createElement('td');
        var stuStrong = document.createElement('strong');
        stuStrong.style.color = 'var(--color-brand-deep)';
        stuStrong.textContent = (inv.studentUsername || inv.userId) + ' ';
        tdStu.appendChild(stuStrong);

        var stuNameDiv = document.createElement('div');
        stuNameDiv.textContent = inv.studentFullName || '-';
        tdStu.appendChild(stuNameDiv);

        var invIdDiv = document.createElement('div');
        invIdDiv.style.fontSize = '0.78rem';
        invIdDiv.style.color = 'var(--color-text-muted)';
        invIdDiv.textContent = inv.invoiceId + ' (v' + String(inv.version || 1) + ')';
        tdStu.appendChild(invIdDiv);

        /* Col 2: Installment Label & Course */
        var tdLabel = document.createElement('td');
        var lblStrong = document.createElement('div');
        lblStrong.style.fontWeight = '700';
        lblStrong.textContent = inv.installmentLabel || '-';
        tdLabel.appendChild(lblStrong);

        if (inv.courseCode || inv.courseId) {
          var crsBadge = document.createElement('span');
          crsBadge.className = 'course-pill';
          crsBadge.style.marginTop = '4px';
          crsBadge.textContent = inv.courseCode || inv.courseId;
          tdLabel.appendChild(crsBadge);
        }

        /* Col 3: Amount (THB) */
        var tdAmt = document.createElement('td');
        var amtStrong = document.createElement('div');
        amtStrong.style.fontWeight = '800';
        amtStrong.style.color = 'var(--color-brand-deep)';
        amtStrong.textContent = inv.amountThbFormatted || (inv.amountThb + ' THB');
        tdAmt.appendChild(amtStrong);

        /* Col 4: Due Date (Asia/Bangkok) */
        var tdDue = document.createElement('td');
        tdDue.textContent = inv.dueDateBkk || '-';

        /* Col 5: Status */
        var tdStatus = document.createElement('td');
        var stBadge = document.createElement('span');
        stBadge.className =
          inv.status === 'PAID'
            ? 'badge badge-ok'
            : inv.status === 'REJECTED' || inv.status === 'CANCELLED'
            ? 'badge badge-danger'
            : 'badge badge-incomplete';
        stBadge.textContent = inv.status || 'UNPAID';
        tdStatus.appendChild(stBadge);

        /* Col 6: Payment Link / Expiry / Notes */
        var tdMeta = document.createElement('td');
        tdMeta.style.fontSize = '0.82rem';
        if (inv.activePaymentId) {
          var payDiv = document.createElement('div');
          payDiv.textContent = 'Payment: ' + inv.activePaymentId;
          tdMeta.appendChild(payDiv);
        }
        if (inv.reservationExpiresAtBangkok) {
          var expDiv = document.createElement('div');
          expDiv.style.color = 'var(--color-warning-text)';
          expDiv.textContent = 'Expires: ' + inv.reservationExpiresAtBangkok;
          tdMeta.appendChild(expDiv);
        }
        if (inv.lastRejectionReason) {
          var rejDiv = document.createElement('div');
          rejDiv.style.color = 'var(--color-danger-text)';
          rejDiv.textContent = 'Rejected: ' + inv.lastRejectionReason;
          tdMeta.appendChild(rejDiv);
        }
        var updDiv = document.createElement('div');
        updDiv.style.color = 'var(--color-text-muted)';
        updDiv.textContent = 'Updated: ' + (inv.updatedAtBangkok || inv.updatedAtUtc || '-');
        tdMeta.appendChild(updDiv);

        tr.appendChild(tdStu);
        tr.appendChild(tdLabel);
        tr.appendChild(tdAmt);
        tr.appendChild(tdDue);
        tr.appendChild(tdStatus);
        tr.appendChild(tdMeta);
        tbody.appendChild(tr);
      }
    }

    var adminCachedInvoicesAllStep10 = [];
    var adminCachedInvoicesCoursesStep10 = [];
    var adminCachedPaymentsAllStep11 = [];
    var currentAdminFinDashboardPeriod = 'ALL';

    function formatSatangThbShortStep10(satangVal) {
      var thbNum = Math.round(Number(satangVal || 0)) / 100;
      try {
        return (
          thbNum.toLocaleString('en-US', {
            minimumFractionDigits: 2,
            maximumFractionDigits: 2
          }) + ' THB'
        );
      } catch (e) {
        return thbNum.toFixed(2) + ' THB';
      }
    }

    function getInvoiceAmountSatangStep10(inv) {
      if (!inv || typeof inv !== 'object') return 0;
      if (inv.amountSatang !== undefined && inv.amountSatang !== null && !isNaN(Number(inv.amountSatang))) {
        return Math.round(Number(inv.amountSatang));
      }
      var thb = parseFloat(String(inv.amountThbFormatted || inv.amountThb || '0').replace(/[^\d.-]/g, ''));
      return isNaN(thb) ? 0 : Math.round(thb * 100);
    }

    function parseFinRecordDateMetaStep10(rec, dateFields) {
      if (!rec || typeof rec !== 'object') return { ms: 0, monthKey: '' };
      var raw = '';
      for (var i = 0; i < dateFields.length; i++) {
        var val = String(rec[dateFields[i]] || '').trim();
        if (val) {
          raw = val;
          break;
        }
      }
      if (!raw) return { ms: 0, monthKey: '' };
      var ymMatch = raw.match(/^(\d{4}-\d{2})/);
      var monthKey = ymMatch ? ymMatch[1] : '';
      var parsedMs = Date.parse(raw);
      if (isNaN(parsedMs)) {
        var bkkMatch = raw.match(/^(\d{4})-(\d{2})-(\d{2})\s+(\d{2}):(\d{2})(?::(\d{2}))?/);
        if (bkkMatch) {
          parsedMs =
            Date.UTC(
              Number(bkkMatch[1]),
              Number(bkkMatch[2]) - 1,
              Number(bkkMatch[3]),
              Number(bkkMatch[4]),
              Number(bkkMatch[5]),
              Number(bkkMatch[6] || 0)
            ) -
            7 * 3600 * 1000;
        } else {
          parsedMs = 0;
        }
      } else if (!monthKey) {
        var d = new Date(parsedMs + 7 * 3600 * 1000);
        var m = String(d.getUTCMonth() + 1);
        monthKey = String(d.getUTCFullYear()) + '-' + (m.length < 2 ? '0' + m : m);
      }
      return { ms: parsedMs, monthKey: monthKey };
    }

    function filterFinRecordsByPeriodStep10(records, dateFields, periodKey) {
      var list = Array.isArray(records) ? records : [];
      if (!periodKey || periodKey === 'ALL') return list;
      var curYm = typeof getCurrentBangkokYearMonthStep13 === 'function'
        ? getCurrentBangkokYearMonthStep13()
        : '';
      var nowMs = Date.now();
      var cutoffMs = periodKey === 'LAST_30D'
        ? nowMs - 30 * 86400000
        : periodKey === 'LAST_90D'
          ? nowMs - 90 * 86400000
          : 0;
      var out = [];
      for (var i = 0; i < list.length; i++) {
        var meta = parseFinRecordDateMetaStep10(list[i], dateFields);
        if (periodKey === 'THIS_MONTH') {
          if (meta.monthKey && meta.monthKey === curYm) {
            out.push(list[i]);
          }
        } else if (cutoffMs > 0) {
          if (meta.ms >= cutoffMs) {
            out.push(list[i]);
          }
        }
      }
      return out;
    }

    function shiftYearMonthStep10(ymStr, deltaMonths) {
      var m = String(ymStr || '').match(/^(\d{4})-(\d{2})$/);
      if (!m) return ymStr;
      var totalMonths = Number(m[1]) * 12 + (Number(m[2]) - 1) + Number(deltaMonths || 0);
      var yr = Math.floor(totalMonths / 12);
      var mo = (totalMonths % 12) + 1;
      return String(yr) + '-' + (mo < 10 ? '0' + mo : String(mo));
    }

    function formatShortMonthLabelStep10(ymStr) {
      var names = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
      var m = String(ymStr || '').match(/^(\d{4})-(\d{2})$/);
      if (!m) return ymStr;
      var idx = Number(m[2]) - 1;
      return (names[idx] || m[2]) + ' ' + m[1].slice(2);
    }

    function renderAdminFinancialDashboardStep10() {
      var invAll = Array.isArray(adminCachedInvoicesAllStep10) ? adminCachedInvoicesAllStep10 : [];
      var payAll = Array.isArray(adminCachedPaymentsAllStep11) ? adminCachedPaymentsAllStep11 : [];
      var period = currentAdminFinDashboardPeriod || 'ALL';

      var filteredInvoices = filterFinRecordsByPeriodStep10(
        invAll,
        ['paidAtBangkok', 'paidAtUtc', 'updatedAtBangkok', 'updatedAtUtc', 'createdAtBangkok', 'createdAtUtc'],
        period
      );
      var filteredPayments = filterFinRecordsByPeriodStep10(
        payAll,
        ['verifiedAtBangkok', 'verifiedAtUtc', 'submittedAtBangkok', 'submittedAtUtc', 'createdAtBangkok', 'createdAtUtc'],
        period
      );

      var collectedSatang = 0;
      var paidCount = 0;
      var awaitingSatang = 0;
      var awaitingCount = 0;
      var unpaidSatang = 0;
      var unpaidCount = 0;
      var totalBilledSatang = 0;

      var monthPaidMap = {};
      var latestPaidYm = '';
      var courseStatsMap = {};
      var courseTitleLookup = {};
      for (var cIdx = 0; cIdx < adminCachedInvoicesCoursesStep10.length; cIdx++) {
        var cObj = adminCachedInvoicesCoursesStep10[cIdx];
        if (cObj && cObj.courseId) {
          courseTitleLookup[cObj.courseId] =
            (cObj.courseCode ? cObj.courseCode + ' — ' : '') + (cObj.title || cObj.courseId);
        }
      }

      for (var i = 0; i < filteredInvoices.length; i++) {
        var inv = filteredInvoices[i];
        var st = String(inv.status || '').toUpperCase();
        var sat = getInvoiceAmountSatangStep10(inv);
        totalBilledSatang += sat;

        var cKey = inv.courseId || '_GENERAL_';
        if (!courseStatsMap[cKey]) {
          courseStatsMap[cKey] = {
            courseId: cKey,
            label:
              courseTitleLookup[cKey] ||
              ((inv.courseCode ? inv.courseCode + ' — ' : '') + (inv.courseTitle || inv.courseId || 'Other Tuition')),
            collectedSatang: 0,
            billedSatang: 0,
            paidCount: 0,
            totalCount: 0
          };
        }
        courseStatsMap[cKey].billedSatang += sat;
        courseStatsMap[cKey].totalCount += 1;

        if (st === 'PAID') {
          collectedSatang += sat;
          paidCount += 1;
          courseStatsMap[cKey].collectedSatang += sat;
          courseStatsMap[cKey].paidCount += 1;
          var dMeta = parseFinRecordDateMetaStep10(inv, [
            'paidAtBangkok',
            'paidAtUtc',
            'updatedAtBangkok',
            'updatedAtUtc',
            'createdAtBangkok',
            'createdAtUtc'
          ]);
          if (dMeta.monthKey) {
            monthPaidMap[dMeta.monthKey] = (monthPaidMap[dMeta.monthKey] || 0) + sat;
            if (!latestPaidYm || dMeta.monthKey > latestPaidYm) {
              latestPaidYm = dMeta.monthKey;
            }
          }
        } else if (st === 'AWAITING_VERIFICATION' || st === 'APPROVING') {
          awaitingSatang += sat;
          awaitingCount += 1;
        } else {
          unpaidSatang += sat;
          unpaidCount += 1;
        }
      }

      var avgTicketSatang = paidCount > 0 ? Math.round(collectedSatang / paidCount) : 0;
      var collectionRatePct = totalBilledSatang > 0 ? (collectedSatang / totalBilledSatang) * 100 : 0;
      var pipelineSatang = awaitingSatang + unpaidSatang;

      setText('fin-stat-collected-thb', formatSatangThbShortStep10(collectedSatang));
      setText(
        'fin-stat-collected-sub',
        String(paidCount) + ' paid invoice' + (paidCount === 1 ? '' : 's')
      );
      setText('fin-stat-collection-rate', collectionRatePct.toFixed(1) + '%');
      var barEl = document.getElementById('fin-stat-collection-bar');
      if (barEl) {
        barEl.style.width = Math.max(0, Math.min(100, collectionRatePct)).toFixed(1) + '%';
      }
      setText('fin-stat-collection-sub', 'Of ' + formatSatangThbShortStep10(totalBilledSatang) + ' billed');
      setText('fin-stat-avg-ticket-thb', formatSatangThbShortStep10(avgTicketSatang));
      setText(
        'fin-stat-avg-ticket-sub',
        paidCount > 0 ? 'Across ' + String(paidCount) + ' settled receipts' : 'No paid receipts yet'
      );
      setText('fin-stat-pipeline-thb', formatSatangThbShortStep10(pipelineSatang));
      setText(
        'fin-stat-pipeline-sub',
        String(awaitingCount) +
          ' reviewing (' +
          formatSatangThbShortStep10(awaitingSatang) +
          ') • ' +
          String(unpaidCount) +
          ' unpaid'
      );

      /* Chart 1: Monthly Collected Income SVG Column Chart */
      var chartWrap = document.getElementById('fin-monthly-income-chart-wrap');
      if (chartWrap) {
        clearChildren(chartWrap);
        var curBkkYm =
          typeof getCurrentBangkokYearMonthStep13 === 'function'
            ? getCurrentBangkokYearMonthStep13()
            : '2026-11';
        var anchorYm = latestPaidYm && latestPaidYm > curBkkYm ? latestPaidYm : curBkkYm;
        var months = [];
        var maxSat = 0;
        for (var mOff = -5; mOff <= 0; mOff++) {
          var ym = shiftYearMonthStep10(anchorYm, mOff);
          var mSat = monthPaidMap[ym] || 0;
          if (mSat > maxSat) maxSat = mSat;
          months.push({ ym: ym, satang: mSat });
        }
        setText(
          'fin-chart-trend-badge',
          formatShortMonthLabelStep10(months[0].ym) + ' – ' + formatShortMonthLabelStep10(months[5].ym)
        );

        var svgNs = 'http://www.w3.org/2000/svg';
        var svg = document.createElementNS(svgNs, 'svg');
        svg.setAttribute('viewBox', '0 0 560 186');
        svg.setAttribute('width', '100%');
        svg.setAttribute('height', '186');
        svg.setAttribute('role', 'img');
        svg.setAttribute('aria-label', 'Monthly collected tuition income chart');

        var defs = document.createElementNS(svgNs, 'defs');
        var grad = document.createElementNS(svgNs, 'linearGradient');
        grad.setAttribute('id', 'pbFinBarGrad');
        grad.setAttribute('x1', '0');
        grad.setAttribute('y1', '0');
        grad.setAttribute('x2', '0');
        grad.setAttribute('y2', '1');
        var stop1 = document.createElementNS(svgNs, 'stop');
        stop1.setAttribute('offset', '0%');
        stop1.setAttribute('stop-color', '#06B6D4');
        var stop2 = document.createElementNS(svgNs, 'stop');
        stop2.setAttribute('offset', '100%');
        stop2.setAttribute('stop-color', '#10B981');
        grad.appendChild(stop1);
        grad.appendChild(stop2);
        defs.appendChild(grad);
        svg.appendChild(defs);

        var chartTop = 26;
        var chartBottom = 152;
        var chartH = chartBottom - chartTop;
        for (var g = 0; g <= 3; g++) {
          var gy = chartTop + (chartH / 3) * g;
          var line = document.createElementNS(svgNs, 'line');
          line.setAttribute('x1', '14');
          line.setAttribute('y1', String(gy));
          line.setAttribute('x2', '546');
          line.setAttribute('y2', String(gy));
          line.setAttribute('stroke', g === 3 ? '#CBD5E1' : '#E2E8F0');
          line.setAttribute('stroke-width', '1');
          if (g < 3) line.setAttribute('stroke-dasharray', '4 4');
          svg.appendChild(line);
        }

        var slotW = 520 / months.length;
        var barW = 46;
        for (var bi = 0; bi < months.length; bi++) {
          var item = months[bi];
          var cx = 20 + slotW * bi + slotW / 2;
          var ratio = maxSat > 0 ? item.satang / maxSat : 0;
          var bh = item.satang > 0 ? Math.max(8, Math.round(ratio * (chartH - 12))) : 4;
          var bx = cx - barW / 2;
          var by = chartBottom - bh;

          var rect = document.createElementNS(svgNs, 'rect');
          rect.setAttribute('x', String(bx));
          rect.setAttribute('y', String(by));
          rect.setAttribute('width', String(barW));
          rect.setAttribute('height', String(bh));
          rect.setAttribute('rx', '6');
          rect.setAttribute('fill', item.satang > 0 ? 'url(#pbFinBarGrad)' : '#E2E8F0');
          var titleNode = document.createElementNS(svgNs, 'title');
          titleNode.textContent = item.ym + ': ' + formatSatangThbShortStep10(item.satang);
          rect.appendChild(titleNode);
          svg.appendChild(rect);

          if (item.satang > 0) {
            var valTxt = document.createElementNS(svgNs, 'text');
            valTxt.setAttribute('x', String(cx));
            valTxt.setAttribute('y', String(by - 6));
            valTxt.setAttribute('text-anchor', 'middle');
            valTxt.setAttribute('font-size', '11');
            valTxt.setAttribute('font-weight', '700');
            valTxt.setAttribute('fill', '#0F766E');
            var thb = item.satang / 100;
            valTxt.textContent =
              thb >= 10000
                ? (thb / 1000).toFixed(1) + 'k'
                : thb.toLocaleString('en-US', { maximumFractionDigits: 0 });
            svg.appendChild(valTxt);
          }

          var lblTxt = document.createElementNS(svgNs, 'text');
          lblTxt.setAttribute('x', String(cx));
          lblTxt.setAttribute('y', '172');
          lblTxt.setAttribute('text-anchor', 'middle');
          lblTxt.setAttribute('font-size', '11');
          lblTxt.setAttribute('font-weight', '600');
          lblTxt.setAttribute('fill', '#64748B');
          lblTxt.textContent = formatShortMonthLabelStep10(item.ym);
          svg.appendChild(lblTxt);
        }

        chartWrap.appendChild(svg);
      }

      /* Chart 2: Income by Course List */
      var courseListEl = document.getElementById('fin-course-income-list');
      if (courseListEl) {
        clearChildren(courseListEl);
        var courseRows = Object.keys(courseStatsMap).map(function (k) {
          return courseStatsMap[k];
        });
        courseRows.sort(function (a, b) {
          if (b.collectedSatang !== a.collectedSatang) {
            return b.collectedSatang - a.collectedSatang;
          }
          return b.billedSatang - a.billedSatang;
        });

        setText(
          'fin-chart-courses-badge',
          String(courseRows.length) + ' Course' + (courseRows.length === 1 ? '' : 's')
        );

        if (courseRows.length === 0) {
          var emptyCourseMsg = document.createElement('p');
          emptyCourseMsg.style.margin = '4px 0';
          emptyCourseMsg.style.fontSize = '0.84rem';
          emptyCourseMsg.style.color = '#64748B';
          emptyCourseMsg.textContent = 'No invoice records found for this period.';
          courseListEl.appendChild(emptyCourseMsg);
        } else {
          var topSlice = courseRows.slice(0, 5);
          for (var ci = 0; ci < topSlice.length; ci++) {
            var cr = topSlice[ci];
            var pct = cr.billedSatang > 0 ? Math.round((cr.collectedSatang / cr.billedSatang) * 100) : 0;
            var rowEl = document.createElement('div');
            rowEl.className = 'pb-fin-course-row';

            var topEl = document.createElement('div');
            topEl.className = 'pb-fin-course-row-top';
            var nameEl = document.createElement('span');
            nameEl.className = 'pb-fin-course-name';
            nameEl.textContent = cr.label;
            nameEl.title = cr.label;
            var amtEl = document.createElement('span');
            amtEl.className = 'pb-fin-course-amt';
            amtEl.textContent =
              formatSatangThbShortStep10(cr.collectedSatang) + ' (' + String(pct) + '%)';
            topEl.appendChild(nameEl);
            topEl.appendChild(amtEl);

            var trackEl = document.createElement('div');
            trackEl.className = 'pb-fin-progress-track';
            trackEl.style.marginTop = '2px';
            var fillEl = document.createElement('div');
            fillEl.className = 'pb-fin-progress-fill';
            fillEl.style.width = String(Math.max(0, Math.min(100, pct))) + '%';
            trackEl.appendChild(fillEl);

            rowEl.appendChild(topEl);
            rowEl.appendChild(trackEl);
            courseListEl.appendChild(rowEl);
          }
        }
      }

      /* Payment Method Breakdown (from PAID Payment Sessions) */
      var splitEl = document.getElementById('fin-payment-method-split');
      if (splitEl) {
        clearChildren(splitEl);
        var ppSat = 0;
        var ppCnt = 0;
        var btSat = 0;
        var btCnt = 0;
        for (var pi = 0; pi < filteredPayments.length; pi++) {
          var pObj = filteredPayments[pi];
          if (String(pObj.status || '').toUpperCase() !== 'PAID') continue;
          var pSat = Math.round(Number(pObj.totalAmountSatang || 0));
          var meth = String(pObj.method || '').toUpperCase();
          if (meth === 'PROMPTPAY_QR') {
            ppSat += pSat;
            ppCnt += 1;
          } else {
            btSat += pSat;
            btCnt += 1;
          }
        }
        var splitItems = [
          {
            lbl: 'PromptPay QR Paid',
            val: formatSatangThbShortStep10(ppSat),
            sub: String(ppCnt) + ' verified session' + (ppCnt === 1 ? '' : 's')
          },
          {
            lbl: 'Bank Transfer Paid',
            val: formatSatangThbShortStep10(btSat),
            sub: String(btCnt) + ' verified session' + (btCnt === 1 ? '' : 's')
          }
        ];
        for (var si = 0; si < splitItems.length; si++) {
          var spBox = document.createElement('div');
          spBox.className = 'pb-fin-split-pill';
          var spLbl = document.createElement('span');
          spLbl.className = 'lbl';
          spLbl.textContent = splitItems[si].lbl;
          var spVal = document.createElement('span');
          spVal.className = 'val';
          spVal.textContent = splitItems[si].val;
          var spSub = document.createElement('span');
          spSub.style.fontSize = '0.73rem';
          spSub.style.color = '#64748B';
          spSub.textContent = splitItems[si].sub;
          spBox.appendChild(spLbl);
          spBox.appendChild(spVal);
          spBox.appendChild(spSub);
          splitEl.appendChild(spBox);
        }
      }
    }

    function loadAdminInvoicesStep10() {
      if (
        !currentSessionMeta ||
        !currentSessionMeta.user ||
        currentSessionMeta.user.role !== 'ADMIN' ||
        currentSessionMeta.user.requiresPrivacyAck
      ) {
        return Promise.resolve();
      }

      var filterStuSel = document.getElementById('select-admin-invoices-filter-student');
      var filterStSel = document.getElementById('select-admin-invoices-filter-status');
      var userIdFilterVal = filterStuSel ? filterStuSel.value : 'ALL';
      var statusFilterVal = filterStSel ? filterStSel.value : 'ALL';

      return rpcCallEnvelope(
        'admin.listInvoices',
        {
          userId: userIdFilterVal,
          statusFilter: statusFilterVal
        },
        { suppressErrorBanner: true }
      )
        .then(function (env) {
          var d = env.data || {};
          populateAdminInvoiceDropdownsStep10(d.studentsList || [], d.coursesList || []);
          renderAdminInvoicesTableStep10(d.invoices || []);
          if (Array.isArray(d.coursesList)) {
            adminCachedInvoicesCoursesStep10 = d.coursesList;
          }
          if (userIdFilterVal === 'ALL' && statusFilterVal === 'ALL') {
            adminCachedInvoicesAllStep10 = d.invoices || [];
            renderAdminFinancialDashboardStep10();
          } else {
            rpcCallEnvelope(
              'admin.listInvoices',
              { userId: 'ALL', statusFilter: 'ALL' },
              { suppressErrorBanner: true }
            )
              .then(function (allEnv) {
                var allD = (allEnv && allEnv.data) || {};
                adminCachedInvoicesAllStep10 = allD.invoices || [];
                renderAdminFinancialDashboardStep10();
              })
              .catch(function () {});
          }
          loadAdminPendingPaymentsStep11();

          var counts = d.summaryCounts || {};
          setText('admin-invoices-count-total', String(counts.totalInvoices || 0));
          setText('admin-billing-subview-invoices-badge', String(counts.totalInvoices || 0));
          setText(
            'admin-invoices-count-unpaid',
            String(
              (counts.unpaidCount || 0) +
                (counts.reservedCount || 0) +
                (counts.rejectedCount || 0)
            ) +
              ' (' +
              (counts.totalUnpaidThbFormatted || '0.00 THB') +
              ')'
          );
          var awaitTotal = (counts.awaitingVerificationCount || 0) + (counts.approvingCount || 0);
          setText('admin-invoices-count-awaiting', String(awaitTotal));
          setText('admin-billing-subview-queue-badge', String(awaitTotal));
          setText(
            'admin-invoices-count-paid',
            String(counts.paidCount || 0) +
              ' (' +
              (counts.totalPaidThbFormatted || '0.00 THB') +
              ')'
          );
          return d;
        })
        .catch(function (err) {
          setAdminInvoicesAlert(
            'danger',
            'Failed to Load Invoices (' + (err.code || 'ERR') + ')',
            err.message || ''
          );
        });
    }

    function handleAdminCreateInvoiceSubmit(evt) {
      if (evt && typeof evt.preventDefault === 'function') {
        evt.preventDefault();
      }
      hideUiErrorBanner();
      setAdminInvoicesAlert('hidden');

      var stuSel = document.getElementById('select-admin-invoice-student');
      var crsSel = document.getElementById('select-admin-invoice-course');
      var lblInp = document.getElementById('input-admin-invoice-label');
      var amtInp = document.getElementById('input-admin-invoice-amount-thb');
      var dueInp = document.getElementById('input-admin-invoice-due-date');
      var submitBtn = document.getElementById('btn-admin-create-invoice-submit');

      var payload = {
        userId: stuSel ? stuSel.value.trim() : '',
        courseId: crsSel ? crsSel.value.trim() : '',
        installmentLabel: lblInp ? lblInp.value.trim() : '',
        amountThb: amtInp ? amtInp.value.trim() : '',
        dueDateBkk: dueInp ? dueInp.value.trim() : ''
      };

      if (submitBtn) {
        submitBtn.disabled = true;
      }
      setText(
        'admin-create-invoice-status',
        'Parsing THB into integer satang & creating UNPAID invoice...'
      );

      return rpcCallEnvelope('admin.createInvoice', payload)
        .then(function (env) {
          var d = env.data || {};
          var inv = d.invoice || {};
          setText(
            'admin-create-invoice-status',
            d.savedMessage ||
              'Created invoice ' +
                (inv.invoiceId || '') +
                ' (' +
                (inv.amountThbFormatted || '') +
                ').'
          );
          setAdminInvoicesAlert(
            'success',
            'Unpaid Invoice Created: ' + (inv.invoiceId || ''),
            'Student: ' +
              (inv.studentUsername || inv.userId) +
              ' | Installment: ' +
              (inv.installmentLabel || '') +
              ' | Amount: ' +
              (inv.amountThbFormatted || '') +
              ' (' +
              String(inv.amountSatang || 0) +
              ' satang) | Due: ' +
              (inv.dueDateBkk || '')
          );
          if (lblInp) {
            lblInp.value = '';
          }
          if (amtInp) {
            amtInp.value = '';
          }
          PBAdminActionModal.close();
          renderDiagnosticResult('PASS: Unpaid invoice created via admin.createInvoice', d);
          return loadAdminInvoicesStep10();
        })
        .catch(function (err) {
          setText(
            'admin-create-invoice-status',
            'Error (' + (err.code || 'ERR') + '): ' + (err.message || '')
          );
          setAdminInvoicesAlert(
            'danger',
            'Invoice Creation Blocked (' + (err.code || 'ERR') + ')',
            err.message || ''
          );
        })
        .then(function () {
          if (submitBtn) {
            submitBtn.disabled = false;
          }
        });
    }


