          var subTimeDiv = document.createElement('div');
          subTimeDiv.style.fontSize = '0.78rem';
          subTimeDiv.style.marginTop = '4px';
          subTimeDiv.style.color = 'var(--color-text-secondary)';
          subTimeDiv.textContent =
            'Submitted (BKK): ' +
            (p.submittedAtBangkok || p.createdAtBangkok || '-');
