    function runButtonWithLoadingState(btnEl, busyLabel, promiseFactory) {
      if (!btnEl) {
        return Promise.resolve().then(promiseFactory);
      }
      if (btnEl.dataset && btnEl.dataset.pbBusy === '1') {
        return Promise.resolve();
      }
      var origText = btnEl.textContent;
      var origDisabled = Boolean(btnEl.disabled);
      if (btnEl.dataset) btnEl.dataset.pbBusy = '1';
      btnEl.disabled = true;
      btnEl.classList.add('is-btn-loading');
      btnEl.setAttribute('aria-busy', 'true');
      if (busyLabel) {
        btnEl.textContent = busyLabel;
      }
      function restore() {
        if (btnEl.dataset) delete btnEl.dataset.pbBusy;
        btnEl.disabled = origDisabled;
        btnEl.classList.remove('is-btn-loading');
        btnEl.removeAttribute('aria-busy');
        if (busyLabel) {
          btnEl.textContent = origText;
        }
      }
      var p;
      try {
        p = Promise.resolve().then(promiseFactory);
      } catch (syncErr) {
        restore();
        return Promise.reject(syncErr);
      }
      return p.then(
        function (res) {
          restore();
          return res;
        },
        function (err) {
          restore();
          throw err;
        }
      );
    }

    function renderDirectImageElementIntoStage(stageOrId, fileId, courseId, altText) {
      var stage = typeof stageOrId === 'string' ? document.getElementById(stageOrId) : stageOrId;
      if (!stage) return;
      clearChildren(stage);
      var cleanId = String(fileId || '').trim();
      if (!cleanId) return;

      if (currentQBankLocalImagePreviewDataUrlByIdPhase2 && currentQBankLocalImagePreviewDataUrlByIdPhase2[cleanId]) {
        stage.classList.remove('pb-img-stage-loading');
        var localImg = document.createElement('img');
        localImg.className = 'pb-actual-image-preview';
        localImg.src = currentQBankLocalImagePreviewDataUrlByIdPhase2[cleanId];
        localImg.alt = altText || ('Diagram ' + cleanId);
        stage.appendChild(localImg);
        return;
      }

      stage.classList.add('pb-img-stage-loading');
      var skel = document.createElement('div');
      skel.className = 'pb-skeleton-line';
      skel.style.width = '86%';
      skel.style.height = '82%';
      skel.style.borderRadius = '10px';
      stage.appendChild(skel);

      PBObjectUrlManager.fetchAndCreateObjectUrl(cleanId, courseId || '')
        .then(function (entry) {
          stage.classList.remove('pb-img-stage-loading');
          clearChildren(stage);
          if (entry && entry.objectUrl) {
            currentQBankLocalImagePreviewDataUrlByIdPhase2[cleanId] = entry.objectUrl;
            var img = document.createElement('img');
            img.className = 'pb-actual-image-preview';
            img.src = entry.objectUrl;
            img.alt = altText || entry.originalFilename || ('Diagram ' + cleanId);
            stage.appendChild(img);
          }
        })
        .catch(function () {
          stage.classList.remove('pb-img-stage-loading');
          clearChildren(stage);
          var fallbackSvg =
            'data:image/svg+xml;utf8,' +
            encodeURIComponent(
              '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 180"><rect width="320" height="180" rx="12" fill="#ECFEFF"/><circle cx="160" cy="76" r="34" fill="#CCFBF1" stroke="#0D9488" stroke-width="3"/><path d="M144 76h32M160 60v32" stroke="#0F766E" stroke-width="3" stroke-linecap="round"/><text x="160" y="142" text-anchor="middle" font-family="sans-serif" font-size="13" font-weight="700" fill="#0F766E">Biology Diagram (' +
                cleanId.replace(/[^A-Za-z0-9_-]/g, '') +
                ')</text></svg>'
            );
          var fbImg = document.createElement('img');
          fbImg.className = 'pb-actual-image-preview';
          fbImg.src = fallbackSvg;
          fbImg.alt = altText || ('Diagram ' + cleanId);
          stage.appendChild(fbImg);
        });
    }

    function parseClientImageFileIdsListPhase2(rawVal) {
      if (Array.isArray(rawVal)) {
        return rawVal
          .map(function (x) { return String(x || '').trim(); })
          .filter(Boolean)
          .slice(0, 8);
      }
      var str = String(rawVal || '').trim();
      if (!str) return [];
      var parts = str.split(',');
      var out = [];
      var seen = {};
      for (var i = 0; i < parts.length && out.length < 8; i++) {
        var id = String(parts[i] || '').trim();
        if (id && !seen[id]) {
          seen[id] = true;
          out.push(id);
        }
      }
      return out;
    }

    function updateQBankOptionsCountBadgePhase2() {
      var badge = document.getElementById('qbank-options-count-badge');
      var typeSel = document.getElementById('select-qbank-type');
      var qType = typeSel ? typeSel.value : 'SINGLE_CHOICE';
      if (!badge) return;
      if (qType === 'TRUE_FALSE') {
        badge.textContent = '2 Choices (True / False)';
      } else {
        var lastLetter = String.fromCharCode(64 + Math.max(2, currentQBankActiveOptionCountPhase2));
        badge.textContent = String(currentQBankActiveOptionCountPhase2) + ' Choices (A–' + lastLetter + ')';
      }
    }

    function setQBankOptionRowCountPhase2(targetCount) {
      var count = Math.min(10, Math.max(2, Number(targetCount) || 4));
      currentQBankActiveOptionCountPhase2 = count;

      // Toggle visibility of rows 2 and 3 (C and D) if count < 4
      for (var baseIdx = 0; baseIdx < 4; baseIdx++) {
        var chkEl = document.getElementById('chk-qbank-opt-correct-' + baseIdx);
        var rowEl = chkEl && chkEl.parentNode ? chkEl.parentNode : null;
        if (rowEl && rowEl.classList) {
          rowEl.classList.toggle('hidden', baseIdx >= count);
        }
      }

      var extraHost = document.getElementById('qbank-extra-options-container');
      if (extraHost) {
        // Preserve existing values in extra rows before rebuilding
        var savedExtra = {};
        for (var k = 4; k < 10; k++) {
          var exTxt = document.getElementById('input-qbank-opt-text-' + k);
          var exChk = document.getElementById('chk-qbank-opt-correct-' + k);
          var exPin = document.getElementById('select-qbank-opt-pin-' + k);
          if (exTxt || exChk || exPin) {
            savedExtra[k] = {
              text: exTxt ? exTxt.value : '',
              checked: Boolean(exChk && exChk.checked),
              pin: exPin ? exPin.value : 'NONE'
            };
          }
        }
        clearChildren(extraHost);
        for (var idx = 4; idx < count; idx++) {
          (function (optIndex) {
            var letter = String.fromCharCode(65 + optIndex);
            var row = document.createElement('div');
            row.className = 'qbank-option-edit-row';
            row.style.display = 'flex';
            row.style.gap = '8px';
            row.style.alignItems = 'center';

            var chk = document.createElement('input');
            chk.type = 'checkbox';
            chk.id = 'chk-qbank-opt-correct-' + optIndex;
            chk.setAttribute('aria-label', 'Option ' + letter + ' is correct');
            if (savedExtra[optIndex]) chk.checked = savedExtra[optIndex].checked;
            row.appendChild(chk);

            var strong = document.createElement('strong');
            strong.style.minWidth = '22px';
            strong.textContent = letter + '.';
            row.appendChild(strong);

            var inp = document.createElement('input');
            inp.type = 'text';
            inp.className = 'form-input';
            inp.id = 'input-qbank-opt-text-' + optIndex;
            inp.placeholder = 'Option ' + letter + ' text';
            inp.style.flex = '1';
            if (savedExtra[optIndex]) inp.value = savedExtra[optIndex].text;
            row.appendChild(inp);

            var sel = document.createElement('select');
            sel.className = 'form-input';
            sel.id = 'select-qbank-opt-pin-' + optIndex;
            sel.style.width = '110px';
            sel.style.fontSize = '0.78rem';
            var pins = [
              { v: 'NONE', l: 'Shuffle OK' },
              { v: 'LAST', l: 'Pin Last' },
              { v: 'FIXED', l: 'Pin Fixed' }
            ];
            for (var p = 0; p < pins.length; p++) {
              var o = document.createElement('option');
              o.value = pins[p].v;
              o.textContent = pins[p].l;
              sel.appendChild(o);
            }
            if (savedExtra[optIndex]) sel.value = savedExtra[optIndex].pin;
            row.appendChild(sel);

            var rmBtn = document.createElement('button');
            rmBtn.type = 'button';
            rmBtn.className = 'btn btn-outline btn-sm';
            rmBtn.textContent = 'Remove';
            rmBtn.setAttribute('aria-label', 'Remove Option ' + letter);
            rmBtn.addEventListener('click', function () {
              removeSpecificQBankOptionRowPhase2(optIndex);
            });
            row.appendChild(rmBtn);

            extraHost.appendChild(row);
          })(idx);
        }
      }
      updateQBankOptionsCountBadgePhase2();
    }

    function removeSpecificQBankOptionRowPhase2(removeIdx) {
      if (currentQBankActiveOptionCountPhase2 <= 2) return;
      var allVals = [];
      for (var i = 0; i < currentQBankActiveOptionCountPhase2; i++) {
        if (i === removeIdx) continue;
        var tEl = document.getElementById('input-qbank-opt-text-' + i);
        var cEl = document.getElementById('chk-qbank-opt-correct-' + i);
        var pEl = document.getElementById('select-qbank-opt-pin-' + i);
        allVals.push({
          text: tEl ? tEl.value : '',
          checked: Boolean(cEl && cEl.checked),
          pin: pEl ? pEl.value : 'NONE'
        });
      }
      setQBankOptionRowCountPhase2(allVals.length);
      for (var j = 0; j < allVals.length; j++) {
        var tEl2 = document.getElementById('input-qbank-opt-text-' + j);
        var cEl2 = document.getElementById('chk-qbank-opt-correct-' + j);
        var pEl2 = document.getElementById('select-qbank-opt-pin-' + j);
        if (tEl2) tEl2.value = allVals[j].text;
        if (cEl2) cEl2.checked = allVals[j].checked;
        if (pEl2) pEl2.value = allVals[j].pin;
      }
    }

    function renderQBankEditorImagesGalleryPhase2() {
      var gallery = document.getElementById('qbank-images-preview-gallery');
      var idInp = document.getElementById('input-qbank-image-id');
      if (idInp) {
        idInp.value = currentQBankEditorImageIdsPhase2.join(',');
      }
      if (!gallery) return;
      clearChildren(gallery);

      for (var i = 0; i < currentQBankEditorImageIdsPhase2.length; i++) {
        (function (fid, idx) {
          var card = document.createElement('div');
          card.className = 'pb-qbank-image-card';

          var topRow = document.createElement('div');
          topRow.style.display = 'flex';
          topRow.style.alignItems = 'center';
          topRow.style.justifyContent = 'space-between';
          topRow.style.gap = '4px';
          topRow.style.marginBottom = '6px';

          var badge = document.createElement('span');
          badge.className = 'badge badge-ok';
          badge.style.fontSize = '0.72rem';
          badge.textContent = 'Image ' + (idx + 1);
          topRow.appendChild(badge);

          var delBtn = document.createElement('button');
          delBtn.type = 'button';
          delBtn.className = 'btn btn-outline btn-sm';
          delBtn.style.minHeight = '26px';
          delBtn.style.padding = '2px 8px';
          delBtn.style.fontSize = '0.74rem';
          delBtn.textContent = 'Delete';
          delBtn.setAttribute('data-qbank-remove-image-id', fid);
          delBtn.setAttribute('aria-label', 'Delete image ' + fid);
          delBtn.addEventListener('click', function () {
            removeQBankEditorImageByIdPhase2(fid);
          });
          topRow.appendChild(delBtn);
          card.appendChild(topRow);

          var stageId = 'qbank-editor-img-preview-stage-' + idx;
          var stage = document.createElement('div');
          stage.id = stageId;
          stage.className = 'pb-qbank-image-thumb-stage';
          card.appendChild(stage);

          var fidLabel = document.createElement('div');
          fidLabel.style.fontSize = '0.72rem';
          fidLabel.style.color = 'var(--color-text-secondary)';
          fidLabel.style.wordBreak = 'break-all';
          fidLabel.textContent = fid;
          card.appendChild(fidLabel);

          gallery.appendChild(card);

          renderDirectImageElementIntoStage(stage, fid, '', 'Question Diagram ' + (idx + 1));
        })(currentQBankEditorImageIdsPhase2[i], i);
      }
    }

    function setQBankEditorImagesListPhase2(rawVal) {
      currentQBankEditorImageIdsPhase2 = parseClientImageFileIdsListPhase2(rawVal);
      renderQBankEditorImagesGalleryPhase2();
    }

    function appendQBankEditorImageIdPhase2(fid, opt_localDataUrl) {
      var cleanId = String(fid || '').trim();
      if (!cleanId) return;
      if (opt_localDataUrl) {
        currentQBankLocalImagePreviewDataUrlByIdPhase2[cleanId] = opt_localDataUrl;
      }
      var list = currentQBankEditorImageIdsPhase2.slice();
      if (list.indexOf(cleanId) === -1 && list.length < 8) {
        list.push(cleanId);
      }
      currentQBankEditorImageIdsPhase2 = list;
      renderQBankEditorImagesGalleryPhase2();
    }

    function removeQBankEditorImageByIdPhase2(fid) {
      var cleanId = String(fid || '').trim();
      currentQBankEditorImageIdsPhase2 = currentQBankEditorImageIdsPhase2.filter(function (x) {
        return x !== cleanId;
      });
      renderQBankEditorImagesGalleryPhase2();
    }

    function syncQBankTypePanelsPhase2() {
      var typeSel = document.getElementById('select-qbank-type');
      var qType = typeSel ? typeSel.value : 'SINGLE_CHOICE';
      var choicePanel = document.getElementById('qbank-panel-choices');
      var numPanel = document.getElementById('qbank-panel-numeric');
      var writtenPanel = document.getElementById('qbank-panel-written');

      if (choicePanel) {
        choicePanel.classList.toggle(
          'hidden',
          qType !== 'SINGLE_CHOICE' && qType !== 'MULTIPLE_SELECT' && qType !== 'TRUE_FALSE'
        );
      }
      if (numPanel) {
        numPanel.classList.toggle('hidden', qType !== 'NUMERIC_RESPONSE');
      }
      if (writtenPanel) {
        writtenPanel.classList.toggle(
          'hidden',
          qType !== 'SHORT_ANSWER' && qType !== 'WRITTEN_RESPONSE'
        );
      }
      if (qType === 'TRUE_FALSE') {
        setQBankOptionRowCountPhase2(2);
        var o0 = document.getElementById('input-qbank-opt-text-0');
        var o1 = document.getElementById('input-qbank-opt-text-1');
        if (o0 && !o0.value) o0.value = 'True';
        if (o1 && !o1.value) o1.value = 'False';
      } else if (qType === 'SINGLE_CHOICE' || qType === 'MULTIPLE_SELECT') {
        if (currentQBankActiveOptionCountPhase2 < 3) {
          setQBankOptionRowCountPhase2(4);
        } else {
          updateQBankOptionsCountBadgePhase2();
        }
      }
    }

    function resetQuestionEditorFormPhase2() {
      var idInp = document.getElementById('input-qbank-question-id');
      var verInp = document.getElementById('input-qbank-expected-version');
      if (idInp) idInp.value = '';
      if (verInp) verInp.value = '';
      setText('qbank-editor-mode-badge', 'Create New Question (v1)');
      setText('qbank-editor-heading', 'Create New Biology Question (Immutable v1)');
      setText('qbank-editor-status', '');

      var codeInp = document.getElementById('input-qbank-code');
      var titleInp = document.getElementById('input-qbank-title');
      var typeSel = document.getElementById('select-qbank-type');
      var diffSel = document.getElementById('select-qbank-difficulty');
      var ptsInp = document.getElementById('input-qbank-points');
      var negInp = document.getElementById('input-qbank-neg-points');
      var topInp = document.getElementById('input-qbank-topics');
      var statSel = document.getElementById('select-qbank-status');
      var stimSel = document.getElementById('select-qbank-stimulus');
      var stemTxt = document.getElementById('textarea-qbank-stem');
      var imgIdInp = document.getElementById('input-qbank-image-id');
      var imgAltInp = document.getElementById('input-qbank-image-alt');
      var accSel = document.getElementById('select-qbank-accessible-flag');
      var expTxt = document.getElementById('textarea-qbank-explanation');
      var refInp = document.getElementById('input-qbank-reference');
      var notesInp = document.getElementById('input-qbank-admin-notes');

      if (codeInp) codeInp.value = '';
      if (titleInp) titleInp.value = '';
      if (typeSel) typeSel.value = 'SINGLE_CHOICE';
      if (diffSel) diffSel.value = 'MEDIUM';
      if (ptsInp) ptsInp.value = '2';
      if (negInp) negInp.value = '0';
      if (topInp) topInp.value = '';
      if (statSel) statSel.value = 'PUBLISHED';
      if (stimSel) stimSel.value = '';
      if (stemTxt) stemTxt.value = '';
      if (imgIdInp) imgIdInp.value = '';
      if (imgAltInp) imgAltInp.value = '';
      if (accSel) accSel.value = 'STANDARD_ALT';
      if (expTxt) expTxt.value = '';
      if (refInp) refInp.value = '';
      if (notesInp) notesInp.value = '';

      setQBankOptionRowCountPhase2(4);
      for (var i = 0; i < 4; i++) {
        var chk = document.getElementById('chk-qbank-opt-correct-' + i);
        var txt = document.getElementById('input-qbank-opt-text-' + i);
        var pin = document.getElementById('select-qbank-opt-pin-' + i);
        if (chk) chk.checked = i === 0;
        if (txt) txt.value = '';
        if (pin) pin.value = 'NONE';
      }
      setQBankEditorImagesListPhase2([]);
      syncQBankTypePanelsPhase2();
    }

    function populateQuestionEditorForEditPhase2(q) {
      if (!q) {
        resetQuestionEditorFormPhase2();
        return;
      }
      var idInp = document.getElementById('input-qbank-question-id');
      var verInp = document.getElementById('input-qbank-expected-version');
      if (idInp) idInp.value = q.questionId || '';
      if (verInp) verInp.value = String(q.version || 1);
      setText(
        'qbank-editor-mode-badge',
        'Edit Question (Creates Immutable v' + String((Number(q.latestVersionNo) || 1) + 1) + ')'
      );
      setText('qbank-editor-heading', 'Edit Question: [' + q.questionCode + '] ' + q.title);
      setText('qbank-editor-status', '');

      var codeInp = document.getElementById('input-qbank-code');
      var titleInp = document.getElementById('input-qbank-title');
      var typeSel = document.getElementById('select-qbank-type');
      var diffSel = document.getElementById('select-qbank-difficulty');
      var ptsInp = document.getElementById('input-qbank-points');
      var negInp = document.getElementById('input-qbank-neg-points');
      var topInp = document.getElementById('input-qbank-topics');
      var statSel = document.getElementById('select-qbank-status');
      var stimSel = document.getElementById('select-qbank-stimulus');
      var stemTxt = document.getElementById('textarea-qbank-stem');
      var imgIdInp = document.getElementById('input-qbank-image-id');
      var imgAltInp = document.getElementById('input-qbank-image-alt');
      var accSel = document.getElementById('select-qbank-accessible-flag');
      var expTxt = document.getElementById('textarea-qbank-explanation');
      var refInp = document.getElementById('input-qbank-reference');
      var notesInp = document.getElementById('input-qbank-admin-notes');

      if (codeInp) codeInp.value = q.questionCode || '';
      if (titleInp) titleInp.value = q.title || '';
      if (typeSel) typeSel.value = q.questionType || 'SINGLE_CHOICE';
      if (diffSel) diffSel.value = q.difficulty || 'MEDIUM';
      if (ptsInp) ptsInp.value = String((Number(q.defaultPointsBp) || 100) / 100);
      if (negInp) negInp.value = String((Number(q.negativePointsBp) || 0) / 100);
      if (topInp) topInp.value = Array.isArray(q.topicTags) ? q.topicTags.join(', ') : '';
      if (statSel) statSel.value = q.status || 'PUBLISHED';
      if (stimSel) stimSel.value = q.stimulusId || '';
      if (stemTxt) stemTxt.value = q.stemPlainText || '';
      var qImgs = Array.isArray(q.imageFileIds) && q.imageFileIds.length > 0
        ? q.imageFileIds
        : (q.imageFileId ? parseClientImageFileIdsListPhase2(q.imageFileId) : []);
      setQBankEditorImagesListPhase2(qImgs);
      if (imgAltInp) imgAltInp.value = q.imageAltText || '';
      if (accSel) accSel.value = q.accessibleDesignFlag || 'STANDARD_ALT';

      var priv = q.privateGradingData || {};
      var gSpec = priv.gradingSpec || {};
      if (expTxt) expTxt.value = priv.explanationPlainText || '';
      if (refInp) refInp.value = priv.referenceText || '';
      if (notesInp) notesInp.value = priv.adminNotes || '';

      var opts = Array.isArray(q.options) ? q.options : [];
      var desiredOptRows = q.questionType === 'TRUE_FALSE' ? 2 : Math.min(10, Math.max(4, opts.length));
      setQBankOptionRowCountPhase2(desiredOptRows);
      for (var i = 0; i < desiredOptRows; i++) {
        var chk = document.getElementById('chk-qbank-opt-correct-' + i);
        var txt = document.getElementById('input-qbank-opt-text-' + i);
        var pin = document.getElementById('select-qbank-opt-pin-' + i);
        var op = opts[i] || null;
        if (chk) chk.checked = Boolean(op && op.isCorrect);
        if (txt) txt.value = op ? op.plainText || '' : '';
        if (pin) pin.value = op && op.pinPosition ? op.pinPosition : 'NONE';
      }

      var msRuleSel = document.getElementById('select-qbank-multiselect-rule');
      if (msRuleSel && gSpec.scoringRule) {
        msRuleSel.value = gSpec.scoringRule;
      }

      var numModeSel = document.getElementById('select-qbank-num-mode');
      var numUnitInp = document.getElementById('input-qbank-num-unit');
      var numTargetInp = document.getElementById('input-qbank-num-target');
      var numTolTypeSel = document.getElementById('select-qbank-num-tol-type');
      var numTolValInp = document.getElementById('input-qbank-num-tol-val');
      var numRoundInp = document.getElementById('input-qbank-num-rounding');
      var numMinInp = document.getElementById('input-qbank-num-min');
      var numMaxInp = document.getElementById('input-qbank-num-max');
      if (numModeSel && gSpec.matchMode) numModeSel.value = gSpec.matchMode;
      if (numUnitInp) numUnitInp.value = q.unitLabel || '';
      if (numTargetInp && gSpec.targetValue !== undefined) numTargetInp.value = String(gSpec.targetValue);
      if (numTolTypeSel && gSpec.toleranceType) numTolTypeSel.value = gSpec.toleranceType;
      if (numTolValInp && gSpec.toleranceValue !== undefined) numTolValInp.value = String(gSpec.toleranceValue);
      if (numRoundInp) numRoundInp.value = gSpec.roundingDecimals !== null && gSpec.roundingDecimals !== undefined ? String(gSpec.roundingDecimals) : '';
      if (numMinInp && gSpec.rangeMin !== undefined) numMinInp.value = String(gSpec.rangeMin);
      if (numMaxInp && gSpec.rangeMax !== undefined) numMaxInp.value = String(gSpec.rangeMax);

      var saModeSel = document.getElementById('select-qbank-sa-grading-mode');
      var maxCharsInp = document.getElementById('input-qbank-max-chars');
      var accAnsTxt = document.getElementById('textarea-qbank-accepted-answers');
      var rubTxt = document.getElementById('textarea-qbank-rubric-model');
      if (saModeSel && q.gradingMode) saModeSel.value = q.gradingMode;
      if (maxCharsInp && q.maxLengthChars) maxCharsInp.value = String(q.maxLengthChars);
      if (accAnsTxt) accAnsTxt.value = Array.isArray(gSpec.acceptedAnswers) ? gSpec.acceptedAnswers.join('\n') : '';
      if (rubTxt) rubTxt.value = gSpec.sampleModelAnswer || gSpec.rubricNotes || '';

      syncQBankTypePanelsPhase2();
    }

    function renderQuestionBankTablePhase2(bundle) {
      var d = bundle || {};
      var list = Array.isArray(d.questions) ? d.questions : [];
      var summary = d.summary || {};
      var pag = d.pagination || { page: 1, totalPages: 1, totalFiltered: 0 };
      var stimuli = Array.isArray(d.stimuli) ? d.stimuli : [];
      currentQBankQuestionsPhase2 = list;
      currentQBankStimuliCachePhase2 = stimuli;

      var cStatus = summary.countsByStatus || {};
      setText('qbank-kpi-total', String(summary.totalQuestionsInBank || 0));
      setText('qbank-kpi-published', String(cStatus.PUBLISHED || 0));
      setText(
        'qbank-kpi-draft',
        String(cStatus.DRAFT || 0) + ' Draft / ' + String(cStatus.ARCHIVED || 0) + ' Archived'
      );
      setText('qbank-kpi-stimuli', String(stimuli.length));

      /* Populate topic filter dropdown & stimulus dropdown */
      var topicSel = document.getElementById('select-qbank-topic-filter');
      if (topicSel && Array.isArray(summary.availableTopics)) {
        var prevTopic = topicSel.value || 'ALL';
        clearChildren(topicSel);
        var allOpt = document.createElement('option');
        allOpt.value = 'ALL';
        allOpt.textContent = 'All Topics';
        topicSel.appendChild(allOpt);
        for (var tIdx = 0; tIdx < summary.availableTopics.length; tIdx++) {
          var tName = summary.availableTopics[tIdx];
          var oEl = document.createElement('option');
          oEl.value = tName;
          oEl.textContent = tName;
          topicSel.appendChild(oEl);
        }
        topicSel.value = prevTopic;
      }

      var stimSel = document.getElementById('select-qbank-stimulus');
      if (stimSel) {
        var prevStim = stimSel.value || '';
        clearChildren(stimSel);
        var noneOpt = document.createElement('option');
        noneOpt.value = '';
        noneOpt.textContent = '-- None (Standalone Question) --';
        stimSel.appendChild(noneOpt);
        for (var sIdx = 0; sIdx < stimuli.length; sIdx++) {
          var st = stimuli[sIdx];
          var sOpt = document.createElement('option');
          sOpt.value = st.stimulusId;
          sOpt.textContent = '[' + st.stimulusCode + '] ' + st.title;
          stimSel.appendChild(sOpt);
        }
        stimSel.value = prevStim;
      }

      /* Render stimuli chips */
      var stimListBox = document.getElementById('admin-stimuli-list-container');
      if (stimListBox) {
        clearChildren(stimListBox);
        if (stimuli.length === 0) {
          var noStSpan = document.createElement('span');
          noStSpan.style.fontSize = '0.84rem';
          noStSpan.style.color = 'var(--color-text-secondary)';
          noStSpan.textContent = 'No shared stimuli created yet.';
          stimListBox.appendChild(noStSpan);
        } else {
          for (var sm = 0; sm < stimuli.length; sm++) {
            (function (stItem) {
              var chipBtn = document.createElement('button');
              chipBtn.type = 'button';
              chipBtn.className = 'btn btn-outline btn-sm';
              chipBtn.textContent = '[' + stItem.stimulusCode + '] ' + stItem.title + ' (v' + stItem.version + ')';
              chipBtn.addEventListener('click', function () {
                var idEl = document.getElementById('input-stimulus-id');
                var verEl = document.getElementById('input-stimulus-expected-version');
                var codeEl = document.getElementById('input-stimulus-code');
                var titleEl = document.getElementById('input-stimulus-title');
                var topEl = document.getElementById('input-stimulus-topics');
                var statEl = document.getElementById('select-stimulus-status');
                var txtEl = document.getElementById('textarea-stimulus-content');
                if (idEl) idEl.value = stItem.stimulusId;
                if (verEl) verEl.value = String(stItem.version || 1);
                if (codeEl) codeEl.value = stItem.stimulusCode;
                if (titleEl) titleEl.value = stItem.title;
                if (topEl) topEl.value = (stItem.topicTags || []).join(', ');
                if (statEl) statEl.value = stItem.status || 'PUBLISHED';
                if (txtEl) txtEl.value = stItem.plainTextSummary || '';
                PBAdminActionModal.open('admin-stimulus-editor-card', 'Edit Shared Stimulus: ' + stItem.stimulusCode);
              });
              stimListBox.appendChild(chipBtn);
            })(stimuli[sm]);
          }
        }
      }

      /* Render Question Bank Table */
      var tbody = document.getElementById('admin-qbank-table-tbody');
      if (!tbody) return;
      clearChildren(tbody);

      if (list.length === 0) {
        var emptyTr = document.createElement('tr');
        var emptyTd = document.createElement('td');
        emptyTd.colSpan = 6;
        emptyTd.style.textAlign = 'center';
        emptyTd.style.padding = '20px';
        emptyTd.style.color = 'var(--color-text-secondary)';
        emptyTd.textContent =
          'No questions match the current filters. Click "Seed 6 Sample Biology Questions" or "+ New Question" to add items.';
        emptyTr.appendChild(emptyTd);
        tbody.appendChild(emptyTr);
      } else {
        for (var i = 0; i < list.length; i++) {
          (function (q) {
            var tr = document.createElement('tr');

            /* Col 1: Code & Title + Stem snippet */
            var td1 = document.createElement('td');
            var codeStrong = document.createElement('strong');
            codeStrong.style.color = 'var(--color-brand-deep)';
            codeStrong.textContent = '[' + q.questionCode + '] ' + q.title;
            td1.appendChild(codeStrong);
            var stemDiv = document.createElement('div');
            stemDiv.style.fontSize = '0.8rem';
            stemDiv.style.color = 'var(--color-text-secondary)';
            stemDiv.style.marginTop = '3px';
            var snippet = String(q.stemPlainText || '').slice(0, 110);
            stemDiv.textContent = snippet + (String(q.stemPlainText || '').length > 110 ? '...' : '');
            td1.appendChild(stemDiv);
            if (q.stimulus) {
              var stimBadge = document.createElement('span');
              stimBadge.className = 'badge badge-ok';
              stimBadge.style.fontSize = '0.68rem';
              stimBadge.style.marginTop = '4px';
              stimBadge.textContent = 'Shared Stimulus: ' + q.stimulus.stimulusCode;
              td1.appendChild(stimBadge);
            }

            /* Col 2: Type & Grading Mode */
            var td2 = document.createElement('td');
            var typeBadge = document.createElement('span');
            typeBadge.className = 'badge badge-ok';
            typeBadge.textContent = q.questionType;
            td2.appendChild(typeBadge);
            var gmDiv = document.createElement('div');
            gmDiv.style.fontSize = '0.76rem';
            gmDiv.style.color = 'var(--color-text-muted)';
            gmDiv.style.marginTop = '4px';
            gmDiv.textContent = 'Grading: ' + q.gradingMode;
            td2.appendChild(gmDiv);

            /* Col 3: Topics & Difficulty */
            var td3 = document.createElement('td');
            var diffBadge = document.createElement('span');
            diffBadge.className = q.difficulty === 'OLYMPIAD' || q.difficulty === 'HARD' ? 'badge badge-incomplete' : 'badge badge-ok';
            diffBadge.textContent = q.difficulty;
            td3.appendChild(diffBadge);
            var tagsDiv = document.createElement('div');
            tagsDiv.style.fontSize = '0.76rem';
            tagsDiv.style.marginTop = '4px';
            tagsDiv.textContent = (q.topicTags || []).join(', ') || 'General Biology';
            td3.appendChild(tagsDiv);

            /* Col 4: Points & Immutable Version */
            var td4 = document.createElement('td');
            var ptsStrong = document.createElement('strong');
            ptsStrong.textContent = q.defaultPointsDisplay;
            td4.appendChild(ptsStrong);
            var verDiv = document.createElement('div');
            verDiv.style.fontSize = '0.76rem';
            verDiv.style.color = 'var(--color-text-secondary)';
            verDiv.textContent =
              'Version ' + q.versionNo + ' (' + q.usedInAttemptsCount + ' attempts)';
            td4.appendChild(verDiv);

            /* Col 5: Status */
            var td5 = document.createElement('td');
            var stBadge = document.createElement('span');
            stBadge.className =
              q.status === 'PUBLISHED'
                ? 'badge badge-ok'
                : q.status === 'ARCHIVED'
                ? 'badge badge-danger'
                : 'badge badge-incomplete';
            stBadge.textContent = q.status;
            td5.appendChild(stBadge);

            /* Col 6: Actions */
            var td6 = document.createElement('td');
            var actRow = document.createElement('div');
            actRow.className = 'pb-users-actions-inline-row';

            var prevBtn = document.createElement('button');
            prevBtn.type = 'button';
            prevBtn.className = 'btn btn-secondary btn-sm';
            setBtnVectorIcon(prevBtn, 'preview', 'Preview', 'Preview question');
            prevBtn.addEventListener('click', function () {
              runButtonWithLoadingState(prevBtn, 'Loading...', function () {
                return openQuestionStudentPreviewModalPhase2(q.questionId, false);
              });
            });
            actRow.appendChild(prevBtn);

            var editBtn = document.createElement('button');
            editBtn.type = 'button';
            editBtn.className = 'btn btn-primary btn-sm';
            setBtnVectorIcon(editBtn, 'edit', 'Edit', 'Edit question');
            editBtn.addEventListener('click', function () {
              populateQuestionEditorForEditPhase2(q);
              PBAdminActionModal.open('admin-question-editor-card', 'Edit Question: ' + q.questionCode);
            });
            actRow.appendChild(editBtn);

            var dupBtn = document.createElement('button');
            dupBtn.type = 'button';
            dupBtn.className = 'btn btn-outline btn-sm';
            setBtnVectorIcon(dupBtn, 'duplicate', 'Copy', 'Duplicate question');
            dupBtn.addEventListener('click', function () {
              runButtonWithLoadingState(dupBtn, 'Duplicating...', function () {
                return rpcCallEnvelope('admin.questions.duplicate', { questionId: q.questionId })
                  .then(function (env) {
                    invalidateQBankClientCachePhase2();
                    renderQuestionBankTablePhase2(env.data);
                    PBNotify.toast('success', 'Question Duplicated', 'Created draft copy of ' + q.questionCode + '.');
                  });
              });
            });
            actRow.appendChild(dupBtn);

            var archBtn = document.createElement('button');
            archBtn.type = 'button';
            archBtn.className = 'btn btn-outline btn-sm';
            setBtnVectorIcon(
              archBtn,
              q.status === 'ARCHIVED' ? 'restore' : 'archive',
              q.status === 'ARCHIVED' ? 'Restore' : 'Archive',
              q.status === 'ARCHIVED' ? 'Restore question' : 'Archive question'
            );
            archBtn.addEventListener('click', function () {
              var nextMode = q.status === 'ARCHIVED' ? 'RESTORE_PUBLISHED' : 'ARCHIVE';
              runButtonWithLoadingState(archBtn, 'Updating...', function () {
                return rpcCallEnvelope('admin.questions.archive', {
                  questionId: q.questionId,
                  mode: nextMode
                }).then(function (env) {
                  invalidateQBankClientCachePhase2();
                  renderQuestionBankTablePhase2(env.data);
                  PBNotify.toast('info', 'Question Status Updated', q.questionCode + ' updated.');
                });
              });
            });
            actRow.appendChild(archBtn);

            td6.appendChild(actRow);

            tr.appendChild(td1);
            tr.appendChild(td2);
            tr.appendChild(td3);
            tr.appendChild(td4);
            tr.appendChild(td5);
            tr.appendChild(td6);
            tbody.appendChild(tr);
          })(list[i]);
        }
      }

      setText(
        'qbank-pagination-summary',
        'Page ' + pag.page + ' of ' + pag.totalPages + ' (' + pag.totalFiltered + ' matching questions)'
      );
      var prevPageBtn = document.getElementById('btn-qbank-prev-page');
      var nextPageBtn = document.getElementById('btn-qbank-next-page');
      if (prevPageBtn) prevPageBtn.disabled = !pag.hasPrevPage;
      if (nextPageBtn) nextPageBtn.disabled = !pag.hasNextPage;
    }

    function loadAdminQuestionBankPhase2(opt_page, opt_forceFresh) {
      if (opt_page) currentQBankPagePhase2 = opt_page;
      var sInp = document.getElementById('input-qbank-search');
      var topSel = document.getElementById('select-qbank-topic-filter');
      var typSel = document.getElementById('select-qbank-type-filter');
      var difSel = document.getElementById('select-qbank-difficulty-filter');
      var stSel = document.getElementById('select-qbank-status-filter');

      var reqPayload = {
        search: sInp ? sInp.value.trim() : '',
        topic: topSel ? topSel.value : 'ALL',
        questionType: typSel ? typSel.value : 'ALL',
        difficulty: difSel ? difSel.value : 'ALL',
        status: stSel ? stSel.value : 'ALL',
        page: currentQBankPagePhase2,
        limit: 15,
        includePrivate: true
      };
      var cacheKey = JSON.stringify(reqPayload);
      if (!opt_forceFresh && qbankResponseCacheByFilterKeyPhase2[cacheKey]) {
        renderQuestionBankTablePhase2(qbankResponseCacheByFilterKeyPhase2[cacheKey]);
      }

      return rpcCallEnvelope('admin.questions.list', reqPayload).then(function (env) {
        if (env && env.data) {
          qbankResponseCacheByFilterKeyPhase2[cacheKey] = env.data;
          renderQuestionBankTablePhase2(env.data);
        }
        return env.data;
      });
    }

    function openQuestionStudentPreviewModalPhase2(questionId, showAnswerKey) {
      currentQBankPreviewQuestionIdPhase2 = questionId;
      currentQBankPreviewShowKeyPhase2 = Boolean(showAnswerKey);
      setText('qbank-preview-mode-badge', 'Loading Question Preview...');
      setText('qbank-preview-heading', 'Loading Question (' + (questionId || '') + ')...');
      renderModalSkeletonBlock('qbank-preview-body-container', 2);
      if (typeof PBAdminActionModal === 'object' && PBAdminActionModal) {
        PBAdminActionModal.open('admin-question-preview-card', 'Student Preview: Loading Question...');
      }
      return rpcCallEnvelope('admin.questions.preview', {
        questionId: questionId,
        includeAnswerKey: currentQBankPreviewShowKeyPhase2
      }).then(function (env) {
        var d = env.data || {};
        var q = d.studentQuestionView || {};
        var host = document.getElementById('qbank-preview-body-container');
        if (!host) return;
        clearChildren(host);

        setText(
          'qbank-preview-mode-badge',
          currentQBankPreviewShowKeyPhase2
            ? 'Admin Key Inspector Active (Private Grading Data Shown)'
            : 'Pure Student View (All Private Grading Keys & Explanations Stripped)'
        );
        setText('qbank-preview-heading', '[' + (q.questionCode || '') + '] ' + (q.title || 'Question Preview'));

        /* 1. Shared Stimulus Box (if attached) */
        if (q.stimulus) {
          var stimBox = document.createElement('div');
          stimBox.className = 'status-item';
          stimBox.style.marginBottom = '14px';
          stimBox.style.background = '#F0FDFA';
          stimBox.style.borderColor = '#0891B2';

          var stimBadge = document.createElement('span');
          stimBadge.className = 'badge badge-ok';
          stimBadge.textContent = 'Shared Stimulus: ' + q.stimulus.title;
          stimBox.appendChild(stimBadge);

          var stimContent = document.createElement('div');
          stimContent.style.marginTop = '8px';
          renderRichTextDocumentToDom(stimContent, q.stimulus.contentRichText, '');
          stimBox.appendChild(stimContent);
          host.appendChild(stimBox);
        }

        /* 2. Question Header & Stem */
        var qBox = document.createElement('div');
        qBox.className = 'status-item';
        var metaBar = document.createElement('div');
        metaBar.style.display = 'flex';
        metaBar.style.gap = '8px';
        metaBar.style.flexWrap = 'wrap';
        metaBar.style.marginBottom = '8px';

        var bType = document.createElement('span');
        bType.className = 'badge badge-ok';
        bType.textContent = q.questionType + ' | ' + q.defaultPointsDisplay;
        metaBar.appendChild(bType);

        if (q.selectionInstruction) {
          var instSpan = document.createElement('span');
          instSpan.style.fontSize = '0.84rem';
          instSpan.style.fontWeight = '600';
          instSpan.style.color = 'var(--color-text-secondary)';
          instSpan.textContent = q.selectionInstruction;
          metaBar.appendChild(instSpan);
        }
        qBox.appendChild(metaBar);

        var stemContainer = document.createElement('div');
        stemContainer.style.fontSize = '1rem';
        stemContainer.style.marginBottom = '12px';
        renderRichTextDocumentToDom(stemContainer, q.stemRichText, '');
        qBox.appendChild(stemContainer);

        var previewImgIds = Array.isArray(q.imageFileIds) && q.imageFileIds.length > 0
          ? q.imageFileIds
          : (q.imageFileId ? parseClientImageFileIdsListPhase2(q.imageFileId) : []);
        if (previewImgIds.length > 0) {
          var prevGallery = document.createElement('div');
          prevGallery.className = 'pb-qbank-image-gallery';
          prevGallery.style.marginBottom = '12px';
          qBox.appendChild(prevGallery);
          for (var pImgIdx = 0; pImgIdx < previewImgIds.length; pImgIdx++) {
            (function (fid, idxNum) {
              var stgId = 'qbank-student-preview-img-' + idxNum;
              var stg = document.createElement('div');
              stg.id = stgId;
              stg.className = 'pb-qbank-image-thumb-stage';
              stg.style.height = '180px';
              prevGallery.appendChild(stg);
              renderDirectImageElementIntoStage(stg, fid, '', q.imageAltText || 'Question Diagram ' + (idxNum + 1));
            })(previewImgIds[pImgIdx], pImgIdx);
          }
        }

        /* 3. Interactive Student Input Controls by Question Type */
        if (
          q.questionType === 'SINGLE_CHOICE' ||
          q.questionType === 'MULTIPLE_SELECT' ||
          q.questionType === 'TRUE_FALSE'
        ) {
          var isMulti = q.questionType === 'MULTIPLE_SELECT';
          var optsWrap = document.createElement('div');
          optsWrap.style.display = 'flex';
          optsWrap.style.flexDirection = 'column';
          optsWrap.style.gap = '8px';
          var opts = Array.isArray(q.options) ? q.options : [];
          for (var i = 0; i < opts.length; i++) {
            var op = opts[i];
            var lbl = document.createElement('label');
            lbl.className = 'checkbox-card';
            lbl.style.display = 'flex';
            lbl.style.alignItems = 'center';
            lbl.style.gap = '10px';
            lbl.style.margin = '0';

            var inp = document.createElement('input');
            inp.type = isMulti ? 'checkbox' : 'radio';
            inp.name = 'qbank_preview_choice';
            lbl.appendChild(inp);

            var keyStrong = document.createElement('strong');
            keyStrong.textContent = op.optionKey + '.';
            lbl.appendChild(keyStrong);

            var opTextDiv = document.createElement('div');
            opTextDiv.style.flex = '1';
            renderRichTextDocumentToDom(opTextDiv, op.contentRichText, '');
            lbl.appendChild(opTextDiv);

            optsWrap.appendChild(lbl);
          }
          qBox.appendChild(optsWrap);
        } else if (q.questionType === 'NUMERIC_RESPONSE') {
          var numRow = document.createElement('div');
          numRow.style.display = 'flex';
          numRow.style.alignItems = 'center';
          numRow.style.gap = '8px';
          var numInp = document.createElement('input');
          numInp.type = 'text';
          numInp.inputMode = 'decimal';
          numInp.className = 'form-input';
          numInp.style.maxWidth = '220px';
          numInp.placeholder = 'Enter numeric answer...';
          numRow.appendChild(numInp);
          if (q.unitLabel) {
            var uSpan = document.createElement('strong');
            uSpan.textContent = q.unitLabel;
            numRow.appendChild(uSpan);
          }
          qBox.appendChild(numRow);
        } else if (q.questionType === 'SHORT_ANSWER') {
          var saInp = document.createElement('input');
          saInp.type = 'text';
          saInp.className = 'form-input';
          saInp.maxLength = q.maxLengthChars || 300;
          saInp.placeholder = 'Type your concise biological answer...';
          qBox.appendChild(saInp);
        } else if (q.questionType === 'WRITTEN_RESPONSE') {
          var wrTxt = document.createElement('textarea');
          wrTxt.className = 'form-textarea';
          wrTxt.rows = 4;
          wrTxt.maxLength = q.maxLengthChars || 2500;
          wrTxt.placeholder = 'Write your structured biological explanation...';
          qBox.appendChild(wrTxt);
        }

        host.appendChild(qBox);

        /* 4. Admin-Only Answer Key & Explanation Inspector (Shown ONLY when toggled on by Admin) */
        if (currentQBankPreviewShowKeyPhase2 && d.adminGradingPreview) {
          var keyBox = document.createElement('div');
          keyBox.className = 'status-item';
          keyBox.style.marginTop = '14px';
          keyBox.style.background = '#FFFBEB';
          keyBox.style.borderColor = '#F59E0B';

          var kBadge = document.createElement('span');
          kBadge.className = 'badge badge-incomplete';
          kBadge.textContent = 'Private Grading Specification & Explanation (Never Sent to Students Before Release)';
          keyBox.appendChild(kBadge);

          var specPre = document.createElement('pre');
          specPre.style.fontSize = '0.78rem';
          specPre.style.marginTop = '8px';
          specPre.style.whiteSpace = 'pre-wrap';
          specPre.textContent = JSON.stringify(d.adminGradingPreview.gradingSpec, null, 2);
          keyBox.appendChild(specPre);

          if (d.adminGradingPreview.explanationPlainText) {
            var expDiv = document.createElement('div');
            expDiv.style.marginTop = '8px';
            expDiv.style.fontSize = '0.88rem';
            expDiv.textContent = 'Explanation: ' + d.adminGradingPreview.explanationPlainText;
            keyBox.appendChild(expDiv);
          }
          host.appendChild(keyBox);
        }

        PBAdminActionModal.open('admin-question-preview-card', 'Student Preview: ' + (q.questionCode || 'Question'));
      });
    }

    function initExamPhase2QuestionBankBindings() {
      var typeSel = document.getElementById('select-qbank-type');
      if (typeSel) {
        typeSel.addEventListener('change', syncQBankTypePanelsPhase2);
      }

      var symBtns = document.querySelectorAll('[data-insert-bio-symbol]');
      var SYM_MAP = {
        alpha: 'α',
        beta: 'β',
        gamma: 'γ',
        Delta: 'Δ',
        mu: 'μm',
        degC: '°C',
        arrow: ' → ',
        eq: ' ⇌ ',
        H2O: 'H₂O',
        CO2: 'CO₂',
        'NADP+': 'NADP⁺'
      };
      for (var sb = 0; sb < symBtns.length; sb++) {
        (function (btn) {
          btn.addEventListener('click', function () {
            var key = btn.getAttribute('data-insert-bio-symbol');
            var sym = SYM_MAP[key] || key;
            var stemEl = document.getElementById('textarea-qbank-stem');
            if (stemEl) {
              var start = stemEl.selectionStart || stemEl.value.length;
              var end = stemEl.selectionEnd || stemEl.value.length;
              stemEl.value = stemEl.value.slice(0, start) + sym + stemEl.value.slice(end);
              stemEl.focus();
            }
          });
        })(symBtns[sb]);
      }

      var openQModalBtn = document.getElementById('btn-admin-open-qbank-modal');
      if (openQModalBtn) {
        openQModalBtn.addEventListener('click', function () {
          resetQuestionEditorFormPhase2();
          PBAdminActionModal.open('admin-question-editor-card', 'Create New Biology Question (v1)');
        });
      }

      var resetQBtn = document.getElementById('btn-qbank-reset-editor');
      if (resetQBtn) {
        resetQBtn.addEventListener('click', resetQuestionEditorFormPhase2);
      }

      var openStimModalBtn = document.getElementById('btn-admin-open-stimulus-modal');
      if (openStimModalBtn) {
        openStimModalBtn.addEventListener('click', function () {
          var idEl = document.getElementById('input-stimulus-id');
          var verEl = document.getElementById('input-stimulus-expected-version');
          var codeEl = document.getElementById('input-stimulus-code');
          var titleEl = document.getElementById('input-stimulus-title');
          var topEl = document.getElementById('input-stimulus-topics');
          var txtEl = document.getElementById('textarea-stimulus-content');
          if (idEl) idEl.value = '';
          if (verEl) verEl.value = '';
          if (codeEl) codeEl.value = '';
          if (titleEl) titleEl.value = '';
          if (topEl) topEl.value = '';
          if (txtEl) txtEl.value = '';
          PBAdminActionModal.open('admin-stimulus-editor-card', 'Create Shared Biology Stimulus');
        });
      }

      bindActionButton('btn-admin-seed-sample-qbank', function () {
        return rpcCallEnvelope('admin.questions.seedSampleBiologyBank', {}).then(function (env) {
          renderQuestionBankTablePhase2(env.data);
          PBNotify.toast(
            'success',
            'Sample Biology Question Bank Ready',
            'Seeded ' + (env.data.seededCount || 0) + ' new biology questions across all 6 question types.'
          );
        });
      });

      bindActionButton('btn-admin-reload-qbank', function () {
        return loadAdminQuestionBankPhase2(1);
      });

      var filterForm = document.getElementById('form-admin-qbank-filter');
      if (filterForm) {
        filterForm.addEventListener('submit', function (evt) {
          evt.preventDefault();
          loadAdminQuestionBankPhase2(1);
        });
      }

      var clearFilterBtn = document.getElementById('btn-qbank-clear-filter');
      if (clearFilterBtn) {
        clearFilterBtn.addEventListener('click', function () {
          var sInp = document.getElementById('input-qbank-search');
          var topSel = document.getElementById('select-qbank-topic-filter');
          var typSel = document.getElementById('select-qbank-type-filter');
          var difSel = document.getElementById('select-qbank-difficulty-filter');
          var stSel = document.getElementById('select-qbank-status-filter');
          if (sInp) sInp.value = '';
          if (topSel) topSel.value = 'ALL';
          if (typSel) typSel.value = 'ALL';
          if (difSel) difSel.value = 'ALL';
          if (stSel) stSel.value = 'ALL';
          loadAdminQuestionBankPhase2(1);
        });
      }

      var prevBtn = document.getElementById('btn-qbank-prev-page');
      if (prevBtn) {
        prevBtn.addEventListener('click', function () {
          if (currentQBankPagePhase2 > 1) {
            loadAdminQuestionBankPhase2(currentQBankPagePhase2 - 1);
          }
        });
      }
      var nextBtn = document.getElementById('btn-qbank-next-page');
      if (nextBtn) {
        nextBtn.addEventListener('click', function () {
          loadAdminQuestionBankPhase2(currentQBankPagePhase2 + 1);
        });
      }

      var toggleKeyBtn = document.getElementById('btn-qbank-preview-toggle-key');
      if (toggleKeyBtn) {
        toggleKeyBtn.addEventListener('click', function () {
          if (currentQBankPreviewQuestionIdPhase2) {
            openQuestionStudentPreviewModalPhase2(
              currentQBankPreviewQuestionIdPhase2,
              !currentQBankPreviewShowKeyPhase2
            );
          }
        });
      }

      var addOptBtn = document.getElementById('btn-qbank-add-option-row');
      if (addOptBtn && !(addOptBtn.dataset && addOptBtn.dataset.boundOpt)) {
        if (addOptBtn.dataset) addOptBtn.dataset.boundOpt = '1';
        addOptBtn.addEventListener('click', function () {
          if (currentQBankActiveOptionCountPhase2 >= 10) {
            PBNotify.toast('warning', 'Maximum Options Reached', 'A question can have up to 10 answer choices (A–J).');
            return;
          }
          setQBankOptionRowCountPhase2(currentQBankActiveOptionCountPhase2 + 1);
        });
      }

      var rmLastOptBtn = document.getElementById('btn-qbank-remove-last-option-row');
      if (rmLastOptBtn && !(rmLastOptBtn.dataset && rmLastOptBtn.dataset.boundOpt)) {
        if (rmLastOptBtn.dataset) rmLastOptBtn.dataset.boundOpt = '1';
        rmLastOptBtn.addEventListener('click', function () {
          if (currentQBankActiveOptionCountPhase2 <= 2) {
            PBNotify.toast('warning', 'Minimum Options Reached', 'At least 2 answer choices (A and B) are required.');
            return;
          }
          setQBankOptionRowCountPhase2(currentQBankActiveOptionCountPhase2 - 1);
        });
      }

      var imgIdInputEl = document.getElementById('input-qbank-image-id');
      if (imgIdInputEl && !(imgIdInputEl.dataset && imgIdInputEl.dataset.boundImgSync)) {
        if (imgIdInputEl.dataset) imgIdInputEl.dataset.boundImgSync = '1';
        imgIdInputEl.addEventListener('change', function () {
          setQBankEditorImagesListPhase2(imgIdInputEl.value);
        });
      }

      var previewImgsBtn = document.getElementById('btn-qbank-preview-images-refresh');
      if (previewImgsBtn && !(previewImgsBtn.dataset && previewImgsBtn.dataset.boundImgSync)) {
        if (previewImgsBtn.dataset) previewImgsBtn.dataset.boundImgSync = '1';
        previewImgsBtn.addEventListener('click', function () {
          var inp = document.getElementById('input-qbank-image-id');
          setQBankEditorImagesListPhase2(inp ? inp.value : '');
        });
      }

      var clearImgsBtn = document.getElementById('btn-qbank-clear-images');
      if (clearImgsBtn && !(clearImgsBtn.dataset && clearImgsBtn.dataset.boundImgSync)) {
        if (clearImgsBtn.dataset) clearImgsBtn.dataset.boundImgSync = '1';
        clearImgsBtn.addEventListener('click', function () {
          setQBankEditorImagesListPhase2([]);
        });
      }

      var qImgFileInput = document.getElementById('input-qbank-image-file');
      if (qImgFileInput && !(qImgFileInput.dataset && qImgFileInput.dataset.boundAutoPreview)) {
        if (qImgFileInput.dataset) qImgFileInput.dataset.boundAutoPreview = '1';
        qImgFileInput.addEventListener('change', function () {
          var upBtn = document.getElementById('btn-qbank-upload-image');
          if (qImgFileInput.files && qImgFileInput.files.length > 0 && upBtn) {
            upBtn.click();
          }
        });
      }

      bindActionButton('btn-qbank-upload-image', function () {
        var fileInp = document.getElementById('input-qbank-image-file');
        var filesList = fileInp && fileInp.files ? Array.prototype.slice.call(fileInp.files) : [];
        if (filesList.length === 0) {
          PBNotify.toast('warning', 'No Image Selected', 'Please choose one or more image files to upload.');
          return Promise.resolve();
        }
        // Sync any manually typed IDs first
        var manualInp = document.getElementById('input-qbank-image-id');
        if (manualInp && manualInp.value.trim()) {
          currentQBankEditorImageIdsPhase2 = parseClientImageFileIdsListPhase2(manualInp.value);
        }
        var chain = Promise.resolve();
        var uploadedIds = [];
        for (var fIdx = 0; fIdx < filesList.length; fIdx++) {
          (function (fileObj) {
            chain = chain.then(function () {
              return readBrowserFileAsBase64Step8(fileObj).then(function (fData) {
                return rpcCallEnvelope('admin.uploadFile', {
                  purpose: 'QUESTION_IMAGE',
                  originalFilename: fData.originalFilename,
                  mimeType: fData.mimeType,
                  dataBase64: fData.dataBase64
                }).then(function (env) {
                  var fid = env.data && env.data.file && env.data.file.fileId;
                  if (fid) {
                    uploadedIds.push(fid);
                    var localUrl = 'data:' + fData.mimeType + ';base64,' + fData.dataBase64;
                    appendQBankEditorImageIdPhase2(fid, localUrl);
                  }
                });
              });
            });
          })(filesList[fIdx]);
        }
        return chain.then(function () {
          if (fileInp) fileInp.value = '';
          PBNotify.toast(
            'success',
            'Question Diagram(s) Uploaded',
            'Added ' + uploadedIds.length + ' image(s): ' + uploadedIds.join(', ')
          );
        });
      });

      var qEditorForm = document.getElementById('form-admin-question-editor');
      if (qEditorForm) {
        qEditorForm.addEventListener('submit', function (evt) {
          evt.preventDefault();
          var qId = (document.getElementById('input-qbank-question-id') || {}).value || '';
          var expVer = (document.getElementById('input-qbank-expected-version') || {}).value || '';
          var qType = (document.getElementById('select-qbank-type') || {}).value || 'SINGLE_CHOICE';

          var optionsPayload = [];
          if (qType === 'SINGLE_CHOICE' || qType === 'MULTIPLE_SELECT' || qType === 'TRUE_FALSE') {
            var maxO = qType === 'TRUE_FALSE' ? 2 : Math.min(10, Math.max(2, currentQBankActiveOptionCountPhase2));
            for (var i = 0; i < maxO; i++) {
              var txt = ((document.getElementById('input-qbank-opt-text-' + i) || {}).value || '').trim();
              var chk = Boolean((document.getElementById('chk-qbank-opt-correct-' + i) || {}).checked);
              var pin = (document.getElementById('select-qbank-opt-pin-' + i) || {}).value || 'NONE';
              if (txt) {
                optionsPayload.push({
                  optionKey: qType === 'TRUE_FALSE' ? (i === 0 ? 'TRUE' : 'FALSE') : String.fromCharCode(65 + i),
                  text: txt,
                  isCorrect: chk,
                  pinPosition: pin
                });
              }
            }
          }

          var rawImgField = (document.getElementById('input-qbank-image-id') || {}).value || '';
          var imgIdsList = parseClientImageFileIdsListPhase2(
            rawImgField || currentQBankEditorImageIdsPhase2
          );

          var payload = {
            questionId: qId,
            expectedVersion: expVer ? Number(expVer) : undefined,
            questionCode: (document.getElementById('input-qbank-code') || {}).value || '',
            title: (document.getElementById('input-qbank-title') || {}).value || '',
            questionType: qType,
            difficulty: (document.getElementById('select-qbank-difficulty') || {}).value || 'MEDIUM',
            defaultPoints: (document.getElementById('input-qbank-points') || {}).value || '1',
            negativePoints: (document.getElementById('input-qbank-neg-points') || {}).value || '0',
            topicTags: (document.getElementById('input-qbank-topics') || {}).value || '',
            status: (document.getElementById('select-qbank-status') || {}).value || 'PUBLISHED',
            stimulusId: (document.getElementById('select-qbank-stimulus') || {}).value || '',
            stemRichText: (document.getElementById('textarea-qbank-stem') || {}).value || '',
            imageFileId: imgIdsList.join(','),
            imageFileIds: imgIdsList,
            imageAltText: (document.getElementById('input-qbank-image-alt') || {}).value || '',
            accessibleDesignFlag: (document.getElementById('select-qbank-accessible-flag') || {}).value || 'STANDARD_ALT',
            options: optionsPayload,
            multiSelectScoringRule: (document.getElementById('select-qbank-multiselect-rule') || {}).value || 'EXACT_MATCH',
            unitLabel: (document.getElementById('input-qbank-num-unit') || {}).value || '',
            numericSpec: {
              matchMode: (document.getElementById('select-qbank-num-mode') || {}).value || 'EXACT_WITH_TOLERANCE',
              targetValue: (document.getElementById('input-qbank-num-target') || {}).value || '',
              toleranceType: (document.getElementById('select-qbank-num-tol-type') || {}).value || 'ABSOLUTE',
              toleranceValue: (document.getElementById('input-qbank-num-tol-val') || {}).value || '0',
              roundingDecimals: (document.getElementById('input-qbank-num-rounding') || {}).value || '',
              rangeMin: (document.getElementById('input-qbank-num-min') || {}).value || '',
              rangeMax: (document.getElementById('input-qbank-num-max') || {}).value || ''
            },
            gradingMode: (document.getElementById('select-qbank-sa-grading-mode') || {}).value || 'MANUAL',
            maxLengthChars: Number((document.getElementById('input-qbank-max-chars') || {}).value || 1500),
            acceptedAnswers: (document.getElementById('textarea-qbank-accepted-answers') || {}).value || '',
            sampleModelAnswer: (document.getElementById('textarea-qbank-rubric-model') || {}).value || '',
            explanationRichText: (document.getElementById('textarea-qbank-explanation') || {}).value || '',
            referenceText: (document.getElementById('input-qbank-reference') || {}).value || '',
            adminNotes: (document.getElementById('input-qbank-admin-notes') || {}).value || ''
          };

          setText('qbank-editor-status', 'Saving question version...');
          var qSubBtn = qEditorForm.querySelector('button[type="submit"]');
          runButtonWithLoadingState(qSubBtn, 'Saving Question...', function () {
            return rpcCallEnvelope('admin.questions.save', payload)
            .then(function (env) {
              invalidateQBankClientCachePhase2();
              renderQuestionBankTablePhase2(env.data);
              PBAdminActionModal.close();
              PBNotify.toast(
                'success',
                'Question Saved',
                'Saved ' + env.data.question.questionCode + ' (Immutable v' + env.data.question.versionNo + ').'
              );
            })
            .catch(function (err) {
              setText('qbank-editor-status', 'Error: ' + ((err && err.message) || 'Failed to save question.'));
            });
          });
        });
      }

      var stimForm = document.getElementById('form-admin-stimulus-editor');
      if (stimForm) {
        stimForm.addEventListener('submit', function (evt) {
          evt.preventDefault();
          var stId = (document.getElementById('input-stimulus-id') || {}).value || '';
          var expVer = (document.getElementById('input-stimulus-expected-version') || {}).value || '';
          var payload = {
            stimulusId: stId,
            expectedVersion: expVer ? Number(expVer) : undefined,
            stimulusCode: (document.getElementById('input-stimulus-code') || {}).value || '',
            title: (document.getElementById('input-stimulus-title') || {}).value || '',
            topicTags: (document.getElementById('input-stimulus-topics') || {}).value || '',
            status: (document.getElementById('select-stimulus-status') || {}).value || 'PUBLISHED',
            contentRichText: (document.getElementById('textarea-stimulus-content') || {}).value || ''
          };
          setText('stimulus-editor-status', 'Saving shared stimulus...');
          rpcCallEnvelope('admin.stimuli.save', payload)
            .then(function () {
              PBAdminActionModal.close();
              loadAdminQuestionBankPhase2(currentQBankPagePhase2);
              PBNotify.toast('success', 'Shared Stimulus Saved', 'Stimulus updated in library.');
            })
            .catch(function (err) {
              setText('stimulus-editor-status', 'Error: ' + ((err && err.message) || 'Failed to save stimulus.'));
            });
        });
      }
    }

