    function populateAdminExamBuilderCourseAndStudentDropdownsPhase3() {
      var courses =
        Array.isArray(currentAdminCoursesList) && currentAdminCoursesList.length > 0
          ? currentAdminCoursesList
          : Array.isArray(currentAdminAvailableCourses)
          ? currentAdminAvailableCourses
          : [];
      var users =
        Array.isArray(currentAdminUsersCache)
          ? currentAdminUsersCache
          : [];

      var courseSelectIds = [
        'select-admin-exams-course-filter',
        'select-exam-editor-course',
        'select-exam-assign-course',
        'select-forms-exam-course'
      ];
      for (var s = 0; s < courseSelectIds.length; s++) {
        var sel = document.getElementById(courseSelectIds[s]);
        if (!sel) continue;
        var prevVal = sel.value;
        while (sel.firstChild) sel.removeChild(sel.firstChild);
        var firstOpt = document.createElement('option');
        firstOpt.value = courseSelectIds[s] === 'select-admin-exams-course-filter' ? 'ALL' : '';
        firstOpt.textContent =
          courseSelectIds[s] === 'select-admin-exams-course-filter'
            ? 'All Courses'
            : '-- Select Course --';
        sel.appendChild(firstOpt);
        for (var c = 0; c < courses.length; c++) {
          var opt = document.createElement('option');
          opt.value = courses[c].courseId;
          opt.textContent = (courses[c].courseCode || '') + ' - ' + (courses[c].title || '');
          sel.appendChild(opt);
        }
        if (prevVal) sel.value = prevVal;
      }

      var stuSel = document.getElementById('select-exam-assign-student');
      if (stuSel) {
        var prevStu = stuSel.value;
        while (stuSel.firstChild) stuSel.removeChild(stuSel.firstChild);
        var dOpt = document.createElement('option');
        dOpt.value = '';
        dOpt.textContent = '-- Select Student Account --';
        stuSel.appendChild(dOpt);
        for (var u = 0; u < users.length; u++) {
          if (users[u].role !== 'STUDENT') continue;
          var uOpt = document.createElement('option');
          uOpt.value = users[u].userId;
          uOpt.textContent =
            (users[u].usernameDisplay || users[u].username || '') +
            ' (' +
            (users[u].fullName || '') +
            ')';
          stuSel.appendChild(uOpt);
        }
        if (prevStu) stuSel.value = prevStu;
      }
    }

    function renderExamEditorSelectedImagesGalleryPhase3() {
      var gallery = document.getElementById('exam-editor-selected-images-gallery');
      var countBadge = document.getElementById('exam-editor-images-count-badge');
      var host = document.getElementById('admin-exam-sec1-questions-checklist');
      if (!gallery) return;
      clearChildren(gallery);

      var selectedMap = {};
      if (host) {
        var chks = host.querySelectorAll('input[data-exam-sec1-q-id]');
        for (var c = 0; c < chks.length; c++) {
          if (chks[c].checked) {
            selectedMap[chks[c].getAttribute('data-exam-sec1-q-id')] = true;
          }
        }
      }

      var questions = Array.isArray(currentQBankQuestionsPhase2) ? currentQBankQuestionsPhase2 : [];
      var imageEntries = [];
      for (var i = 0; i < questions.length; i++) {
        var q = questions[i];
        if (!selectedMap[q.questionId]) continue;
        var qImgs = Array.isArray(q.imageFileIds) && q.imageFileIds.length > 0
          ? q.imageFileIds
          : (q.imageFileId ? parseClientImageFileIdsListPhase2(q.imageFileId) : []);
        for (var j = 0; j < qImgs.length; j++) {
          imageEntries.push({
            questionId: q.questionId,
            questionCode: q.questionCode,
            questionTitle: q.title,
            imageAltText: q.imageAltText || q.title || 'Question Diagram',
            fileId: qImgs[j],
            imageIndexInQuestion: j + 1,
            totalInQuestion: qImgs.length
          });
        }
      }

      if (countBadge) {
        countBadge.textContent =
          String(imageEntries.length) +
          (imageEntries.length === 1 ? ' Diagram in Exam' : ' Diagrams in Exam');
      }

      for (var k = 0; k < imageEntries.length; k++) {
        (function (entry, cardIdx) {
          var card = document.createElement('div');
          card.className = 'pb-qbank-image-card';

          var hdr = document.createElement('div');
          hdr.style.display = 'flex';
          hdr.style.alignItems = 'center';
          hdr.style.justifyContent = 'space-between';
          hdr.style.gap = '6px';
          hdr.style.marginBottom = '8px';

          var bdg = document.createElement('span');
          bdg.className = 'badge badge-ok';
          bdg.textContent =
            entry.questionCode +
            (entry.totalInQuestion > 1 ? ' (Img ' + entry.imageIndexInQuestion + ')' : '');
          hdr.appendChild(bdg);

          var codeEl = document.createElement('code');
          codeEl.style.fontSize = '0.73rem';
          codeEl.textContent = entry.fileId;
          hdr.appendChild(codeEl);
          card.appendChild(hdr);

          var stg = document.createElement('div');
          stg.className = 'pb-qbank-image-thumb-stage';
          card.appendChild(stg);

          var cap = document.createElement('div');
          cap.style.fontSize = '0.76rem';
          cap.style.fontWeight = '600';
          cap.style.color = 'var(--color-text-secondary)';
          cap.textContent = entry.questionTitle;
          card.appendChild(cap);

          gallery.appendChild(card);
          renderDirectImageElementIntoStage(stg, entry.fileId, '', entry.imageAltText);
        })(imageEntries[k], k);
      }
    }

    function renderExamBuilderQuestionChecklistPhase3(selectedQuestionIdsMap) {
      var host = document.getElementById('admin-exam-sec1-questions-checklist');
      if (!host) return;
      while (host.firstChild) host.removeChild(host.firstChild);

      var questions = Array.isArray(currentQBankQuestionsPhase2) ? currentQBankQuestionsPhase2 : [];
      if (questions.length === 0) {
        var emptyP = document.createElement('p');
        emptyP.style.margin = '4px 0';
        emptyP.style.fontSize = '0.84rem';
        emptyP.style.color = 'var(--color-text-muted)';
        emptyP.textContent =
          'No questions loaded in Question Bank yet. Click "Load Sample Questions" in the Question Bank tab first.';
        host.appendChild(emptyP);
        renderExamEditorSelectedImagesGalleryPhase3();
        return;
      }

      var selMap = selectedQuestionIdsMap || {};
      for (var i = 0; i < questions.length; i++) {
        (function (q) {
          if (q.status === 'ARCHIVED') return;
          var rowWrap = document.createElement('div');
          rowWrap.className = 'pb-exam-q-check-item';

          var leftLabel = document.createElement('label');
          leftLabel.style.display = 'flex';
          leftLabel.style.alignItems = 'center';
          leftLabel.style.gap = '10px';
          leftLabel.style.flex = '1';
          leftLabel.style.cursor = 'pointer';

          var chk = document.createElement('input');
          chk.type = 'checkbox';
          chk.setAttribute('data-exam-sec1-q-id', q.questionId);
          chk.checked = Boolean(selMap[q.questionId]);
          chk.addEventListener('change', function () {
            renderExamEditorSelectedImagesGalleryPhase3();
          });
          leftLabel.appendChild(chk);

          var qImgs = Array.isArray(q.imageFileIds) && q.imageFileIds.length > 0
            ? q.imageFileIds
            : (q.imageFileId ? parseClientImageFileIdsListPhase2(q.imageFileId) : []);
          if (qImgs.length > 0) {
            var thumbBox = document.createElement('span');
            thumbBox.className = 'pb-exam-q-check-thumb';
            leftLabel.appendChild(thumbBox);
            renderDirectImageElementIntoStage(thumbBox, qImgs[0], '', q.imageAltText || q.title);
          }

          var infoSpan = document.createElement('span');
          infoSpan.style.fontSize = '0.86rem';
          infoSpan.textContent =
            '[' +
            q.questionCode +
            '] ' +
            q.title +
            ' (' +
            q.questionType +
            ', ' +
            (q.defaultPointsDisplay || '1 pt') +
            (qImgs.length > 0 ? ', ' + qImgs.length + ' img' : '') +
            ')';
          leftLabel.appendChild(infoSpan);
          rowWrap.appendChild(leftLabel);

          var qPrevBtn = document.createElement('button');
          qPrevBtn.type = 'button';
          qPrevBtn.className = 'btn btn-outline btn-sm';
          qPrevBtn.style.minHeight = '30px';
          qPrevBtn.style.padding = '3px 10px';
          qPrevBtn.style.fontSize = '0.76rem';
          qPrevBtn.textContent = 'Preview';
          qPrevBtn.addEventListener('click', function (evt) {
            evt.preventDefault();
            evt.stopPropagation();
            runButtonWithLoadingState(qPrevBtn, 'Loading...', function () {
              return openQuestionStudentPreviewModalPhase2(q.questionId, false);
            });
          });
          rowWrap.appendChild(qPrevBtn);

          host.appendChild(rowWrap);
        })(questions[i]);
      }
      renderExamEditorSelectedImagesGalleryPhase3();
    }

    function syncExamAttemptPolicyPairFromCount(policySelId, countInpId, pairWrapId, rawCount) {
      var policySel = document.getElementById(policySelId);
      var countInp = document.getElementById(countInpId);
      var pairWrap = document.getElementById(pairWrapId);
      var n = parseInt(rawCount, 10);
      if (isNaN(n) || n < 0) n = 1;
      if (n > 100) n = 100;

      if (policySel) {
        if (n === 0) {
          policySel.value = 'MULTIPLE_UNLIMITED';
        } else if (n === 1) {
          policySel.value = 'SINGLE';
        } else {
          policySel.value = 'MULTIPLE_LIMITED';
        }
      }
      if (countInp) {
        countInp.value = String(n);
        var isLimited = n >= 2;
        countInp.classList.toggle('hidden', !isLimited);
        countInp.disabled = !isLimited;
      }
      if (pairWrap) {
        pairWrap.classList.toggle('is-fixed-count', n < 2);
      }
    }

    function readExamAttemptPolicyCountValue(policySelId, countInpId, examMode) {
      var policySel = document.getElementById(policySelId);
      var countInp = document.getElementById(countInpId);
      var pol = policySel ? policySel.value : '';
      if (pol === 'SINGLE') {
        return '1';
      }
      if (pol === 'MULTIPLE_UNLIMITED') {
        return '0';
      }
      if (pol === 'MULTIPLE_LIMITED') {
        var lim = parseInt(countInp ? countInp.value : '2', 10);
        if (isNaN(lim) || lim < 2) lim = 2;
        if (lim > 100) lim = 100;
        return String(lim);
      }
      if (countInp && String(countInp.value).trim() !== '') {
        return String(countInp.value);
      }
      return examMode === 'PRACTICE' ? '0' : '1';
    }

    function bindExamAttemptPolicyPair(policySelId, countInpId, pairWrapId, modeSelId, examIdInputId) {
      var policySel = document.getElementById(policySelId);
      var countInp = document.getElementById(countInpId);
      var modeSel = document.getElementById(modeSelId);
      var pairWrap = document.getElementById(pairWrapId);

      if (policySel && !(policySel.dataset && policySel.dataset.boundAttPol)) {
        if (policySel.dataset) policySel.dataset.boundAttPol = '1';
        policySel.addEventListener('change', function () {
          if (policySel.dataset) policySel.dataset.userTouched = '1';
          var pol = policySel.value;
          if (pol === 'SINGLE') {
            if (countInp) countInp.value = '1';
            syncExamAttemptPolicyPairFromCount(policySelId, countInpId, pairWrapId, 1);
          } else if (pol === 'MULTIPLE_UNLIMITED') {
            if (countInp) countInp.value = '0';
            syncExamAttemptPolicyPairFromCount(policySelId, countInpId, pairWrapId, 0);
          } else {
            var cur = parseInt(countInp ? countInp.value : '3', 10);
            var target = !isNaN(cur) && cur >= 2 ? cur : 3;
            if (countInp) countInp.value = String(target);
            syncExamAttemptPolicyPairFromCount(policySelId, countInpId, pairWrapId, target);
            if (countInp && !countInp.disabled) {
              try {
                countInp.focus();
                countInp.select();
              } catch (e) {}
            }
          }
        });
      }

      if (countInp && !(countInp.dataset && countInp.dataset.boundAttCnt)) {
        if (countInp.dataset) countInp.dataset.boundAttCnt = '1';
        countInp.addEventListener('blur', function () {
          if (policySel && policySel.value === 'MULTIPLE_LIMITED') {
            var v = parseInt(countInp.value, 10);
            if (isNaN(v) || v < 2) v = 2;
            if (v > 100) v = 100;
            countInp.value = String(v);
          }
        });
        countInp.addEventListener('input', function () {
          if (policySel && policySel.dataset) policySel.dataset.userTouched = '1';
        });
      }

      if (modeSel && !(modeSel.dataset && modeSel.dataset.boundAttMode)) {
        if (modeSel.dataset) modeSel.dataset.boundAttMode = '1';
        modeSel.addEventListener('change', function () {
          var existingId = ((document.getElementById(examIdInputId) || {}).value || '').trim();
          var userTouched = policySel && policySel.dataset && policySel.dataset.userTouched === '1';
          if (existingId || userTouched) {
            return;
          }
          if (modeSel.value === 'PRACTICE') {
            syncExamAttemptPolicyPairFromCount(policySelId, countInpId, pairWrapId, 0);
          } else {
            syncExamAttemptPolicyPairFromCount(policySelId, countInpId, pairWrapId, 1);
          }
        });
      }

      if (pairWrap && policySel) {
        syncExamAttemptPolicyPairFromCount(
          policySelId,
          countInpId,
          pairWrapId,
          countInp ? countInp.value : 1
        );
      }
    }

