      /* Warning-Banner-Free #sandboxFrame Embed Wrapper Generator */
      function buildSandboxFrameEmbedSnippet(rawSrcUrl, opt_cropTopBanner) {
        var cleanSrc = String(rawSrcUrl || '').trim();
        if (!cleanSrc || cleanSrc.indexOf('/userCodeAppPanel') !== -1) {
          cleanSrc = 'https://script.google.com/macros/s/YOUR_DEPLOYMENT_ID/exec';
        } else if (/\/dev(|\?|#|$)/.test(cleanSrc)) {
          cleanSrc = cleanSrc.replace(/\/dev(|\?|#|$)/, '/exec$1');
        }
        var cropChk = document.getElementById('chk-admin-sandbox-crop-banner');
        var useCrop =
          opt_cropTopBanner !== undefined
            ? Boolean(opt_cropTopBanner)
            : Boolean(cropChk && cropChk.checked);
        var frameStyle = useCrop
          ? 'position:fixed;left:0;right:0;top:-38px;width:100%;height:calc(100dvh + 38px);border:0;margin:0;padding:0;'
          : 'position:fixed;inset:0;width:100%;height:100dvh;border:0;margin:0;padding:0;';
        var openTag = '<' + 'iframe';
        var closeTag = '</' + 'iframe>';
        return (
          '<!DOCTYPE html>\n<html lang="en">\n<head>\n  <meta charset="UTF-8" />\n  <meta name="viewport" content="width=device-width, initial-scale=1.0, viewport-fit=cover" />\n  <title>Pattanabhumi Biology — Learning Portal</title>\n  <style>html,body{margin:0;padding:0;width:100%;height:100%;overflow:hidden;background:#F4FAFC;}</style>\n</head>\n<body>\n  ' +
          openTag +
          ' id="sandboxFrame" title="Pattanabhumi Biology — Learning Portal"' +
          ' style="' + frameStyle + '"' +
          ' allow="accelerometer *; autoplay *; camera *; clipboard-read *; clipboard-write *; encrypted-media *; fullscreen *; geolocation *; gyroscope *; local-network-access *; magnetometer *; microphone *; midi *; payment *; picture-in-picture *; screen-wake-lock *; sync-xhr *; usb *; web-share *"' +
          ' sandbox="allow-downloads allow-forms allow-modals allow-popups allow-popups-to-escape-sandbox allow-same-origin allow-scripts allow-top-navigation-by-user-activation allow-storage-access-by-user-activation"' +
          ' src="' + cleanSrc.replace(/"/g, '&quot;') + '">' +
          closeTag +
          '\n</body>\n</html>'
        );
      }

      var sandboxSrcInp = document.getElementById('input-admin-sandbox-iframe-src');
